export default "land\\n\ud83c\uddf3\ud83c\uddec\\tNigeria\\n\ud83c\uddf3\ud83c\uddee\\tNicaragua\\n\ud83c\uddf3\ud83c\uddf1\\tNetherlands\\n\ud83c\uddf3\ud83c\uddf4\\tNorway\\n\ud83c\uddf3\ud83c\uddf5\\tNepal\\n\ud83c\uddf3\ud83c\uddf7\\tNauru\\n\ud83c\uddf3\ud83c\uddfa\\tNiue\\n\ud83c\uddf3\ud83c\uddff\\tNew Zealand\\n\ud83c\uddf4\ud83c\uddf2\\tOman\\n\ud83c\uddf5\ud83c\udde6\\tPanama\\n\ud83c\uddf5\ud83c\uddea\\tPeru\\n\ud83c\uddf5\ud83c\uddeb\\tFrench Polynesia\\n\ud83c\uddf5\ud83c\uddec\\tPapua New Guinea\\n\ud83c\uddf5\ud83c\udded\\tPhilippines\\n\ud83c\uddf5\ud83c\uddf0\\tPakistan\\n\ud83c\uddf5\ud83c\uddf1\\tPoland\\n\ud83c\uddf5\ud83c\uddf2\\tSt. Pierre & Miquelon\\n\ud83c\uddf5\ud83c\uddf3\\tPitcairn Islands\\n\ud83c\uddf5\ud83c\uddf7\\tPuerto Rico\\n\ud83c\uddf5\ud83c\uddf8\\tPalestinian Territories\\n\ud83c\uddf5\ud83c\uddf9\\tPortugal\\n\ud83c\uddf5\ud83c\uddfc\\tPalau\\n\ud83c\uddf5\ud83c\uddfe\\tParaguay\\n\ud83c\uddf6\ud83c\udde6\\tQatar\\n\ud83c\uddf7\ud83c\uddea\\tR\u00e9union\\n\ud83c\uddf7\ud83c\uddf4\\tRomania\\n\ud83c\uddf7\ud83c\uddf8\\tSerbia\\n\ud83c\uddf7\ud83c\uddfa\\tRussia\\n\ud83c\uddf7\ud83c\uddfc\\tRwanda\\n\ud83c\uddf8\ud83c\udde6\\tSaudi Arabia\\n\ud83c\uddf8\ud83c\udde7\\tSolomon Islands\\n\ud83c\uddf8\ud83c\udde8\\tSeychelles\\n\ud83c\uddf8\ud83c\udde9\\tSudan\\n\ud83c\uddf8\ud83c\uddea\\tSweden\\n\ud83c\uddf8\ud83c\uddec\\tSingapore\\n\ud83c\uddf8\ud83c\udded\\tSt. Helena\\n\ud83c\uddf8\ud83c\uddee\\tSlovenia\\n\ud83c\uddf8\ud83c\uddef\\tSvalbard & Jan Mayen\\n\ud83c\uddf8\ud83c\uddf0\\tSlovakia\\n\ud83c\uddf8\ud83c\uddf1\\tSierra Leone\\n\ud83c\uddf8\ud83c\uddf2\\tSan Marino\\n\ud83c\uddf8\ud83c\uddf3\\tSenegal\\n\ud83c\uddf8\ud83c\uddf4\\tSomalia\\n\ud83c\uddf8\ud83c\uddf7\\tSuriname\\n\ud83c\uddf8\ud83c\uddf8\\tSouth Sudan\\n\ud83c\uddf8\ud83c\uddf9\\tS\u00e3o Tom\u00e9 & Pr\u00edncipe\\n\ud83c\uddf8\ud83c\uddfb\\tEl Salvador\\n\ud83c\uddf8\ud83c\uddfd\\tSint Maarten\\n\ud83c\uddf8\ud83c\uddfe\\tSyria\\n\ud83c\uddf8\ud83c\uddff\\tSwaziland\\n\ud83c\uddf9\ud83c\udde6\\tTristan da Cunha\\n\ud83c\uddf9\ud83c\udde8\\tTurks & Caicos Islands\\n\ud83c\uddf9\ud83c\udde9\\tChad\\n\ud83c\uddf9\ud83c\uddeb\\tFrench Southern Territories\\n\ud83c\uddf9\ud83c\uddec\\tTogo\\n\ud83c\uddf9\ud83c\udded\\tThailand\\n\ud83c\uddf9\ud83c\uddef\\tTajikistan\\n\ud83c\uddf9\ud83c\uddf0\\tTokelau\\n\ud83c\uddf9\ud83c\uddf1\\tTimor-Leste\\n\ud83c\uddf9\ud83c\uddf2\\tTurkmenistan\\n\ud83c\uddf9\ud83c\uddf3\\tTunisia\\n\ud83c\uddf9\ud83c\uddf4\\tTonga\\n\ud83c\uddf9\ud83c\uddf7\\tTurkey\\n\ud83c\uddf9\ud83c\uddf9\\tTrinidad & Tobago\\n\ud83c\uddf9\ud83c\uddfb\\tTuvalu\\n\ud83c\uddf9\ud83c\uddfc\\tTaiwan\\n\ud83c\uddf9\ud83c\uddff\\tTanzania\\n\ud83c\uddfa\ud83c\udde6\\tUkraine\\n\ud83c\uddfa\ud83c\uddec\\tUganda\\n\ud83c\uddfa\ud83c\uddf2\\tU.S. Outlying Islands\\n\ud83c\uddfa\ud83c\uddf3\\tUnited Nations\\n\ud83c\uddfa\ud83c\uddf8\\tUnited States\\n\ud83c\uddfa\ud83c\uddfe\\tUruguay\\n\ud83c\uddfa\ud83c\uddff\\tUzbekistan\\n\ud83c\uddfb\ud83c\udde6\\tVatican City\\n\ud83c\uddfb\ud83c\udde8\\tSt. Vincent & Grenadines\\n\ud83c\uddfb\ud83c\uddea\\tVenezuela\\n\ud83c\uddfb\ud83c\uddec\\tBritish Virgin Islands\\n\ud83c\uddfb\ud83c\uddee\\tU.S. Virgin Islands\\n\ud83c\uddfb\ud83c\uddf3\\tVietnam\\n\ud83c\uddfb\ud83c\uddfa\\tVanuatu\\n\ud83c\uddfc\ud83c\uddeb\\tWallis & Futuna\\n\ud83c\uddfc\ud83c\uddf8\\tSamoa\\n\ud83c\uddfd\ud83c\uddf0\\tKosovo\\n\ud83c\uddfe\ud83c\uddea\\tYemen\\n\ud83c\uddfe\ud83c\uddf9\\tMayotte\\n\ud83c\uddff\ud83c\udde6\\tSouth Africa\\n\ud83c\uddff\ud83c\uddf2\\tZambia\\n\ud83c\uddff\ud83c\uddfc\\tZimbabwe\\n\ud83c\udff4\udb40\udc67\udb40\udc62\udb40\udc65\udb40\udc6e\udb40\udc67\udb40\udc7f\\tEngland\\n\ud83c\udff4\udb40\udc67\udb40\udc62\udb40\udc73\udb40\udc63\udb40\udc74\udb40\udc7f\\tScotland\\n\ud83c\udff4\udb40\udc67\udb40\udc62\udb40\udc77\udb40\udc6c\udb40\udc73\udb40\udc7f\\tWales\"},{\"source_archive\":\"Unified_Psychiatric_AI_Brain_Part1.zip\",\"source_path\":\"source_projects/Virtual-Psychiatrist-master/Virtual-Psychiatrist-master/Backend/resources/vaderSentiment/__init__.py\",\"language\":\"py\",\"content\":\"#!/usr/bin/python\"},{\"source_archive\":\"Unified_Psychiatric_AI_Brain_Part1.zip\",\"source_path\":\"source_projects/Virtual-Psychiatrist-master/Virtual-Psychiatrist-master/Backend/resources/TextSentiment.py\",\"language\":\"py\",\"content\":\"from flask import jsonify\\nfrom flask_restful import Resource, reqparse\\nfrom resources.vaderSentiment.vaderSentiment import SentimentIntensityAnalyzer\\n\\nanalyser = SentimentIntensityAnalyzer()\\n# UPDATING THE VADER DICTIONARY WITH NEW WORDS ALONG WITH THEIR SCORES!\\nnew_words = {\\n    'afraid': -1.0\\n}\\nanalyser.lexicon.update(new_words)\\n\\nsentiment_args = reqparse.RequestParser()\\nsentiment_args.add_argument(\\\"text\\\",  type = str, help = \\\"Text parameter missing.\\\", required = True)\\n\\ndef sentiment_string(score):\\n    positive = float(score['pos'])\\n    negative = float(score['neg'])\\n    compound = float(score['compound'])\\n    neutral  = float(score['neu'])\\n    \\n    if positive > negative and positive > compound and positive > neutral:\\n        string = \\\"positive\\\"\\n        return string\\n    elif negative > positive and negative > compound and positive <= neutral:\\n        string = \\\"negative\\\"\\n        return string\\n    elif compound > positive and compound > negative and compound > neutral:\\n        string = \\\"compound\\\"\\n        return string\\n    elif neutral > positive and neutral > negative and neutral > compound:\\n        string = \\\"neutral\\\"\\n        return string\\n    else:\\n        string = \\\"neutral\\\"\\n        return string\\n\\ndef sentiment_analyzer_scores(sentence):\\n    score = analyser.polarity_scores(sentence)\\n    return score\\n\\n# API ENDPOINT ACCESS HERE\\nclass TextSentiment(Resource):    \\n    def post(self): \\n        args  = sentiment_args.parse_args()\\n        score = sentiment_analyzer_scores(args['text'])\\n        finalOutput = sentiment_string(score)    # for printing out the analyzed o/p from scores\\n        return {'success': True, 'score': score, 'message': finalOutput}\"},{\"source_archive\":\"Unified_Psychiatric_AI_Brain_Part1.zip\",\"source_path\":\"source_projects/Virtual-Psychiatrist-master/Virtual-Psychiatrist-master/Backend/resources/FacialSentiment.py\",\"language\":\"py\",\"content\":\"from flask import jsonify, request\\nfrom flask_restful import Resource\\nimport os,cv2\\nimport numpy as np\\nfrom keras.models import model_from_json\\nfrom keras.preprocessing import image\\n\\n# Model & Classifier\\nmodel = model_from_json(open(\\\"./resources/facial_emotion/fer.json\\\", \\\"r\\\").read())    \\nmodel.load_weights('./resources/facial_emotion/fer.h5')                             \\n\\ndef FacialOutput(imagename):\\n    Image = cv2.imread('./static/'+imagename)\\n    auto_result, alpha, beta = automatic_brightness_and_contrast(Image)\\n    cv2.imwrite('./static/auto_result.jpeg', auto_result)\\n    \\n    path           = './static/auto_result.jpeg'\\n    test_img       = cv2.imread(path)\\n    gray_img       = cv2.cvtColor(test_img, cv2.COLOR_BGR2GRAY)\\n    faces_detected = face_haar_cascade.detectMultiScale(gray_img, 1.32, 5)\\n    for (x,y,w,h) in faces_detected:\\n        cv2.rectangle(test_img,(x,y),(x+w,y+h),(255,0,0),thickness=7)\\n        roi_gray     = gray_img[y:y+w,x:x+h]\\n        roi_gray     = cv2.resize(roi_gray,(48,48))\\n        img_pixels   = image.img_to_array(roi_gray)\\n        img_pixels   = np.expand_dims(img_pixels, axis = 0)\\n        img_pixels  /= 255\\n        predictions  = model.predict(img_pixels)\\n        # find max indexed array\\n        max_index = np.argmax(predictions[0])\\n        emotions = ('angry', 'disgust', 'fear', 'happy', 'sad', 'surprise', 'neutral')\\n        predicted_emotion = emotions[max_index]\\n        return predicted_emotion\\n\\n# API ENDPOINT ACCESS HERE\\nclass FacialSentiment(Resource):\\n    def post(self): \\n        f = request.files['image']        \\n        if f.filename != '':\\n            f.save(os.path.join('static', f.filename))\\n            result = FacialOutput(f.filename)\\n            os.remove(\\\"./static/\\\" + f.filename)\\n            os.remove(\\\"./static/auto_result.jpeg\\\")\\n            return {'success': True, 'facial_sentiment': result}\\n        else:\\n            return {'success': False, 'facial_sentiment': \\\"False, some error occured.\\\"}\"},{\"source_archive\":\"Unified_Psychiatric_AI_Brain_Part1.zip\",\"source_path\":\"source_projects/Virtual-Psychiatrist-master/Virtual-Psychiatrist-master/Backend/app.py\",\"language\":\"py\",\"content\":\"import re, os\\nfrom flask import Flask, request, jsonify, session\\nfrom flask_sqlalchemy import SQLAlchemy\\nfrom flask_restful import Api, Resource\\nfrom collections import Counter\\nfrom resources import TextSentiment, FacialSentiment, SpeechSentiment\\nfrom resources.chatbot.chatbot import chatbot_final\\nimport matplotlib.pyplot as plt\\n\\napp = Flask(__name__)\\napp.config['JSON_SORT_KEYS'] = False\\napp.config['SQLALCHEMY_DATABASE_URI'] = 'sqlite:///therapist.db'\\napp.secret_key = \\\"therapistsecretkey\\\"\\ndb = SQLAlchemy(app)\\napi = Api(app, prefix='/api')\\n\\n# USER MODEL\\nclass User(db.Model): \\n    id       = db.Column(db.Integer, primary_key=True)\\n    name     = db.Column(db.String(50))\\n    email    = db.Column(db.String(50))\\n    password = db.Column(db.String(255))\\n\\n    def __repr__(self): \\n        return '%d - %s - %s' % (self.id, self.name, self.email)\\n\\n# ANALYSIS MODEL\\nclass Analysis(db.Model):\\n    id            = db.Column(db.Integer, primary_key=True)\\n    email         = db.Column(db.String(50))\\n    s1            = db.Column(db.Text ,nullable=True)\\n    s2            = db.Column(db.Text, nullable=True)\\n    s3            = db.Column(db.Text, nullable=True)\\n    s4            = db.Column(db.Text, nullable=True)\\n    s5            = db.Column(db.Text, nullable=True)\\n    count_session = db.Column(db.Integer)\\n    \\n# CHAT MODEL\\nclass Chat(db.Model):\\n    id        = db.Column(db.Integer, primary_key = True)\\n    user_id   = db.Column(db.Integer)\\n    is_user   = db.Column(db.Integer)\\n    message   = db.Column(db.Text)\\n    timestamp = db.Column(db.DateTime(timezone=True), server_default=db.func.now())\\n    \\n# REGISTERING USERS HERE\\nclass RegisterResource(Resource): \\n    def get(self): \\n        users   = User.query.all()\\n        userobj = {}\\n        for u in users: \\n            userobj[u.id] = {'name': u.name, 'email': u.email, 'password': u.password}\\n        return jsonify({\\\"success\\\":'true', \\\"users\\\": userobj})\\n\\n    def post(self): \\n        user = User(\\n            name     = request.json['name'],\\n            email    = request.json['email'],\\n            password = request.json['password']\\n        )\\n        analysis = Analysis(\\n            email = request.json['email'],\\n            count_session = 0\\n        )\\n        userobj = User.query.filter_by(email = user.email).first()\\n        if userobj:\\n            return jsonify({\\\"success\\\": \\\"False\\\", \\\"message\\\": \\\"An account with this email already exists!\\\"})\\n        else:\\n            db.session.add(user)\\n            db.session.add(analysis)\\n            db.session.commit()\\n            session['user'] = user.email\\n            return jsonify({\\\"success\\\": \\\"True\\\", \\\"message\\\": \\\"Successfully registered & logged in!\\\"})\\n    \\n# LOGIN\\nclass LoginResource(Resource):    \\n    def post(self): \\n        email    = request.json['email']\\n        password = request.json['password']\\n        userobj  = User.query.filter_by(email = email, password = password).first()\\n        if userobj:\\n            session['user'] = userobj.email\\n            return jsonify({\\\"success\\\": \\\"True\\\", \\\"message\\\": \\\"Logged In\\\"})\\n        else: \\n            return jsonify({\\\"success\\\": \\\"False\\\", \\\"message\\\": \\\"Email or Password incorrect\\\"})\\n    \\n# LOGOUT HERE\\nclass LogoutResource(Resource):\\n    def post(self):\\n        email = request.json['email']\\n        if \\\"user\\\" in session:\\n            if email == session['user']:                \\n                session.pop('user', None)\\n                return jsonify({\\\"success\\\": \\\"True\\\", \\\"message\\\": \\\"Logged out\\\"}) \\n            return jsonify({\\\"success\\\": \\\"False\\\", \\\"message\\\": \\\"Not logged in!\\\"}) \\n        return jsonify({\\\"success\\\": \\\"False\\\", \\\"message\\\": \\\"Not logged in!\\\"}) \\n\\n# USER PROFILE\\nclass ProfileResource(Resource):\\n    def get(self):\\n        if \\\"user\\\" in session:\\n            userobj  = User.query.filter_by(email = session['user']).first()\\n            if userobj:\\n                user = {'name': userobj.name, 'email': userobj.email}\\n                return jsonify({\\\"success\\\": \\\"True\\\", \\\"user\\\": user})\\n            else:\\n                return jsonify({\\\"success\\\": \\\"False\\\", \\\"message\\\": \\\"User Not Found!\\\"})        \\n        return jsonify({\\\"success\\\": \\\"False\\\", \\\"message\\\": \\\"Not logged in!\\\"})\\n    \\n# EXTARCT DIFFERENT EMOTIONS AND CLUB THEM TOGETHER\\ndef extract_emotions(emotions):  \\n    if emotions is not None:  \\n        items = re.split(r'[,;]', emotions)\\n        items = list(filter(None, items))\\n        items = dict(Counter(items))\\n        return items\\n    else:\\n        return \\\"\\\"\\n\\n# RADAR CHART\\ndef radarchart(items, userid, name):\\n    if items != \\\"\\\":\\n        path = \\\"static/\\\" + str(userid) + name +\\\".png\\\"\\n        categories, values = [], []\\n        for item in items:\\n            categories.append(item.capitalize())\\n            values.append(items[item])\\n        pi = 3.14\\n        fig = plt.figure(figsize=(6,6))\\n        ax = plt.subplot(polar=\\\"True\\\")\\n\\n        N = len(categories)\\n        values += values[:1]\\n        angles = [n/float(N) * 2 * pi for n in range(N)]\\n        angles += angles[:1]\\n\\n        #ploting\\n        plt.polar(angles,values, marker = '.', color ='#5CA08E')\\n        plt.fill(angles, values, alpha = 0.4,  facecolor = \\\"#5CA08E\\\", linewidth = 2, linestyle = 'solid')\\n\\n        plt.xticks(angles[:-1], categories, color = '#5CA08E', rotation = 45)\\n        ax.set_rlabel_position(0)\\n        ax.xaxis.grid(True, color = '#BFBEBE')\\n        ax.spines['polar'].set_color('#BFBEBE')\\n        plt.yticks([20,40,60,80],color = '#5CA08E', size = 10)\\n        plt.ylim(0, 80)\\n        plt.savefig(\\\"./\\\" + path , format = \\\"png\\\", transparent = \\\"True\\\")\\n        # plt.show()\\n        return request.host_url + path\\n    else:\\n        return request.host_url + 'static/static.png'\\n\\n# ANALYSIS\\nclass AnalysisResource(Resource):\\n    def get(self):\\n        if \\\"user\\\" in session:\\n            analyzed = Analysis.query.filter_by(email = session['user']).first()\\n            user     = User.query.filter_by(email = session['user']).first()   \\n            \\n            items1 = extract_emotions(analyzed.s1)\\n            items2 = extract_emotions(analyzed.s2)\\n            items3 = extract_emotions(analyzed.s3)\\n            items4 = extract_emotions(analyzed.s4)\\n            items5 = extract_emotions(analyzed.s5)\\n            \\n            analysis = [\\n                {\\n                    \\\"id\\\": 1,\\n                    \\\"session\\\": radarchart(items1, user.id, \\\"s1\\\")\\n                },\\n                {\\n                    \\\"id\\\": 2,\\n                    \\\"session\\\": radarchart(items2, user.id, \\\"s2\\\")\\n                },\\n                {\\n                    \\\"id\\\": 3,\\n                    \\\"session\\\": radarchart(items3, user.id, \\\"s3\\\")\\n                },\\n                {\\n                    \\\"id\\\": 4,\\n                    \\\"session\\\": radarchart(items4, user.id, \\\"s4\\\")\\n                },\\n                {\\n                    \\\"id\\\": 5,\\n                    \\\"session\\\": radarchart(items5, user.id, \\\"s5\\\")\\n                },\\n            ]\\n            \\n            return jsonify({\\\"success\\\": \\\"True\\\", \\\"analysis\\\": analysis})\\n        return jsonify({\\\"success\\\": \\\"False\\\", \\\"message\\\": \\\"Not logged in!\\\"})\\n    \\n# NO. OF SESSIONS COMPLETED\\nclass SessionResource(Resource):\\n    def post(self):\\n        if \\\"user\\\" in session:\\n            user_obj = Analysis.query.filter_by(email = session['user']).first()\\n            if user_obj.count_session == 5:\\n                pass    \\n            else:\\n                setattr(user_obj, 'count_session', user_obj.count_session+1)\\n                db.session.commit()\\n            return jsonify({\\\"success\\\": \\\"True\\\", \\\"message\\\": \\\"Successfully updated session count\\\"})\\n        return jsonify({\\\"success\\\": \\\"False\\\", \\\"message\\\": \\\"Not logged in!\\\"})        \\n        \\n    def get(self):\\n        if \\\"user\\\" in session:\\n            count_sessions = Analysis.query.filter_by(email = session['user']).first().count_session\\n            return jsonify({\\\"success\\\": \\\"True\\\", \\\"sessions_attended\\\": count_sessions})\\n        return jsonify({\\\"success\\\": \\\"False\\\", \\\"message\\\": \\\"Not logged in!\\\"})             \\n\\n# SAVE ANALYSIS OF A PARTICULAR MESSAGE IN A SESSION\\ndef save_analysis(text_sentiment, facial_sentiment):\\n    user_analysis = Analysis.query.filter_by(email = session['user']).first()\\n    \\n    session_count = user_analysis.count_session\\n    if session_count == 1:\\n        pre_emotion = user_analysis.s1\\n    elif session_count == 2:\\n        pre_emotion = user_analysis.s2\\n    elif session_count == 3:\\n        pre_emotion = user_analysis.s3\\n    elif session_count == 4:\\n        pre_emotion = user_analysis.s4\\n    else:\\n        pre_emotion = user_analysis.s5                                \\n    \\n    if pre_emotion is None:\\n        pre_emotion = ''\\n    \\n    emotion = pre_emotion + facial_sentiment + ',' + text_sentiment + ';'            \\n    setattr(user_analysis, 's'+str(session_count), emotion)        \\n    db.session.commit()\\n\\n# CHATBOT\\nclass Chatbot(Resource):\\n    def get(self):\\n        if \\\"user\\\" in session:\\n            user_id = User.query.filter_by(email = session['user']).first().id\\n            user_messages = Chat.query.filter_by(user_id = user_id).all()\\n            chat = []\\n            for msg in user_messages:\\n                chat.append({\\n                    \\\"id\\\": msg.id,\\n                    \\\"is_user\\\": msg.is_user,\\n                    \\\"message\\\": msg.message,\\n                    \\\"timestamp\\\": msg.timestamp                     \\n                })\\n            \\n            return jsonify({\\\"success\\\": \\\"True\\\", \\\"chat\\\": chat})\\n        return jsonify({\\\"success\\\": \\\"False\\\", \\\"message\\\": \\\"Not logged in!\\\"})    \\n        \\n    def post(self):\\n        if \\\"user\\\" in session:\\n            user_obj = User.query.filter_by(email = session['user']).first()\\n            \\n            is_user    = request.form['is_user']\\n            message    = request.form['message']\\n            image_file = request.files['image']\\n            \\n            if image_file.filename != '':\\n                image_file.save(os.path.join('static', image_file.filename))\\n                # FACIAL EMOTION HERE\\n                facial_sentiment = FacialSentiment.FacialOutput(image_file.filename)\\n                os.remove(\\\"./static/\\\" + image_file.filename)\\n                os.remove(\\\"./static/auto_result.jpeg\\\")\\n                if facial_sentiment is None:\\n                    facial_sentiment = \\\"neutral\\\"\\n            else:\\n                facial_sentiment = \\\"neutral\\\"\\n            \\n            # VADER SENTIMENT HERE\\n            score = TextSentiment.sentiment_analyzer_scores(message)\\n            text_sentiment = TextSentiment.sentiment_string(score)\\n                        \\n            # SAVING ANALYSIS\\n            save_analysis(text_sentiment, facial_sentiment)\\n            \\n            # GET MAIN Q/A Model Response Here.\\n            response = chatbot_final(message, text_sentiment, facial_sentiment)\\n            \\n            main_chat = Chat(\\n                user_id = user_obj.id,\\n                is_user = 0,\\n                message = response\\n            )\\n            \\n            user_chat = Chat(\\n                user_id = user_obj.id,\\n                is_user = is_user,\\n                message = message\\n            )\\n            db.session.add_all([user_chat, main_chat])\\n            db.session.commit()\\n            \\n            return jsonify({\\\"success\\\": \\\"True\\\", \\\"message\\\": response})\\n        return jsonify({\\\"success\\\": \\\"False\\\", \\\"message\\\": \\\"Not logged in!\\\"})        \\n\\n# CLEARING THE USER CHAT AFTER A SESSION\\nclass ClearChat(Resource):\\n    def post(self):\\n        if \\\"user\\\" in session:\\n            user_id = User.query.filter_by(email = session['user']).first().id\\n            Chat.query.filter_by(user_id = user_id).delete()\\n            # print(user_messages)\\n            db.session.commit()\\n            return jsonify({\\\"success\\\": \\\"True\\\", \\\"message\\\": \\\"Successfully deleted the session chats\\\"})\\n        return jsonify({\\\"success\\\": \\\"False\\\", \\\"message\\\": \\\"Not logged in!\\\"})    \\n    \\n    \\napi.add_resource(LoginResource, '/user/login')\\napi.add_resource(RegisterResource, '/user/register')\\napi.add_resource(LogoutResource,'/user/logout')\\n\\napi.add_resource(ProfileResource, '/user/profile')\\napi.add_resource(AnalysisResource, '/user/analysis')\\napi.add_resource(SessionResource, '/user/session')\\n\\napi.add_resource(ClearChat, '/user/clearchat')\\n\\napi.add_resource(Chatbot, '/chatbot')\\n\\n# MODEL ENDPOINTS \\napi.add_resource(TextSentiment.TextSentiment, \\\"/text\\\")\\napi.add_resource(FacialSentiment.FacialSentiment, \\\"/facial\\\")\\napi.add_resource(SpeechSentiment.SpeechSentiment, \\\"/speech\\\")\\n\\n@app.route('/')\\ndef home():\\n \\treturn \\\"Server is Live!\\\"\\n\\nif __name__ == '__main__':\\n    app.run(debug = True)\"},{\"source_archive\":\"Unified_Psychiatric_AI_Brain_Part1.zip\",\"source_path\":\"source_projects/Virtual-Psychiatrist-master/Virtual-Psychiatrist-master/Backend/static/dont_delete_this.txt\",\"language\":\"txt\",\"content\":\"Dont delete this file inorder to commit the static folder onto GIT.\"},{\"source_archive\":\"Unified_Psychiatric_AI_Brain_Part1.zip\",\"source_path\":\"source_projects/Virtual-Psychiatrist-master/Virtual-Psychiatrist-master/Backend/.gitignore\",\"language\":\"text\",\"content\":\"# Byte-compiled / optimized / DLL files\\n__pycache__/\\n*.py[cod]\\n*$py.class\\n\\n# C extensions\\n*.so\\n\\n# Distribution / packaging\\n.Python\\nbuild/\\ndevelop-eggs/\\ndist/\\ndownloads/\\neggs/\\n.eggs/\\nlib/\\nlib64/\\nparts/\\nsdist/\\nvar/\\nwheels/\\nshare/python-wheels/\\n*.egg-info/\\n.installed.cfg\\n*.egg\\nMANIFEST\\n\\n# PyInstaller\\n#  Usually these files are written by a python script from a template\\n#  before PyInstaller builds the exe, so as to inject date/other infos into it.\\n*.manifest\\n*.spec\\n\\n# Installer logs\\npip-log.txt\\npip-delete-this-directory.txt\\n\\n# Unit test / coverage reports\\nhtmlcov/\\n.tox/\\n.nox/\\n.coverage\\n.coverage.*\\n.cache\\nnosetests.xml\\ncoverage.xml\\n*.cover\\n*.py,cover\\n.hypothesis/\\n.pytest_cache/\\ncover/\\n\\n# Translations\\n*.mo\\n*.pot\\n\\n# Django stuff:\\n*.log\\nlocal_settings.py\\ndb.sqlite3\\ndb.sqlite3-journal\\n\\n# Flask stuff:\\ninstance/\\n.webassets-cache\\n\\n# Scrapy stuff:\\n.scrapy\\n\\n# Sphinx documentation\\ndocs/_build/\\n\\n# PyBuilder\\n.pybuilder/\\ntarget/\\n\\n# Jupyter Notebook\\n.ipynb_checkpoints\\n\\n# IPython\\nprofile_default/\\nipython_config.py\\n\\n# pyenv\\n#   For a library or package, you might want to ignore these files since the code is\\n#   intended to run in multiple environments; otherwise, check them in:\\n# .python-version\\n\\n# pipenv\\n#   According to pypa/pipenv#598, it is recommended to include Pipfile.lock in version control.\\n#   However, in case of collaboration, if having platform-specific dependencies or dependencies\\n#   having no cross-platform support, pipenv may install dependencies that don't work, or not\\n#   install all needed dependencies.\\n#Pipfile.lock\\n\\n# PEP 582; used by e.g. github.com/David-OConnor/pyflow\\n__pypackages__/\\n\\n# Celery stuff\\ncelerybeat-schedule\\ncelerybeat.pid\\n\\n# SageMath parsed files\\n*.sage.py\\n\\n# Environments\\n.env\\n.venv\\nenv/\\nvenv/\\nENV/\\nenv.bak/\\nvenv.bak/\\nai.txt\\n\\n# Spyder project settings\\n.spyderproject\\n.spyproject\\n\\n# Rope project settings\\n.ropeproject\\n\\n# mkdocs documentation\\n/site\\n\\n# mypy\\n.mypy_cache/\\n.dmypy.json\\ndmypy.json\\n\\n# Pyre type checker\\n.pyre/\\n\\n# pytype static type analyzer\\n.pytype/\\n\\n# Cython debug symbols\\ncython_debug/\"},{\"source_archive\":\"Unified_Psychiatric_AI_Brain_Part1.zip\",\"source_path\":\"source_projects/Virtual-Psychiatrist-master/Virtual-Psychiatrist-master/README.md\",\"language\":\"md\",\"content\":\"# Virtual Psychiatrist\\n\\nThis is an app which helps a user to deal with depression at a basic level by providing them\\nCognitive - Behavioral Therapy i.e. CBT Therapy in order to overcome various psychological problems and guide them to\\ngo take assistance by visiting an actual Psychologist. User can interact to a chatbot and can also track his\\nprogress through the analysis provided inside the application.\\n\\n### Project Structure is divided into 2 main Modules:\\n\\n- #### Backend \\n    Flask is used inorder to wrap all the ML Models. Follow the steps below to run the Backend Server.\\n\\n    <details><summary><b>Show Steps</b></summary>\\n    \\n    1. Change the directory from root to `Backend` folder:\\n\\n        ``` \\n        $ cd Backend \\n        ```\\n\\n    2. Install all the required libraries from `requirements.txt` file:\\n\\n        ```\\n        $ pip3 install -r requirements.txt \\n        ```\\n\\n    3. Once done with installation, run the below command to serve the flask server:\\n\\n        ```\\n        $ python app.py\\n        ```\\n        It will take some time to serve since the tensorflow is loaded first time the server is started.\\n    4. Now, you can visit different urls specified in the `app.py` to view the backend.\\n\\n</details>\\n\\n- #### Frontend \\n    React Native Framework is used to make mobile application frontend for both Android as well as iOS devices. Follow the steps below to run the Frontend.\\n    \\n    <details><summary><b>Show Steps</b></summary>\\n    \\n    1. Change the directory from root to `Frontend/Therapist` folder:\\n\\n        ``` \\n        $ cd Frontend/Therapist \\n        ```\\n\\n    2. Make sure Android-Studio and React-Native are properly set up before running the following command (for Android):\\n\\n        ```\\n        $ react-native run-android \\n        ```\\n\\n    3. Now, the app will be visible in either emulator or the device connected as specified earlier in your own config.\\n\\n</details>\\n\\n## License\\n[MIT](https://github.com/smit-sms/Virtual-Psychiatrist/blob/master/LICENSE)\"},{\"source_archive\":\"Unified_Psychiatric_AI_Brain_Part1.zip\",\"source_path\":\"source_projects/ChatPsychiatrist-master/ChatPsychiatrist-master/requirements.txt\",\"language\":\"txt\",\"content\":\"accelerate==0.18.0\\nanthropic==0.2.10\\nbeautifulsoup4==4.12.2\\ndatasets==2.11.0\\ndeepspeed==0.9.0+970d827f\\neinops==0.6.1\\nfastapi==0.100.0\\nflash_attn==1.0.1\\ngradio==3.39.0\\nhttpx==0.24.1\\nhuggingface_hub==0.14.1\\nintel_extension_for_pytorch==2.0.100\\njsonlines==3.1.0\\nlangchain==0.0.245\\nllama==0.1.1\\nmarkdownify==0.11.6\\nnumpy==1.24.2\\nopenai==0.27.8\\npandas==2.0.0\\npeft==0.2.0\\nplotly==5.15.0\\npolyglot==16.7.4\\nprompt_toolkit==3.0.31\\npsutil==5.9.4\\npycld2==0.41\\npydantic==1.10.7\\npytz==2023.3\\nray==2.3.1\\nRequests==2.31.0\\nrich==13.4.2\\nrwkv==0.8.0\\nscikit_learn==1.3.0\\nscipy==1.11.1\\nshortuuid==1.0.11\\ntiktoken==0.4.0\\ntorch==1.13.1+cu117\\ntqdm==4.65.0\\ntransformers==4.28.1\\nuvicorn==0.23.1\\nvertexai==0.0.1\\nvllm==0.1.2\\nxformers==0.0.20\\n\"},{\"source_archive\":\"Unified_Psychiatric_AI_Brain_Part1.zip\",\"source_path\":\"source_projects/ChatPsychiatrist-master/ChatPsychiatrist-master/format.sh\",\"language\":\"sh\",\"content\":\"#!/usr/bin/env bash\\n\\n# Adopted from https://github.com/skypilot-org/skypilot/blob/master/format.sh\\n\\n# Cause the script to exit if a single command fails\\nset -eo pipefail\\n\\n# this stops git rev-parse from failing if we run this from the .git directory\\nbuiltin cd \\\"$(dirname \\\"${BASH_SOURCE:-$0}\\\")\\\"\\nROOT=\\\"$(git rev-parse --show-toplevel)\\\"\\nbuiltin cd \\\"$ROOT\\\" || exit 1\\n\\nBLACK_VERSION=$(black --version | head -n 1 | awk '{print $2}')\\nPYLINT_VERSION=$(pylint --version | head -n 1 | awk '{print $2}')\\n\\n# # params: tool name, tool version, required version\\ntool_version_check() {\\n    if [[ $2 != $3 ]]; then\\n        echo \\\"Wrong $1 version installed: $3 is required, not $2.\\\"\\n        exit 1\\n    fi\\n}\\n\\ntool_version_check \\\"black\\\" $BLACK_VERSION \\\"23.3.0\\\"\\ntool_version_check \\\"pylint\\\" $PYLINT_VERSION \\\"2.8.2\\\"\\n\\n# Format files that differ from main branch. Ignores dirs that are not slated\\n# for autoformat yet.\\nformat_changed() {\\n    # The `if` guard ensures that the list of filenames is not empty, which\\n    # could cause yapf to receive 0 positional arguments, making it hang\\n    # waiting for STDIN.\\n    #\\n    # `diff-filter=ACM` and $MERGEBASE is to ensure we only format files that\\n    # exist on both branches.\\n    MERGEBASE=\\\"$(git merge-base origin/main HEAD)\\\"\\n\\n    if ! git diff --diff-filter=ACM --quiet --exit-code \\\"$MERGEBASE\\\" -- '*.py' '*.pyi' &>/dev/null; then\\n        git diff --name-only --diff-filter=ACM \\\"$MERGEBASE\\\" -- '*.py' '*.pyi' | xargs -P 5 black\\n    fi\\n}\\n\\n## This flag formats individual files. --files *must* be the first command line\\n## arg to use this option.\\nif [[ \\\"$1\\\" == '--files' ]]; then\\n   black \\\"${@:2}\\\"\\n   # If `--all` is passed, then any further arguments are ignored and the\\n   # entire python directory is formatted.\\nelif [[ \\\"$1\\\" == '--all' ]]; then\\n   # Format all files\\n   black fastchat\\nelse\\n   # Format only the files that changed in last commit.\\n   format_changed\\nfi\\necho 'FastChat Black: Done'\\n\\n# Run Pylint\\necho 'FastChat Pylint:'\\npylint fastchat\\n# TODO(suquark): disable 'pylint_quotes' for now due to too many inconsistent quotes\\n# pylint --load-plugins pylint_quotes fastchat\\n\\nif ! git diff --quiet &>/dev/null; then\\n    echo 'Reformatted files. Please review and stage the changes.'\\n    echo 'Changes not staged for commit:'\\n    echo\\n    git --no-pager diff --name-only\\n\\n    exit 1\\nfi\\n\"},{\"source_archive\":\"Unified_Psychiatric_AI_Brain_Part1.zip\",\"source_path\":\"source_projects/ChatPsychiatrist-master/ChatPsychiatrist-master/docs/Evaluation_definetion.md\",\"language\":\"md\",\"content\":\"# Evaluation definition\\n\\nWe measure the quality of the response by the following 7 metrics. We provide the definition of each metric and the corresponding strategies, guidances and examples.\\n\\n| Strategies                            | Guidances                                                    | Examples                                                     |\\n| ------------------------------------- | ------------------------------------------------------------ | ------------------------------------------------------------ |\\n| Information                           | The response should supply  psychological, counselling or mental health data, facts, resources, theory,  etc.. It may be specifically related to the counseling process and client's  behavior. It may answer direct questions but does not include directions for  what the client should do. | There is a psychological effect  on first     love, called Zeigarnic effect. |\\n| Direct  Guidance                      | The response should provide  suggestions, directives, instructions, or advice about what the client should  do to change. This consists of directions or advice that the counselor  suggests for the client, or for the client and counselor together, either within  or outside the counseling session. | To cope with your OCD, plan  ahead by discussing your concerns with your husband and setting boundaries. |\\n| Approval and Reassurance              | The response should provide  emotional support, reassurance, encouragement, approval, or reinforcement. It  may imply sympathy or tend to alleviate anxiety by minimizing client's  problems. | Let me give you a warm hug! /  It's wonderful to hear that you are feeling better and finding the diary and  thought tables beneficial. |\\n| Restatement & Reflection  & Listening | The response should show its  understanding on what the client is feeling or what the client's message  means. Then the response should provide repeating or rephrasing of the  client's statement(s), or meaning of the question, put its understanding into  one's own words (code) and feed it back for the client\u2019s verification. It  must contain reference to stated or implied feelings. It may be based on  previous statements, or knowledge of the total situation. It may be phrased  either tentatively or as a statement. | You feel like you are becoming  violent. / It seems like you are struggling with finding a balance in your  relationships, especially when it comes to having deep, personal  connections. |\\n| Interpretation                        | The response should go beyond  what the client has overtly recognized. It might take one of several forms:  It might establish connections between seemingly isolated statements or  events; it interprets defenses, feelings, resistance, or transference (the interpersonal  relationship between counselor and client): it might indicate themes,  patterns, or causal relationships in the client's behavior or personality. It  usually gives alternative meanings, reasons or explanations for old behavior  or issues. | I think you love your mom very  much.                        |\\n| Self-disclosure                       | The response should share the  psychiatrist's own personal experiences and feelings with the client; may  begin with an \\\"I\\\". Note that not all statements that begin with an  \\\"I\\\" are self-disclosure; it must have a quality of sharing or disclosing. | This question brings back to me  some similar memories       |\\n| Obtain  releveant information         | The response should use  appropriate questions. It may request a clarification of feelings or an  exploration of the situation without purposely limiting the nature of the  response to a yes or no or a one- or two-word response. | Can you provide an example of a  change you are considering and why it is challenging for you? |\\n\\n\\n# Citation\\n```\\n@book{hill2009helping,\\n  title={Helping skills: Facilitating, exploration, insight, and action},\\n  author={Hill, Clara E},\\n  year={2009},\\n  publisher={American Psychological Association}\\n}\\n\\n@misc{sun2021psyqa,\\n  title={PsyQA: A Chinese Dataset for Generating Long Counseling Text for Mental Health Support}, \\n  author={Hao Sun and Zhenru Lin and Chujie Zheng and Siyang Liu and Minlie Huang},\\n  year={2021},\\n  eprint={2106.01702},\\n  archivePrefix={arXiv},\\n  primaryClass={cs.CL}\\n}\\n```\"},{\"source_archive\":\"Unified_Psychiatric_AI_Brain_Part1.zip\",\"source_path\":\"source_projects/ChatPsychiatrist-master/ChatPsychiatrist-master/fastchat/score_app.py\",\"language\":\"py\",\"content\":\"import gradio as gr\\nimport json\\nimport os\\nfrom typing import Dict, Sequence, Optional\\nimport argparse\\nfrom collections import defaultdict\\nfrom dataclasses import dataclass, field\\n\\nTOTAL_QUESTIONS = 80\\nQUESTION_NUM_PER_CATEGORY = 10\\n\\n@dataclass\\nclass ScoreCell:\\n    model_score: int = field(default=0)\\n    \\n\\ndef read_jsonl(path: str, key: str=None):\\n    data = []\\n    with open(os.path.expanduser(path), \\\"r\\\", encoding=\\\"utf-8\\\") as f:\\n        for line in f:\\n            if not line:\\n                continue\\n            data.append(json.loads(line))\\n    if key is not None:\\n        data.sort(key=lambda x: x[key])\\n        data = {item[key]: item for item in data}\\n    return data\\n\\ndef get_categories(question_json):\\n    questions = read_jsonl(question_json)\\n    categories = []\\n    for question in questions:\\n        categories.append(question[\\\"category\\\"])\\n    categories = list(set(categories))\\n    return categories\\n\\ndef show(question_json, answerA_json, answerB_json, category, question_id:int):\\n    questions = read_jsonl(question_json)\\n    category_questions = [question for question in questions if question[\\\"category\\\"] == category]\\n    question_id = question_id - 1\\n    q, q_id = category_questions[question_id][\\\"text\\\"], category_questions[question_id][\\\"question_id\\\"]\\n    \\n    ansA = read_jsonl(answerA_json)[q_id-1][\\\"text\\\"]\\n    ansB = read_jsonl(answerB_json)[q_id-1][\\\"text\\\"]\\n    return q, ansA, ansB\\n\\ndef upvote(score_dict, category_selector, question_id):\\n    tmp_id = f\\\"{category_selector}-{question_id}\\\"\\n    if tmp_id in score_dict:\\n        return score_dict\\n    score_dict[tmp_id].model_score += 1\\n    return score_dict\\n\\ndef reset_cur_question(scoreA, scoreB, category_selector, question_id):\\n    tmp_id = f\\\"{category_selector}-{question_id}\\\"\\n    if tmp_id in scoreA:\\n        del scoreA[tmp_id]\\n    if tmp_id in scoreB:\\n        del scoreB[tmp_id]\\n    return scoreA, scoreB\\n    \\ndef show_result(scoreA, scoreB):\\n    answered_num = len(scoreA) + len(scoreB)\\n    if answered_num == 0:\\n        return \\\"\u26a0\u26a0\u26a0 No question has been answered\\\"\\n    scoreA_sum = sum([score.model_score for score in scoreA.values()])\\n    scoreB_sum = sum([score.model_score for score in scoreB.values()])\\n    res = \\\"Model-A: {} | Model-B: {}\\\".format(int(scoreA_sum), int(scoreB_sum))\\n    if answered_num < TOTAL_QUESTIONS:\\n        res += \\\"\\\\n \u26a0\u26a0\u26a0 Not all questions have been answered\\\"\\n    return res\\n\\n\\ndef build_demo():\\n    demo = gr.Blocks()\\n    with demo:\\n        scoreA = gr.State(value=defaultdict(ScoreCell))\\n        scoreB = gr.State(value=defaultdict(ScoreCell))\\n        \\n        question_json_path = gr.Dropdown(\\n            label=\\\"Question JSON Path\\\",\\n            choices=[\\\"eval/table/counselling_question.jsonl\\\",],\\n        )\\n        with gr.Row():\\n            with gr.Column():\\n                answerA_json_path = gr.Dropdown(\\n                    label=\\\"Model-A Answer JSON Path\\\",\\n                    choices=[\\\"eval/table/answer/counselling_answer.jsonl\\\",],\\n                )\\n            with gr.Column():\\n                answerB_json_path = gr.Dropdown(\\n                    label=\\\"Model-B Answer JSON Path\\\",\\n                    choices=[\\\"eval/table/answer/counselling_answer_vicuna-7b.jsonl\\\",],\\n                )\\n        with gr.Row():\\n            with gr.Column():\\n                category_selector = gr.Dropdown(\\n                    choices=categories,\\n                    label=\\\"Question Category\\\",\\n                    interactive=True,\\n                    show_label=True,\\n                )\\n            with gr.Column():\\n                question_id = gr.Slider(1, QUESTION_NUM_PER_CATEGORY, value=1, label=\\\"Question ID\\\", step=1)\\n        \\n        with gr.Row():\\n            with gr.Column():\\n                reset_cur_q_btn = gr.Button(value=\\\"Reset Current Question\\\")\\n            with gr.Column():\\n                prev_q_btn = gr.Button(value=\\\"\ud83d\udc48 Previous Question\\\")\\n            with gr.Column():\\n                next_q_btn = gr.Button(value=\\\"\ud83d\udc49 Next Question\\\")\\n        output_q = gr.Textbox(label=\\\"Question\\\")\\n        with gr.Row():\\n            with gr.Column():\\n                output_ansA = gr.Textbox(label=\\\"Model-A Answer\\\")\\n                upvote_ansA_btn = gr.Button(value=\\\"\ud83d\udc4d\\\")\\n            with gr.Column():\\n                output_ansB = gr.Textbox(label=\\\"Model-B Answer\\\")\\n                upvote_ansB_btn = gr.Button(value=\\\"\ud83d\udc4d\\\")\\n        \\n        with gr.Row():\\n            summarize = gr.Button(value=\\\"Summarize\\\")\\n            result = gr.Textbox(label=\\\"Result\\\", interactive=False, placeholder=\\\"Result will be shown here\\\")\\n            reset = gr.Button(value=\\\"Reset\\\")\\n            \\n        \\n        category_selector.change(fn=show, inputs=[question_json_path, answerA_json_path, answerB_json_path, category_selector, question_id], outputs=[output_q, output_ansA, output_ansB])\\n        question_id.change(fn=show, inputs=[question_json_path, answerA_json_path, answerB_json_path, category_selector, question_id], outputs=[output_q, output_ansA, output_ansB])\\n        \\n        # reset current question's vote\\n        reset_cur_q_btn.click(fn=reset_cur_question, inputs=[scoreA, scoreB, category_selector, question_id], outputs=[scoreA, scoreB])\\n        prev_q_btn.click(fn=lambda qid: max(qid - 1, 1), inputs=[question_id], outputs=[question_id])\\n        next_q_btn.click(fn=lambda qid: min(qid + 1, QUESTION_NUM_PER_CATEGORY), inputs=[question_id], outputs=[question_id])\\n        \\n        upvote_ansA_btn.click(\\n            fn=upvote, inputs=[scoreA, category_selector, question_id], outputs=[scoreA])\\n        upvote_ansB_btn.click(\\n            fn=upvote, inputs=[scoreB, category_selector, question_id], outputs=[scoreB])\\n        \\n        summarize.click(fn=show_result, inputs=[scoreA, scoreB], outputs=[result])\\n        reset.click(fn=lambda: (defaultdict(ScoreCell), defaultdict(ScoreCell), \\\"Result will be shown here\\\"), \\n                    outputs=[scoreA, scoreB, result])\\n    \\n    return demo\\n    \\n\\nif __name__ == \\\"__main__\\\":\\n    parser = argparse.ArgumentParser()\\n    parser.add_argument(\\\"--share\\\", action=\\\"store_true\\\")\\n    args = parser.parse_args()\\n    categories = get_categories(\\\"eval/table/counselling_question.jsonl\\\")\\n    \\n    build_demo().launch(share = args.share)\"},{\"source_archive\":\"Unified_Psychiatric_AI_Brain_Part1.zip\",\"source_path\":\"source_projects/ChatPsychiatrist-master/ChatPsychiatrist-master/fastchat/serve/gradio_block_arena_named.py\",\"language\":\"py\",\"content\":\"\\\"\\\"\\\"\\nChatbot Arena (side-by-side) tab.\\nUsers chat with two chosen models.\\n\\\"\\\"\\\"\\n\\nimport json\\nimport time\\n\\nimport gradio as gr\\nimport numpy as np\\n\\nfrom fastchat.constants import (\\n    MODERATION_MSG,\\n    CONVERSATION_LIMIT_MSG,\\n    INACTIVE_MSG,\\n    INPUT_CHAR_LEN_LIMIT,\\n    CONVERSATION_TURN_LIMIT,\\n)\\nfrom fastchat.model.model_adapter import get_conversation_template\\nfrom fastchat.serve.gradio_web_server import (\\n    State,\\n    bot_response,\\n    get_conv_log_filename,\\n    no_change_btn,\\n    enable_btn,\\n    disable_btn,\\n    learn_more_md,\\n    get_model_description_md,\\n    ip_expiration_dict,\\n)\\nfrom fastchat.utils import (\\n    build_logger,\\n    violates_moderation,\\n)\\n\\n\\nlogger = build_logger(\\\"gradio_web_server_multi\\\", \\\"gradio_web_server_multi.log\\\")\\n\\nnum_sides = 2\\nenable_moderation = False\\n\\n\\ndef set_global_vars_named(enable_moderation_):\\n    global enable_moderation\\n    enable_moderation = enable_moderation_\\n\\n\\ndef load_demo_side_by_side_named(models, url_params):\\n    states = (None,) * num_sides\\n\\n    model_left = models[0] if len(models) > 0 else \\\"\\\"\\n    if len(models) > 1:\\n        weights = ([8] * 4 + [4] * 8 + [1] * 32)[: len(models) - 1]\\n        weights = weights / np.sum(weights)\\n        model_right = np.random.choice(models[1:], p=weights)\\n    else:\\n        model_right = model_left\\n\\n    selector_updates = (\\n        gr.Dropdown.update(choices=models, value=model_left, visible=True),\\n        gr.Dropdown.update(choices=models, value=model_right, visible=True),\\n    )\\n\\n    return (\\n        states\\n        + selector_updates\\n        + (gr.Chatbot.update(visible=True),) * num_sides\\n        + (\\n            gr.Textbox.update(visible=True),\\n            gr.Box.update(visible=True),\\n            gr.Row.update(visible=True),\\n            gr.Row.update(visible=True),\\n            gr.Accordion.update(visible=True),\\n        )\\n    )\\n\\n\\ndef vote_last_response(states, vote_type, model_selectors, request: gr.Request):\\n    with open(get_conv_log_filename(), \\\"a\\\") as fout:\\n        data = {\\n            \\\"tstamp\\\": round(time.time(), 4),\\n            \\\"type\\\": vote_type,\\n            \\\"models\\\": [x for x in model_selectors],\\n            \\\"states\\\": [x.dict() for x in states],\\n            \\\"ip\\\": request.client.host,\\n        }\\n        fout.write(json.dumps(data) + \\\"\\\\n\\\")\\n\\n\\ndef leftvote_last_response(\\n    state0, state1, model_selector0, model_selector1, request: gr.Request\\n):\\n    logger.info(f\\\"leftvote (named). ip: {request.client.host}\\\")\\n    vote_last_response(\\n        [state0, state1], \\\"leftvote\\\", [model_selector0, model_selector1], request\\n    )\\n    return (\\\"\\\",) + (disable_btn,) * 4\\n\\n\\ndef rightvote_last_response(\\n    state0, state1, model_selector0, model_selector1, request: gr.Request\\n):\\n    logger.info(f\\\"rightvote (named). ip: {request.client.host}\\\")\\n    vote_last_response(\\n        [state0, state1], \\\"rightvote\\\", [model_selector0, model_selector1], request\\n    )\\n    return (\\\"\\\",) + (disable_btn,) * 4\\n\\n\\ndef tievote_last_response(\\n    state0, state1, model_selector0, model_selector1, request: gr.Request\\n):\\n    logger.info(f\\\"tievote (named). ip: {request.client.host}\\\")\\n    vote_last_response(\\n        [state0, state1], \\\"tievote\\\", [model_selector0, model_selector1], request\\n    )\\n    return (\\\"\\\",) + (disable_btn,) * 4\\n\\n\\ndef bothbad_vote_last_response(\\n    state0, state1, model_selector0, model_selector1, request: gr.Request\\n):\\n    logger.info(f\\\"bothbad_vote (named). ip: {request.client.host}\\\")\\n    vote_last_response(\\n        [state0, state1], \\\"bothbad_vote\\\", [model_selector0, model_selector1], request\\n    )\\n    return (\\\"\\\",) + (disable_btn,) * 4\\n\\n\\ndef regenerate(state0, state1, request: gr.Request):\\n    logger.info(f\\\"regenerate (named). ip: {request.client.host}\\\")\\n    states = [state0, state1]\\n    for i in range(num_sides):\\n        states[i].conv.update_last_message(None)\\n    return states + [x.to_gradio_chatbot() for x in states] + [\\\"\\\"] + [disable_btn] * 6\\n\\n\\ndef clear_history(request: gr.Request):\\n    logger.info(f\\\"clear_history (named). ip: {request.client.host}\\\")\\n    return [None] * num_sides + [None] * num_sides + [\\\"\\\"] + [disable_btn] * 6\\n\\n\\ndef share_click(state0, state1, model_selector0, model_selector1, request: gr.Request):\\n    logger.info(f\\\"share (named). ip: {request.client.host}\\\")\\n    if state0 is not None and state1 is not None:\\n        vote_last_response(\\n            [state0, state1], \\\"share\\\", [model_selector0, model_selector1], request\\n        )\\n\\n\\ndef add_text(\\n    state0, state1, model_selector0, model_selector1, text, request: gr.Request\\n):\\n    ip = request.client.host\\n    logger.info(f\\\"add_text (named). ip: {ip}. len: {len(text)}\\\")\\n    states = [state0, state1]\\n    model_selectors = [model_selector0, model_selector1]\\n\\n    # Init states if necessary\\n    for i in range(num_sides):\\n        if states[i] is None:\\n            states[i] = State(model_selectors[i])\\n\\n    if len(text) <= 0:\\n        for i in range(num_sides):\\n            states[i].skip_next = True\\n        return (\\n            states\\n            + [x.to_gradio_chatbot() for x in states]\\n            + [\\\"\\\"]\\n            + [\\n                no_change_btn,\\n            ]\\n            * 6\\n        )\\n\\n    if ip_expiration_dict[ip] < time.time():\\n        logger.info(f\\\"inactive (named). ip: {request.client.host}. text: {text}\\\")\\n        for i in range(num_sides):\\n            states[i].skip_next = True\\n        return (\\n            states\\n            + [x.to_gradio_chatbot() for x in states]\\n            + [INACTIVE_MSG]\\n            + [\\n                no_change_btn,\\n            ]\\n            * 6\\n        )\\n\\n    if enable_moderation:\\n        flagged = violates_moderation(text)\\n        if flagged:\\n            logger.info(\\n                f\\\"violate moderation (named). ip: {request.client.host}. text: {text}\\\"\\n            )\\n            for i in range(num_sides):\\n                states[i].skip_next = True\\n            return (\\n                states\\n                + [x.to_gradio_chatbot() for x in states]\\n                + [MODERATION_MSG]\\n                + [\\n                    no_change_btn,\\n                ]\\n                * 6\\n            )\\n\\n    conv = states[0].conv\\n    if (len(conv.messages) - conv.offset) // 2 >= CONVERSATION_TURN_LIMIT:\\n        logger.info(f\\\"conversation turn limit. ip: {request.client.host}. text: {text}\\\")\\n        for i in range(num_sides):\\n            states[i].skip_next = True\\n        return (\\n            states\\n            + [x.to_gradio_chatbot() for x in states]\\n            + [CONVERSATION_LIMIT_MSG]\\n            + [\\n                no_change_btn,\\n            ]\\n            * 6\\n        )\\n\\n    text = text[:INPUT_CHAR_LEN_LIMIT]  # Hard cut-off\\n    for i in range(num_sides):\\n        states[i].conv.append_message(states[i].conv.roles[0], text)\\n        states[i].conv.append_message(states[i].conv.roles[1], None)\\n        states[i].skip_next = False\\n\\n    return (\\n        states\\n        + [x.to_gradio_chatbot() for x in states]\\n        + [\\\"\\\"]\\n        + [\\n            disable_btn,\\n        ]\\n        * 6\\n    )\\n\\n\\ndef bot_response_multi(\\n    state0,\\n    state1,\\n    temperature,\\n    top_p,\\n    max_new_tokens,\\n    request: gr.Request,\\n):\\n    logger.info(f\\\"bot_response_multi (named). ip: {request.client.host}\\\")\\n\\n    if state0.skip_next:\\n        # This generate call is skipped due to invalid inputs\\n        yield (\\n            state0,\\n            state1,\\n            state0.to_gradio_chatbot(),\\n            state1.to_gradio_chatbot(),\\n        ) + (no_change_btn,) * 6\\n        return\\n\\n    states = [state0, state1]\\n    gen = []\\n    for i in range(num_sides):\\n        gen.append(\\n            bot_response(\\n                states[i],\\n                temperature,\\n                top_p,\\n                max_new_tokens,\\n                request,\\n            )\\n        )\\n\\n    chatbots = [None] * num_sides\\n    while True:\\n        stop = True\\n        for i in range(num_sides):\\n            try:\\n                ret = next(gen[i])\\n                states[i], chatbots[i] = ret[0], ret[1]\\n                stop = False\\n            except StopIteration:\\n                pass\\n        yield states + chatbots + [disable_btn] * 6\\n        if stop:\\n            break\\n\\n\\ndef flash_buttons():\\n    btn_updates = [\\n        [disable_btn] * 4 + [enable_btn] * 2,\\n        [enable_btn] * 6,\\n    ]\\n    for i in range(10):\\n        yield btn_updates[i % 2]\\n        time.sleep(0.2)\\n\\n\\ndef build_side_by_side_ui_named(models):\\n    notice_markdown = \\\"\\\"\\\"\\n# \u2694\ufe0f  Chatbot Arena \u2694\ufe0f \\n### Rules\\n- Chat with two models side-by-side and vote for which one is better!\\n- You pick the models you want to chat with.\\n- You can do multiple rounds of conversations before voting.\\n- Click \\\"Clear history\\\" to start a new round.\\n- | [Blog](https://lmsys.org/blog/2023-05-03-arena/) | [GitHub](https://github.com/lm-sys/FastChat) | [Paper](https://arxiv.org/abs/2306.05685) | [Twitter](https://twitter.com/lmsysorg) | [Discord](https://discord.gg/HSWAKCrnFx) |\\n\\n### Terms of use\\nBy using this service, users are required to agree to the following terms: The service is a research preview intended for non-commercial use only. It only provides limited safety measures and may generate offensive content. It must not be used for any illegal, harmful, violent, racist, or sexual purposes. **The service collects user dialogue data and reserves the right to distribute it under a Creative Commons Attribution (CC-BY) license.** The demo works better on desktop devices with a wide screen.\\n\\n### Choose two models to chat with (view [leaderboard](?leaderboard))\\n\\\"\\\"\\\"\\n\\n    states = [gr.State() for _ in range(num_sides)]\\n    model_selectors = [None] * num_sides\\n    chatbots = [None] * num_sides\\n\\n    model_description_md = get_model_description_md(models)\\n    notice = gr.Markdown(\\n        notice_markdown + model_description_md, elem_id=\\\"notice_markdown\\\"\\n    )\\n\\n    with gr.Box(elem_id=\\\"share-region-named\\\"):\\n        with gr.Row():\\n            for i in range(num_sides):\\n                with gr.Column():\\n                    model_selectors[i] = gr.Dropdown(\\n                        choices=models,\\n                        value=models[i] if len(models) > i else \\\"\\\",\\n                        interactive=True,\\n                        show_label=False,\\n                        container=False,\\n                    )\\n\\n        with gr.Row():\\n            for i in range(num_sides):\\n                label = \\\"Model A\\\" if i == 0 else \\\"Model B\\\"\\n                with gr.Column():\\n                    chatbots[i] = gr.Chatbot(\\n                        label=label, elem_id=f\\\"chatbot\\\", visible=False, height=550\\n                    )\\n\\n        with gr.Box() as button_row:\\n            with gr.Row():\\n                leftvote_btn = gr.Button(value=\\\"\ud83d\udc48  A is better\\\", interactive=False)\\n                rightvote_btn = gr.Button(value=\\\"\ud83d\udc49  B is better\\\", interactive=False)\\n                tie_btn = gr.Button(value=\\\"\ud83e\udd1d  Tie\\\", interactive=False)\\n                bothbad_btn = gr.Button(value=\\\"\ud83d\udc4e  Both are bad\\\", interactive=False)\\n\\n    with gr.Row():\\n        with gr.Column(scale=20):\\n            textbox = gr.Textbox(\\n                show_label=False,\\n                placeholder=\\\"Enter text and press ENTER\\\",\\n                visible=False,\\n                container=False,\\n            )\\n        with gr.Column(scale=1, min_width=50):\\n            send_btn = gr.Button(value=\\\"Send\\\", visible=False)\\n\\n    with gr.Row() as button_row2:\\n        regenerate_btn = gr.Button(value=\\\"\ud83d\udd04  Regenerate\\\", interactive=False)\\n        clear_btn = gr.Button(value=\\\"\ud83d\uddd1\ufe0f  Clear history\\\", interactive=False)\\n        share_btn = gr.Button(value=\\\"\ud83d\udcf7  Share\\\")\\n\\n    with gr.Accordion(\\\"Parameters\\\", open=False, visible=True) as parameter_row:\\n        temperature = gr.Slider(\\n            minimum=0.0,\\n            maximum=1.0,\\n            value=0.7,\\n            step=0.1,\\n            interactive=True,\\n            label=\\\"Temperature\\\",\\n        )\\n        top_p = gr.Slider(\\n            minimum=0.0,\\n            maximum=1.0,\\n            value=1.0,\\n            step=0.1,\\n            interactive=True,\\n            label=\\\"Top P\\\",\\n        )\\n        max_output_tokens = gr.Slider(\\n            minimum=16,\\n            maximum=1024,\\n            value=512,\\n            step=64,\\n            interactive=True,\\n            label=\\\"Max output tokens\\\",\\n        )\\n\\n    gr.Markdown(learn_more_md)\\n\\n    # Register listeners\\n    btn_list = [\\n        leftvote_btn,\\n        rightvote_btn,\\n        tie_btn,\\n        bothbad_btn,\\n        regenerate_btn,\\n        clear_btn,\\n    ]\\n    leftvote_btn.click(\\n        leftvote_last_response,\\n        states + model_selectors,\\n        [textbox, leftvote_btn, rightvote_btn, tie_btn, bothbad_btn],\\n    )\\n    rightvote_btn.click(\\n        rightvote_last_response,\\n        states + model_selectors,\\n        [textbox, leftvote_btn, rightvote_btn, tie_btn, bothbad_btn],\\n    )\\n    tie_btn.click(\\n        tievote_last_response,\\n        states + model_selectors,\\n        [textbox, leftvote_btn, rightvote_btn, tie_btn, bothbad_btn],\\n    )\\n    bothbad_btn.click(\\n        bothbad_vote_last_response,\\n        states + model_selectors,\\n        [textbox, leftvote_btn, rightvote_btn, tie_btn, bothbad_btn],\\n    )\\n    regenerate_btn.click(\\n        regenerate, states, states + chatbots + [textbox] + btn_list\\n    ).then(\\n        bot_response_multi,\\n        states + [temperature, top_p, max_output_tokens],\\n        states + chatbots + btn_list,\\n    ).then(\\n        flash_buttons, [], btn_list\\n    )\\n    clear_btn.click(clear_history, None, states + chatbots + [textbox] + btn_list)\\n\\n    share_js = \\\"\\\"\\\"\\nfunction (a, b, c, d) {\\n    const captureElement = document.querySelector('#share-region-named');\\n    html2canvas(captureElement)\\n        .then(canvas => {\\n            canvas.style.display = 'none'\\n            document.body.appendChild(canvas)\\n            return canvas\\n        })\\n        .then(canvas => {\\n            const image = canvas.toDataURL('image/png')\\n            const a = document.createElement('a')\\n            a.setAttribute('download', 'chatbot-arena.png')\\n            a.setAttribute('href', image)\\n            a.click()\\n            canvas.remove()\\n        });\\n    return [a, b, c, d];\\n}\\n\\\"\\\"\\\"\\n    share_btn.click(share_click, states + model_selectors, [], _js=share_js)\\n\\n    for i in range(num_sides):\\n        model_selectors[i].change(\\n            clear_history, None, states + chatbots + [textbox] + btn_list\\n        )\\n\\n    textbox.submit(\\n        add_text,\\n        states + model_selectors + [textbox],\\n        states + chatbots + [textbox] + btn_list,\\n    ).then(\\n        bot_response_multi,\\n        states + [temperature, top_p, max_output_tokens],\\n        states + chatbots + btn_list,\\n    ).then(\\n        flash_buttons, [], btn_list\\n    )\\n    send_btn.click(\\n        add_text,\\n        states + model_selectors + [textbox],\\n        states + chatbots + [textbox] + btn_list,\\n    ).then(\\n        bot_response_multi,\\n        states + [temperature, top_p, max_output_tokens],\\n        states + chatbots + btn_list,\\n    ).then(\\n        flash_buttons, [], btn_list\\n    )\\n\\n    return (\\n        states,\\n        model_selectors,\\n        chatbots,\\n        textbox,\\n        send_btn,\\n        button_row,\\n        button_row2,\\n        parameter_row,\\n    )\\n\"},{\"source_archive\":\"Unified_Psychiatric_AI_Brain_Part1.zip\",\"source_path\":\"source_projects/ChatPsychiatrist-master/ChatPsychiatrist-master/fastchat/serve/api_provider.py\",\"language\":\"py\",\"content\":\"\\\"\\\"\\\"Call API providers.\\\"\\\"\\\"\\n\\nimport os\\nimport random\\nimport time\\n\\nfrom fastchat.utils import build_logger\\nfrom fastchat.constants import WORKER_API_TIMEOUT\\n\\n\\nlogger = build_logger(\\\"gradio_web_server\\\", \\\"gradio_web_server.log\\\")\\n\\n\\ndef openai_api_stream_iter(model_name, messages, temperature, top_p, max_new_tokens):\\n    import openai\\n\\n    # Make requests\\n    gen_params = {\\n        \\\"model\\\": model_name,\\n        \\\"prompt\\\": messages,\\n        \\\"temperature\\\": temperature,\\n        \\\"top_p\\\": top_p,\\n    }\\n    logger.info(f\\\"==== request ====\\\\n{gen_params}\\\")\\n\\n    res = openai.ChatCompletion.create(\\n        model=model_name, messages=messages, temperature=temperature, stream=True\\n    )\\n    text = \\\"\\\"\\n    for chunk in res:\\n        text += chunk[\\\"choices\\\"][0][\\\"delta\\\"].get(\\\"content\\\", \\\"\\\")\\n        data = {\\n            \\\"text\\\": text,\\n            \\\"error_code\\\": 0,\\n        }\\n        yield data\\n\\n\\ndef anthropic_api_stream_iter(model_name, prompt, temperature, top_p, max_new_tokens):\\n    import anthropic\\n\\n    c = anthropic.Anthropic(api_key=os.environ[\\\"ANTHROPIC_API_KEY\\\"])\\n\\n    # Make requests\\n    gen_params = {\\n        \\\"model\\\": model_name,\\n        \\\"prompt\\\": prompt,\\n        \\\"temperature\\\": temperature,\\n        \\\"top_p\\\": top_p,\\n    }\\n    logger.info(f\\\"==== request ====\\\\n{gen_params}\\\")\\n\\n    res = c.completions.create(\\n        prompt=prompt,\\n        stop_sequences=[anthropic.HUMAN_PROMPT],\\n        max_tokens_to_sample=max_new_tokens,\\n        temperature=temperature,\\n        top_p=top_p,\\n        model=model_name,\\n        stream=True,\\n    )\\n    text = \\\"\\\"\\n    for chunk in res:\\n        text += chunk.completion\\n        data = {\\n            \\\"text\\\": text,\\n            \\\"error_code\\\": 0,\\n        }\\n        yield data\\n\\n\\ndef bard_api_stream_iter(state):\\n    import requests\\n\\n    # TODO: we will use the official PaLM 2 API sooner or later,\\n    # and we will update this function accordingly. So here we just hard code the\\n    # Bard worker address. It is going to be deprecated anyway.\\n    conv = state.conv\\n\\n    # Make requests\\n    gen_params = {\\n        \\\"model\\\": \\\"bard\\\",\\n        \\\"prompt\\\": state.messages,\\n    }\\n    logger.info(f\\\"==== request ====\\\\n{gen_params}\\\")\\n\\n    response = requests.post(\\n        \\\"http://localhost:18900/chat\\\",\\n        json={\\n            \\\"content\\\": conv.messages[-2][-1],\\n            \\\"state\\\": state.bard_session_state,\\n        },\\n        stream=False,\\n        timeout=WORKER_API_TIMEOUT,\\n    )\\n    resp_json = response.json()\\n    state.bard_session_state = resp_json[\\\"state\\\"]\\n    content = resp_json[\\\"content\\\"]\\n    # The Bard Web API does not support streaming yet. Here we have to simulate\\n    # the streaming behavior by adding some time.sleep().\\n    pos = 0\\n    while pos < len(content):\\n        # This is a fancy way to simulate token generation latency combined\\n        # with a Poisson process.\\n        pos += random.randint(1, 5)\\n        time.sleep(random.expovariate(50))\\n        data = {\\n            \\\"text\\\": content[:pos],\\n            \\\"error_code\\\": 0,\\n        }\\n        yield data\\n\\n\\ndef init_palm_chat(model_name):\\n    import vertexai  # pip3 install google-cloud-aiplatform\\n    from vertexai.preview.language_models import ChatModel\\n\\n    project_id = os.environ[\\\"GCP_PROJECT_ID\\\"]\\n    location = \\\"us-central1\\\"\\n    vertexai.init(project=project_id, location=location)\\n\\n    chat_model = ChatModel.from_pretrained(model_name)\\n    chat = chat_model.start_chat(examples=[])\\n    return chat\\n\\n\\ndef palm_api_stream_iter(chat, message, temperature, top_p, max_new_tokens):\\n    parameters = {\\n        \\\"temperature\\\": temperature,\\n        \\\"top_p\\\": top_p,\\n        \\\"max_output_tokens\\\": max_new_tokens,\\n    }\\n    gen_params = {\\n        \\\"model\\\": \\\"palm-2\\\",\\n        \\\"prompt\\\": message,\\n    }\\n    gen_params.update(parameters)\\n    logger.info(f\\\"==== request ====\\\\n{gen_params}\\\")\\n\\n    response = chat.send_message(message, **parameters)\\n    content = response.text\\n\\n    pos = 0\\n    while pos < len(content):\\n        # This is a fancy way to simulate token generation latency combined\\n        # with a Poisson process.\\n        pos += random.randint(10, 20)\\n        time.sleep(random.expovariate(50))\\n        data = {\\n            \\\"text\\\": content[:pos],\\n            \\\"error_code\\\": 0,\\n        }\\n        yield data\\n\"},{\"source_archive\":\"Unified_Psychiatric_AI_Brain_Part1.zip\",\"source_path\":\"source_projects/ChatPsychiatrist-master/ChatPsychiatrist-master/fastchat/serve/cli.py\",\"language\":\"py\",\"content\":\"\\\"\\\"\\\"\\nChat with a model with command line interface.\\n\\nUsage:\\npython3 -m fastchat.serve.cli --model lmsys/vicuna-7b-v1.3\\npython3 -m fastchat.serve.cli --model lmsys/fastchat-t5-3b-v1.0\\n\\nOther commands:\\n- Type \\\"!!exit\\\" or an empty line to exit.\\n- Type \\\"!!reset\\\" to start a new conversation.\\n\\\"\\\"\\\"\\nimport argparse\\nimport os\\nimport re\\nimport sys\\n\\nfrom prompt_toolkit import PromptSession\\nfrom prompt_toolkit.auto_suggest import AutoSuggestFromHistory\\nfrom prompt_toolkit.completion import WordCompleter\\nfrom prompt_toolkit.history import InMemoryHistory\\nfrom prompt_toolkit.key_binding import KeyBindings\\nfrom rich.console import Console\\nfrom rich.live import Live\\nfrom rich.markdown import Markdown\\n\\nfrom fastchat.model.model_adapter import add_model_args\\nfrom fastchat.modules.gptq import GptqConfig\\nfrom fastchat.serve.inference import ChatIO, chat_loop\\n\\n\\nclass SimpleChatIO(ChatIO):\\n    def __init__(self, multiline: bool = False):\\n        self._multiline = multiline\\n\\n    def prompt_for_input(self, role) -> str:\\n        if not self._multiline:\\n            return input(f\\\"{role}: \\\")\\n\\n        prompt_data = []\\n        line = input(f\\\"{role} [ctrl-d/z on empty line to end]: \\\")\\n        while True:\\n            prompt_data.append(line.strip())\\n            try:\\n                line = input()\\n            except EOFError as e:\\n                break\\n        return \\\"\\\\n\\\".join(prompt_data)\\n\\n    def prompt_for_output(self, role: str):\\n        print(f\\\"{role}: \\\", end=\\\"\\\", flush=True)\\n\\n    def stream_output(self, output_stream):\\n        pre = 0\\n        for outputs in output_stream:\\n            output_text = outputs[\\\"text\\\"]\\n            output_text = output_text.strip().split(\\\" \\\")\\n            now = len(output_text) - 1\\n            if now > pre:\\n                print(\\\" \\\".join(output_text[pre:now]), end=\\\" \\\", flush=True)\\n                pre = now\\n        print(\\\" \\\".join(output_text[pre:]), flush=True)\\n        return \\\" \\\".join(output_text)\\n\\n\\nclass RichChatIO(ChatIO):\\n    bindings = KeyBindings()\\n\\n    @bindings.add(\\\"escape\\\", \\\"enter\\\")\\n    def _(event):\\n        event.app.current_buffer.newline()\\n\\n    def __init__(self, multiline: bool = False, mouse: bool = False):\\n        self._prompt_session = PromptSession(history=InMemoryHistory())\\n        self._completer = WordCompleter(\\n            words=[\\\"!!exit\\\", \\\"!!reset\\\"], pattern=re.compile(\\\"$\\\")\\n        )\\n        self._console = Console()\\n        self._multiline = multiline\\n        self._mouse = mouse\\n\\n    def prompt_for_input(self, role) -> str:\\n        self._console.print(f\\\"[bold]{role}:\\\")\\n        # TODO(suquark): multiline input has some issues. fix it later.\\n        prompt_input = self._prompt_session.prompt(\\n            completer=self._completer,\\n            multiline=False,\\n            mouse_support=self._mouse,\\n            auto_suggest=AutoSuggestFromHistory(),\\n            key_bindings=self.bindings if self._multiline else None,\\n        )\\n        self._console.print()\\n        return prompt_input\\n\\n    def prompt_for_output(self, role: str):\\n        self._console.print(f\\\"[bold]{role}:\\\")\\n\\n    def stream_output(self, output_stream):\\n        \\\"\\\"\\\"Stream output from a role.\\\"\\\"\\\"\\n        # TODO(suquark): the console flickers when there is a code block\\n        #  above it. We need to cut off \\\"live\\\" when a code block is done.\\n\\n        # Create a Live context for updating the console output\\n        with Live(console=self._console, refresh_per_second=4) as live:\\n            # Read lines from the stream\\n            for outputs in output_stream:\\n                if not outputs:\\n                    continue\\n                text = outputs[\\\"text\\\"]\\n                # Render the accumulated text as Markdown\\n                # NOTE: this is a workaround for the rendering \\\"unstandard markdown\\\"\\n                #  in rich. The chatbots output treat \\\"\\\\n\\\" as a new line for\\n                #  better compatibility with real-world text. However, rendering\\n                #  in markdown would break the format. It is because standard markdown\\n                #  treat a single \\\"\\\\n\\\" in normal text as a space.\\n                #  Our workaround is adding two spaces at the end of each line.\\n                #  This is not a perfect solution, as it would\\n                #  introduce trailing spaces (only) in code block, but it works well\\n                #  especially for console output, because in general the console does not\\n                #  care about trailing spaces.\\n                lines = []\\n                for line in text.splitlines():\\n                    lines.append(line)\\n                    if line.startswith(\\\"```\\\"):\\n                        # Code block marker - do not add trailing spaces, as it would\\n                        #  break the syntax highlighting\\n                        lines.append(\\\"\\\\n\\\")\\n                    else:\\n                        lines.append(\\\"  \\\\n\\\")\\n                markdown = Markdown(\\\"\\\".join(lines))\\n                # Update the Live console output\\n                live.update(markdown)\\n        self._console.print()\\n        return text\\n\\n\\nclass ProgrammaticChatIO(ChatIO):\\n    def prompt_for_input(self, role) -> str:\\n        contents = \\\"\\\"\\n        # `end_sequence` signals the end of a message. It is unlikely to occur in\\n        #  message content.\\n        end_sequence = \\\" __END_OF_A_MESSAGE_47582648__\\\\n\\\"\\n        len_end = len(end_sequence)\\n        while True:\\n            if len(contents) >= len_end:\\n                last_chars = contents[-len_end:]\\n                if last_chars == end_sequence:\\n                    break\\n            try:\\n                char = sys.stdin.read(1)\\n                contents = contents + char\\n            except EOFError:\\n                continue\\n        contents = contents[:-len_end]\\n        print(f\\\"[!OP:{role}]: {contents}\\\", flush=True)\\n        return contents\\n\\n    def prompt_for_output(self, role: str):\\n        print(f\\\"[!OP:{role}]: \\\", end=\\\"\\\", flush=True)\\n\\n    def stream_output(self, output_stream):\\n        pre = 0\\n        for outputs in output_stream:\\n            output_text = outputs[\\\"text\\\"]\\n            output_text = output_text.strip().split(\\\" \\\")\\n            now = len(output_text) - 1\\n            if now > pre:\\n                print(\\\" \\\".join(output_text[pre:now]), end=\\\" \\\", flush=True)\\n                pre = now\\n        print(\\\" \\\".join(output_text[pre:]), flush=True)\\n        return \\\" \\\".join(output_text)\\n\\n\\ndef main(args):\\n    if args.gpus:\\n        if len(args.gpus.split(\\\",\\\")) < args.num_gpus:\\n            raise ValueError(\\n                f\\\"Larger --num-gpus ({args.num_gpus}) than --gpus {args.gpus}!\\\"\\n            )\\n        os.environ[\\\"CUDA_VISIBLE_DEVICES\\\"] = args.gpus\\n        os.environ[\\\"XPU_VISIBLE_DEVICES\\\"] = args.gpus\\n\\n    if args.style == \\\"simple\\\":\\n        chatio = SimpleChatIO(args.multiline)\\n    elif args.style == \\\"rich\\\":\\n        chatio = RichChatIO(args.multiline, args.mouse)\\n    elif args.style == \\\"programmatic\\\":\\n        chatio = ProgrammaticChatIO()\\n    else:\\n        raise ValueError(f\\\"Invalid style for console: {args.style}\\\")\\n    try:\\n        chat_loop(\\n            args.model_path,\\n            args.device,\\n            args.num_gpus,\\n            args.max_gpu_memory,\\n            args.load_8bit,\\n            args.cpu_offloading,\\n            args.conv_template,\\n            args.temperature,\\n            args.repetition_penalty,\\n            args.max_new_tokens,\\n            chatio,\\n            GptqConfig(\\n                ckpt=args.gptq_ckpt or args.model_path,\\n                wbits=args.gptq_wbits,\\n                groupsize=args.gptq_groupsize,\\n                act_order=args.gptq_act_order,\\n            ),\\n            args.revision,\\n            args.judge_sent_end,\\n            args.debug,\\n            history=not args.no_history,\\n        )\\n    except KeyboardInterrupt:\\n        print(\\\"exit...\\\")\\n\\n\\nif __name__ == \\\"__main__\\\":\\n    parser = argparse.ArgumentParser()\\n    add_model_args(parser)\\n    parser.add_argument(\\n        \\\"--conv-template\\\", type=str, default=None, help=\\\"Conversation prompt template.\\\"\\n    )\\n    parser.add_argument(\\\"--temperature\\\", type=float, default=0.7)\\n    parser.add_argument(\\\"--repetition_penalty\\\", type=float, default=1.0)\\n    parser.add_argument(\\\"--max-new-tokens\\\", type=int, default=512)\\n    parser.add_argument(\\\"--no-history\\\", action=\\\"store_true\\\")\\n    parser.add_argument(\\n        \\\"--style\\\",\\n        type=str,\\n        default=\\\"simple\\\",\\n        choices=[\\\"simple\\\", \\\"rich\\\", \\\"programmatic\\\"],\\n        help=\\\"Display style.\\\",\\n    )\\n    parser.add_argument(\\n        \\\"--multiline\\\",\\n        action=\\\"store_true\\\",\\n        help=\\\"Enable multiline input. Use ESC+Enter for newline.\\\",\\n    )\\n    parser.add_argument(\\n        \\\"--mouse\\\",\\n        action=\\\"store_true\\\",\\n        help=\\\"[Rich Style]: Enable mouse support for cursor positioning.\\\",\\n    )\\n    parser.add_argument(\\n        \\\"--judge-sent-end\\\",\\n        action=\\\"store_true\\\",\\n        help=\\\"Whether enable the correction logic that interrupts the output of sentences due to EOS.\\\",\\n    )\\n    parser.add_argument(\\n        \\\"--debug\\\",\\n        action=\\\"store_true\\\",\\n        help=\\\"Print useful debug information (e.g., prompts)\\\",\\n    )\\n    args = parser.parse_args()\\n    main(args)\\n\"},{\"source_archive\":\"Unified_Psychiatric_AI_Brain_Part1.zip\",\"source_path\":\"source_projects/ChatPsychiatrist-master/ChatPsychiatrist-master/fastchat/serve/bard_worker.py\",\"language\":\"py\",\"content\":\"\\\"\\\"\\\"\\nAdapted from https://github.com/acheong08/Bard.\\n\\\"\\\"\\\"\\nimport argparse\\nimport json\\nimport random\\nimport re\\nimport string\\n\\nfrom fastapi import FastAPI\\nimport httpx\\nfrom pydantic import BaseModel, Field\\nfrom typing import List, Optional, Union\\nimport uvicorn\\n\\n\\nclass ConversationState(BaseModel):\\n    conversation_id: str = \\\"\\\"\\n    response_id: str = \\\"\\\"\\n    choice_id: str = \\\"\\\"\\n    req_id: int = 0\\n\\n\\nclass Message(BaseModel):\\n    content: str\\n    state: ConversationState = Field(default_factory=ConversationState)\\n\\n\\nclass Response(BaseModel):\\n    content: str\\n    factualityQueries: Optional[List]\\n    textQuery: Optional[Union[str, List]]\\n    choices: List[dict]\\n    state: ConversationState\\n\\n\\nclass Chatbot:\\n    \\\"\\\"\\\"\\n    A class to interact with Google Bard.\\n    Parameters\\n        session_id: str\\n            The __Secure-1PSID cookie.\\n    \\\"\\\"\\\"\\n\\n    def __init__(self, session_id):\\n        headers = {\\n            \\\"Host\\\": \\\"bard.google.com\\\",\\n            \\\"X-Same-Domain\\\": \\\"1\\\",\\n            \\\"User-Agent\\\": \\\"Mozilla/5.0 (Windows NT 10.0; WOW64) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/91.0.4472.114 Safari/537.36\\\",\\n            \\\"Content-Type\\\": \\\"application/x-www-form-urlencoded;charset=UTF-8\\\",\\n            \\\"Origin\\\": \\\"https://bard.google.com\\\",\\n            \\\"Referer\\\": \\\"https://bard.google.com/\\\",\\n        }\\n        self.session = httpx.AsyncClient()\\n        self.session.headers = headers\\n        self.session.cookies.set(\\\"__Secure-1PSID\\\", session_id)\\n        self.SNlM0e = None\\n\\n    async def _get_snlm0e(self):\\n        resp = await self.session.get(url=\\\"https://bard.google.com/\\\", timeout=10)\\n        # Find \\\"SNlM0e\\\":\\\"<ID>\\\"\\n        if resp.status_code != 200:\\n            raise Exception(\\\"Could not get Google Bard\\\")\\n        SNlM0e = re.search(r\\\"SNlM0e\\\\\\\":\\\\\\\"(.*?)\\\\\\\"\\\", resp.text).group(1)\\n        return SNlM0e\\n\\n    async def ask(self, message: Message) -> Response:\\n        \\\"\\\"\\\"\\n        Send a message to Google Bard and return the response.\\n        :param message: The message to send to Google Bard.\\n        :return: A dict containing the response from Google Bard.\\n        \\\"\\\"\\\"\\n        if message.state.conversation_id == \\\"\\\":\\n            message.state.req_id = int(\\\"\\\".join(random.choices(string.digits, k=4)))\\n        # url params\\n        params = {\\n            # \\\"bl\\\": \\\"boq_assistant-bard-web-server_20230315.04_p2\\\",\\n            # This is a newer API version\\n            \\\"bl\\\": \\\"boq_assistant-bard-web-server_20230507.20_p2\\\",\\n            \\\"_reqid\\\": str(message.state.req_id),\\n            \\\"rt\\\": \\\"c\\\",\\n        }\\n\\n        # message arr -> data[\\\"f.req\\\"]. Message is double json stringified\\n        message_struct = [\\n            [message.content],\\n            None,\\n            [\\n                message.state.conversation_id,\\n                message.state.response_id,\\n                message.state.choice_id,\\n            ],\\n        ]\\n        data = {\\n            \\\"f.req\\\": json.dumps([None, json.dumps(message_struct)]),\\n            \\\"at\\\": self.SNlM0e,\\n        }\\n\\n        # do the request!\\n        resp = await self.session.post(\\n            \\\"https://bard.google.com/_/BardChatUi/data/assistant.lamda.BardFrontendService/StreamGenerate\\\",\\n            params=params,\\n            data=data,\\n            timeout=60,\\n        )\\n\\n        chat_data = json.loads(resp.content.splitlines()[3])[0][2]\\n        if not chat_data:\\n            return Response(\\n                content=f\\\"Google Bard encountered an error: {resp.content}.\\\",\\n                factualityQueries=[],\\n                textQuery=\\\"\\\",\\n                choices=[],\\n                state=message.state,\\n            )\\n        json_chat_data = json.loads(chat_data)\\n        conversation = ConversationState(\\n            conversation_id=json_chat_data[1][0],\\n            response_id=json_chat_data[1][1],\\n            choice_id=json_chat_data[4][0][0],\\n            req_id=message.state.req_id + 100000,\\n        )\\n        return Response(\\n            content=json_chat_data[0][0],\\n            factualityQueries=json_chat_data[3],\\n            textQuery=json_chat_data[2][0] if json_chat_data[2] is not None else \\\"\\\",\\n            choices=[{\\\"id\\\": i[0], \\\"content\\\": i[1]} for i in json_chat_data[4]],\\n            state=conversation,\\n        )\\n\\n\\napp = FastAPI()\\nchatbot = None\\n\\n\\n@app.on_event(\\\"startup\\\")\\nasync def startup_event():\\n    global chatbot\\n    cookie = json.load(open(\\\"bard_cookie.json\\\"))\\n    chatbot = Chatbot(cookie[\\\"__Secure-1PSID\\\"])\\n    chatbot.SNlM0e = await chatbot._get_snlm0e()\\n\\n\\n@app.post(\\\"/chat\\\", response_model=Response)\\nasync def chat(message: Message):\\n    response = await chatbot.ask(message)\\n    return response\\n\\n\\nif __name__ == \\\"__main__\\\":\\n    parser = argparse.ArgumentParser(\\\"Google Bard worker\\\")\\n    parser.add_argument(\\\"--host\\\", type=str, default=\\\"localhost\\\")\\n    parser.add_argument(\\\"--port\\\", type=int, default=18900)\\n    parser.add_argument(\\\"--reload\\\", action=\\\"store_true\\\")\\n    args = parser.parse_args()\\n    uvicorn.run(\\n        \\\"bard_worker:app\\\",\\n        host=args.host,\\n        port=args.port,\\n        log_level=\\\"info\\\",\\n        reload=args.reload,\\n    )\\n\"},{\"source_archive\":\"Unified_Psychiatric_AI_Brain_Part1.zip\",\"source_path\":\"source_projects/ChatPsychiatrist-master/ChatPsychiatrist-master/fastchat/serve/test_throughput.py\",\"language\":\"py\",\"content\":\"\\\"\\\"\\\"Benchmarking script to test the throughput of serving workers.\\\"\\\"\\\"\\nimport argparse\\nimport json\\n\\nimport requests\\nimport threading\\nimport time\\n\\nfrom fastchat.conversation import get_conv_template\\n\\n\\ndef main():\\n    if args.worker_address:\\n        worker_addr = args.worker_address\\n    else:\\n        controller_addr = args.controller_address\\n        ret = requests.post(controller_addr + \\\"/refresh_all_workers\\\")\\n        ret = requests.post(controller_addr + \\\"/list_models\\\")\\n        models = ret.json()[\\\"models\\\"]\\n        models.sort()\\n        print(f\\\"Models: {models}\\\")\\n\\n        ret = requests.post(\\n            controller_addr + \\\"/get_worker_address\\\", json={\\\"model\\\": args.model_name}\\n        )\\n        worker_addr = ret.json()[\\\"address\\\"]\\n        print(f\\\"worker_addr: {worker_addr}\\\")\\n\\n    if worker_addr == \\\"\\\":\\n        return\\n\\n    conv = get_conv_template(\\\"vicuna_v1.1\\\")\\n    conv.append_message(conv.roles[0], \\\"Tell me a story with more than 1000 words\\\")\\n    prompt_template = conv.get_prompt()\\n    prompts = [prompt_template for _ in range(args.n_thread)]\\n\\n    headers = {\\\"User-Agent\\\": \\\"fastchat Client\\\"}\\n    ploads = [\\n        {\\n            \\\"model\\\": args.model_name,\\n            \\\"prompt\\\": prompts[i],\\n            \\\"max_new_tokens\\\": args.max_new_tokens,\\n            \\\"temperature\\\": 0.0,\\n            # \\\"stop\\\": conv.sep,\\n        }\\n        for i in range(len(prompts))\\n    ]\\n\\n    def send_request(results, i):\\n        if args.test_dispatch:\\n            ret = requests.post(\\n                controller_addr + \\\"/get_worker_address\\\", json={\\\"model\\\": args.model_name}\\n            )\\n            thread_worker_addr = ret.json()[\\\"address\\\"]\\n        else:\\n            thread_worker_addr = worker_addr\\n        print(f\\\"thread {i} goes to {thread_worker_addr}\\\")\\n        response = requests.post(\\n            thread_worker_addr + \\\"/worker_generate_stream\\\",\\n            headers=headers,\\n            json=ploads[i],\\n            stream=False,\\n        )\\n        k = list(\\n            response.iter_lines(chunk_size=8192, decode_unicode=False, delimiter=b\\\"\\\\0\\\")\\n        )\\n        # print(k)\\n        response_new_words = json.loads(k[-2].decode(\\\"utf-8\\\"))[\\\"text\\\"]\\n        error_code = json.loads(k[-2].decode(\\\"utf-8\\\"))[\\\"error_code\\\"]\\n        # print(f\\\"=== Thread {i} ===, words: {1}, error code: {error_code}\\\")\\n        results[i] = len(response_new_words.split(\\\" \\\")) - len(prompts[i].split(\\\" \\\"))\\n\\n    # use N threads to prompt the backend\\n    tik = time.time()\\n    threads = []\\n    results = [None] * args.n_thread\\n    for i in range(args.n_thread):\\n        t = threading.Thread(target=send_request, args=(results, i))\\n        t.start()\\n        # time.sleep(0.5)\\n        threads.append(t)\\n\\n    for t in threads:\\n        t.join()\\n\\n    print(f\\\"Time (POST): {time.time() - tik} s\\\")\\n    # n_words = 0\\n    # for i, response in enumerate(results):\\n    #     # print(prompt[i].replace(conv.sep, \\\"\\\\n\\\"), end=\\\"\\\")\\n    #     # make sure the streaming finishes at EOS or stopping criteria\\n    #     k = list(response.iter_lines(chunk_size=8192, decode_unicode=False, delimiter=b\\\"\\\\0\\\"))\\n    #     response_new_words = json.loads(k[-2].decode(\\\"utf-8\\\"))[\\\"text\\\"]\\n    #     # print(response_new_words)\\n    #     n_words += len(response_new_words.split(\\\" \\\")) - len(prompts[i].split(\\\" \\\"))\\n    n_words = sum(results)\\n    time_seconds = time.time() - tik\\n    print(\\n        f\\\"Time (Completion): {time_seconds}, n threads: {args.n_thread}, \\\"\\n        f\\\"throughput: {n_words / time_seconds} words/s.\\\"\\n    )\\n\\n\\nif __name__ == \\\"__main__\\\":\\n    parser = argparse.ArgumentParser()\\n    parser.add_argument(\\n        \\\"--controller-address\\\", type=str, default=\\\"http://localhost:21001\\\"\\n    )\\n    parser.add_argument(\\\"--worker-address\\\", type=str)\\n    parser.add_argument(\\\"--model-name\\\", type=str, default=\\\"vicuna\\\")\\n    parser.add_argument(\\\"--max-new-tokens\\\", type=int, default=2048)\\n    parser.add_argument(\\\"--n-thread\\\", type=int, default=8)\\n    parser.add_argument(\\\"--test-dispatch\\\", action=\\\"store_true\\\")\\n    args = parser.parse_args()\\n\\n    main()\\n\"},{\"source_archive\":\"Unified_Psychiatric_AI_Brain_Part1.zip\",\"source_path\":\"source_projects/ChatPsychiatrist-master/ChatPsychiatrist-master/fastchat/serve/multi_model_worker.py\",\"language\":\"py\",\"content\":\"\\\"\\\"\\\"\\nA multi-model worker that contains multiple sub-works one for each model.  This\\nsupports running a list of models on the same machine so that they can\\n(potentially) share the same background weights.\\n\\nEach model can have one or more model names.\\n\\nThis multi-model worker assumes the models shares some underlying weights and\\nthus reports the combined queue lengths for health checks.\\n\\nWe recommend using this with multiple Peft models (with `peft` in the name)\\nwhere all Peft models are trained on the exact same base model.\\n\\\"\\\"\\\"\\nimport argparse\\nimport asyncio\\nimport dataclasses\\nimport logging\\nimport json\\nimport os\\nimport time\\nfrom typing import List, Union\\nimport threading\\nimport uuid\\n\\nfrom fastapi import FastAPI, Request, BackgroundTasks\\nfrom fastapi.responses import StreamingResponse, JSONResponse\\nimport requests\\n\\ntry:\\n    from transformers import (\\n        AutoTokenizer,\\n        AutoModelForCausalLM,\\n        LlamaTokenizer,\\n        AutoModel,\\n    )\\nexcept ImportError:\\n    from transformers import (\\n        AutoTokenizer,\\n        AutoModelForCausalLM,\\n        LLaMATokenizer,\\n        AutoModel,\\n    )\\nimport torch\\nimport torch.nn.functional as F\\nimport uvicorn\\n\\nfrom fastchat.constants import WORKER_HEART_BEAT_INTERVAL, ErrorCode, SERVER_ERROR_MSG\\nfrom fastchat.model.model_adapter import (\\n    load_model,\\n    add_model_args,\\n    get_conversation_template,\\n)\\nfrom fastchat.model.model_chatglm import generate_stream_chatglm\\nfrom fastchat.model.model_falcon import generate_stream_falcon\\nfrom fastchat.model.model_codet5p import generate_stream_codet5p\\nfrom fastchat.modules.gptq import GptqConfig\\nfrom fastchat.serve.inference import generate_stream\\nfrom fastchat.serve.model_worker import ModelWorker, worker_id, logger\\nfrom fastchat.utils import build_logger, pretty_print_semaphore, get_context_length\\n\\n\\n# We store both the underlying workers and a mapping from their model names to\\n# the worker instance.  This makes it easy to fetch the appropriate worker for\\n# each API call.\\nworkers = []\\nworker_map = {}\\napp = FastAPI()\\n\\n\\ndef release_worker_semaphore():\\n    workers[0].semaphore.release()\\n\\n\\ndef acquire_worker_semaphore():\\n    if workers[0].semaphore is None:\\n        # Share the same semaphore for all workers because\\n        # all workers share the same GPU.\\n        semaphore = asyncio.Semaphore(workers[0].limit_worker_concurrency)\\n        for w in workers:\\n            w.semaphore = semaphore\\n    return workers[0].semaphore.acquire()\\n\\n\\ndef create_background_tasks():\\n    background_tasks = BackgroundTasks()\\n    background_tasks.add_task(release_worker_semaphore)\\n    return background_tasks\\n\\n\\n# Note: for all the calls below, we make a hard assumption that the caller\\n# includes the model name in the payload, otherwise we can't figure out which\\n# underlying sub-worker to call.\\n\\n\\n@app.post(\\\"/worker_generate_stream\\\")\\nasync def api_generate_stream(request: Request):\\n    params = await request.json()\\n    await acquire_worker_semaphore()\\n    worker = worker_map[params[\\\"model\\\"]]\\n    generator = worker.generate_stream_gate(params)\\n    background_tasks = create_background_tasks()\\n    return StreamingResponse(generator, background=background_tasks)\\n\\n\\n@app.post(\\\"/worker_generate\\\")\\nasync def api_generate(request: Request):\\n    params = await request.json()\\n    await acquire_worker_semaphore()\\n    worker = worker_map[params[\\\"model\\\"]]\\n    output = worker.generate_gate(params)\\n    release_worker_semaphore()\\n    return JSONResponse(output)\\n\\n\\n@app.post(\\\"/worker_get_embeddings\\\")\\nasync def api_get_embeddings(request: Request):\\n    params = await request.json()\\n    await acquire_worker_semaphore()\\n    worker = worker_map[params[\\\"model\\\"]]\\n    embedding = worker.get_embeddings(params)\\n    background_tasks = create_background_tasks()\\n    return JSONResponse(content=embedding, background=background_tasks)\\n\\n\\n@app.post(\\\"/worker_get_status\\\")\\nasync def api_get_status(request: Request):\\n    return {\\n        \\\"model_names\\\": [m for w in workers for m in w.model_names],\\n        \\\"speed\\\": 1,\\n        \\\"queue_length\\\": sum([w.get_queue_length() for w in workers]),\\n    }\\n\\n\\n@app.post(\\\"/count_token\\\")\\nasync def api_count_token(request: Request):\\n    params = await request.json()\\n    worker = worker_map[params[\\\"model\\\"]]\\n    return worker.count_token(params)\\n\\n\\n@app.post(\\\"/worker_get_conv_template\\\")\\nasync def api_get_conv(request: Request):\\n    params = await request.json()\\n    worker = worker_map[params[\\\"model\\\"]]\\n    return worker.get_conv_template()\\n\\n\\n@app.post(\\\"/model_details\\\")\\nasync def api_model_details(request: Request):\\n    params = await request.json()\\n    worker = worker_map[params[\\\"model\\\"]]\\n    return {\\\"context_length\\\": worker.context_len}\\n\\n\\nif __name__ == \\\"__main__\\\":\\n    # Note: Ensure we resolve arg conflicts.  We let `add_model_args` add MOST\\n    # of the model args but we'll override one to have an append action that\\n    # supports multiple values.\\n    parser = argparse.ArgumentParser(conflict_handler=\\\"resolve\\\")\\n    parser.add_argument(\\\"--host\\\", type=str, default=\\\"localhost\\\")\\n    parser.add_argument(\\\"--port\\\", type=int, default=21002)\\n    parser.add_argument(\\\"--worker-address\\\", type=str, default=\\\"http://localhost:21002\\\")\\n    parser.add_argument(\\n        \\\"--controller-address\\\", type=str, default=\\\"http://localhost:21001\\\"\\n    )\\n    add_model_args(parser)\\n    # Override the model path to be repeated and align it with model names.\\n    parser.add_argument(\\n        \\\"--model-path\\\",\\n        type=str,\\n        default=[],\\n        action=\\\"append\\\",\\n        help=\\\"One or more paths to model weights to load. This can be a local folder or a Hugging Face repo ID.\\\",\\n    )\\n    parser.add_argument(\\n        \\\"--model-names\\\",\\n        type=lambda s: s.split(\\\",\\\"),\\n        action=\\\"append\\\",\\n        help=\\\"One or more model names.  Values must be aligned with `--model-path` values.\\\",\\n    )\\n    parser.add_argument(\\\"--limit-worker-concurrency\\\", type=int, default=5)\\n    parser.add_argument(\\\"--stream-interval\\\", type=int, default=2)\\n    parser.add_argument(\\\"--no-register\\\", action=\\\"store_true\\\")\\n    args = parser.parse_args()\\n    logger.info(f\\\"args: {args}\\\")\\n\\n    if args.gpus:\\n        if len(args.gpus.split(\\\",\\\")) < args.num_gpus:\\n            raise ValueError(\\n                f\\\"Larger --num-gpus ({args.num_gpus}) than --gpus {args.gpus}!\\\"\\n            )\\n        os.environ[\\\"CUDA_VISIBLE_DEVICES\\\"] = args.gpus\\n\\n    gptq_config = GptqConfig(\\n        ckpt=args.gptq_ckpt or args.model_path,\\n        wbits=args.gptq_wbits,\\n        groupsize=args.gptq_groupsize,\\n        act_order=args.gptq_act_order,\\n    )\\n\\n    if args.model_names is None:\\n        args.model_names = [[x.split(\\\"/\\\")[-1]] for x in args.model_path]\\n\\n    # Launch all workers\\n    workers = []\\n    for model_path, model_names in zip(args.model_path, args.model_names):\\n        w = ModelWorker(\\n            args.controller_address,\\n            args.worker_address,\\n            worker_id,\\n            model_path,\\n            model_names,\\n            args.limit_worker_concurrency,\\n            args.no_register,\\n            device=args.device,\\n            num_gpus=args.num_gpus,\\n            max_gpu_memory=args.max_gpu_memory,\\n            load_8bit=args.load_8bit,\\n            cpu_offloading=args.cpu_offloading,\\n            gptq_config=gptq_config,\\n            stream_interval=args.stream_interval,\\n        )\\n        workers.append(w)\\n        for model_name in model_names:\\n            worker_map[model_name] = w\\n\\n    # Register all models\\n    url = args.controller_address + \\\"/register_worker\\\"\\n    data = {\\n        \\\"worker_name\\\": workers[0].worker_addr,\\n        \\\"check_heart_beat\\\": not args.no_register,\\n        \\\"worker_status\\\": {\\n            \\\"model_names\\\": [m for w in workers for m in w.model_names],\\n            \\\"speed\\\": 1,\\n            \\\"queue_length\\\": sum([w.get_queue_length() for w in workers]),\\n        },\\n    }\\n    r = requests.post(url, json=data)\\n    assert r.status_code == 200\\n\\n    uvicorn.run(app, host=args.host, port=args.port, log_level=\\\"info\\\")\\n\"},{\"source_archive\":\"Unified_Psychiatric_AI_Brain_Part1.zip\",\"source_path\":\"source_projects/ChatPsychiatrist-master/ChatPsychiatrist-master/fastchat/serve/monitor/conv_release_scripts/upload_hf_dataset.py\",\"language\":\"py\",\"content\":\"\\\"\\\"\\\"\\nUpload to huggingface.\\n\\\"\\\"\\\"\\nimport json\\nfrom datasets import Dataset, DatasetDict, load_dataset\\n\\nobjs = json.load(open(\\\"clean_battle_conv_20230630_tagged_v3_pii_33k_added.json\\\"))\\ndata = Dataset.from_list(objs)\\ndata.push_to_hub(\\\"lmsys/chatbot_arena_conversations\\\", private=True)\\n\"},{\"source_archive\":\"Unified_Psychiatric_AI_Brain_Part1.zip\",\"source_path\":\"source_projects/ChatPsychiatrist-master/ChatPsychiatrist-master/fastchat/serve/monitor/conv_release_scripts/merge_field.py\",\"language\":\"py\",\"content\":\"\\\"\\\"\\\"Count the unique users in a battle log file.\\\"\\\"\\\"\\n\\nimport argparse\\nimport json\\n\\n\\nif __name__ == \\\"__main__\\\":\\n    parser = argparse.ArgumentParser()\\n    parser.add_argument(\\\"--input\\\", type=str)\\n    parser.add_argument(\\\"--tag-file\\\", type=str)\\n    args = parser.parse_args()\\n\\n    # build index\\n    objs = json.load(open(args.tag_file))\\n    new_field_dict = {}\\n    for obj in objs:\\n        new_field_dict[obj[\\\"question_id\\\"]] = obj[\\\"toxic_chat\\\"]\\n\\n    objs = json.load(open(args.input))\\n    for obj in objs:\\n        obj[\\\"toxic_chat_tag\\\"] = new_field_dict[obj[\\\"question_id\\\"]]\\n\\n    output = args.input.replace(\\\".json\\\", \\\"_added.json\\\")\\n    with open(output, \\\"w\\\") as fout:\\n        json.dump(objs, fout, indent=2, ensure_ascii=False)\\n\"},{\"source_archive\":\"Unified_Psychiatric_AI_Brain_Part1.zip\",\"source_path\":\"source_projects/ChatPsychiatrist-master/ChatPsychiatrist-master/fastchat/serve/monitor/conv_release_scripts/filter_bad_conv.py\",\"language\":\"py\",\"content\":\"\\\"\\\"\\\"\\nFilter conversations for release.\\n\\nUsage: python3 filter_bad_conv.py --in clean_battle_conv_20230630_tagged_v1_pii.json\\n\\\"\\\"\\\"\\nimport argparse\\nfrom collections import defaultdict\\nfrom enum import Enum, auto\\nimport json\\nimport os\\nimport random\\n\\nfrom tqdm import tqdm\\n\\nBLOCKED_WORDS_FILENAME = \\\"blocked_words.json\\\"\\nblocked_words = []\\nfrequency = defaultdict(lambda: 0)\\n\\n\\nclass TypeCode(Enum):\\n    CORRECT = auto()\\n    ANONYMIZED = auto()\\n    REDACTED = auto()\\n    BAD_FORMAT = auto()\\n    BLOCKED_WORD = auto()\\n    BLOCKED_MODEL = auto()\\n    TOO_SHORT = auto()\\n    TOO_FREQUENT = auto()\\n\\n\\ndef detect_type(conv):\\n    for key in [\\\"conversation_a\\\", \\\"conversation_b\\\"]:\\n        messages = [row[\\\"content\\\"] for row in conv[key]]\\n        for msg in messages:\\n            if not isinstance(msg, str):\\n                return TypeCode.BAD_FORMAT\\n\\n        user_prompts = [\\n            row[\\\"content\\\"].lower().strip() for row in conv[key] if row[\\\"role\\\"] == \\\"user\\\"\\n        ]\\n        if len(messages) <= 2 and all(len(x) < 16 for x in user_prompts):\\n            return TypeCode.TOO_SHORT\\n\\n        if all(x in frequent_prompts for x in user_prompts):\\n            return TypeCode.TOO_FREQUENT\\n\\n        for msg in messages:\\n            msg = msg.lower()\\n            if \\\"<anonymized>\\\" in msg:\\n                return TypeCode.ANONYMIZED\\n            if \\\"<redacted>\\\" in msg:\\n                return TypeCode.REDACTED\\n\\n            for w in blocked_words:\\n                if w in msg:\\n                    return TypeCode.BLOCKED_WORD\\n\\n    for key in [\\\"model_a\\\", \\\"model_b\\\"]:\\n        if conv[key] in [\\\"vicuna-33b\\\", \\\"mpt-30b-chat\\\"]:\\n            return TypeCode.BLOCKED_MODEL\\n\\n    return TypeCode.CORRECT\\n\\n\\nif __name__ == \\\"__main__\\\":\\n    parser = argparse.ArgumentParser()\\n    parser.add_argument(\\\"--in-file\\\", type=str, required=True)\\n    parser.add_argument(\\\"--sample\\\", type=int)\\n    args = parser.parse_args()\\n\\n    # Read conversations\\n    convs = json.load(open(args.in_file))\\n    print(f\\\"#conv: {len(convs)}\\\")\\n\\n    # Read blocked words\\n    if os.path.exists(BLOCKED_WORDS_FILENAME):\\n        blocked_words = json.load(open(BLOCKED_WORDS_FILENAME))\\n\\n    # Count frequency\\n    for conv in convs:\\n        for key in [\\\"conversation_a\\\", \\\"conversation_b\\\"]:\\n            messages = [row[\\\"content\\\"] for row in conv[key] if row[\\\"role\\\"] == \\\"user\\\"]\\n            for msg in messages:\\n                if not isinstance(msg, str):\\n                    continue\\n                msg = msg.lower().strip()\\n                frequency[msg] += 1\\n\\n    keys = list(frequency.keys())\\n    keys.sort(key=lambda x: -frequency[x])\\n    frequent_prompts = keys[:10]\\n    frequent_prompts = set(frequent_prompts)\\n    frequent_prompts.add(\\\"\\\")\\n\\n    # Start filter\\n    ct_bad_format = 0\\n    ct_anonymized = 0\\n    ct_redacted = 0\\n    ct_error = 0\\n    ct_lang_filter = 0\\n    ct_flagged = 0\\n    ct_blocked_word = 0\\n    ct_blocked_model = 0\\n    ct_too_short = 0\\n    ct_too_frequent = 0\\n\\n    new_convs = []\\n    for conv in tqdm(convs):\\n        type_code = detect_type(conv)\\n\\n        if type_code == TypeCode.BAD_FORMAT:\\n            ct_bad_format += 1\\n            continue\\n\\n        if type_code == TypeCode.ANONYMIZED:\\n            ct_anonymized += 1\\n            continue\\n        elif type_code == TypeCode.REDACTED:\\n            ct_redacted += 1\\n            continue\\n        elif type_code == TypeCode.BLOCKED_WORD:\\n            ct_blocked_word += 1\\n            continue\\n        elif type_code == TypeCode.BLOCKED_MODEL:\\n            ct_blocked_model += 1\\n            continue\\n        elif type_code == TypeCode.TOO_SHORT:\\n            ct_too_short += 1\\n            continue\\n        elif type_code == TypeCode.TOO_FREQUENT:\\n            ct_too_frequent += 1\\n            continue\\n\\n        if conv[\\\"openai_moderation\\\"][\\\"flagged\\\"]:\\n            ct_flagged += 1\\n            continue\\n\\n        if type_code in [TypeCode.CORRECT]:\\n            new_convs.append(conv)\\n\\n    if args.sample:\\n        # random.seed(0)\\n        # random.shuffle(new_convs)\\n        new_convs = new_convs[: args.sample]\\n\\n    print(f\\\"ct_anonymized: {ct_anonymized}, ct_redacted: {ct_redacted}\\\")\\n    print(f\\\"ct_bad_format: {ct_bad_format}, ct_flagged: {ct_flagged}\\\")\\n    print(f\\\"ct_blocked_word: {ct_blocked_word}, ct_blocked_model: {ct_blocked_model}\\\")\\n    print(f\\\"ct_too_short: {ct_too_short}, ct_too_frequent: {ct_anonymized}\\\")\\n    print(f\\\"new_conv: {len(new_convs)}\\\")\\n\\n    out_file = args.in_file.replace(\\\".json\\\", \\\".out.json\\\")\\n    print(f\\\"Output to {out_file}\\\")\\n    with open(out_file, \\\"w\\\") as fout:\\n        json.dump(new_convs, fout, indent=2, ensure_ascii=False)\\n\"},{\"source_archive\":\"Unified_Psychiatric_AI_Brain_Part1.zip\",\"source_path\":\"source_projects/ChatPsychiatrist-master/ChatPsychiatrist-master/fastchat/serve/monitor/conv_release_scripts/count_unique_users.py\",\"language\":\"py\",\"content\":\"\\\"\\\"\\\"Count the unique users in a battle log file.\\\"\\\"\\\"\\n\\nimport argparse\\nimport json\\n\\n\\nif __name__ == \\\"__main__\\\":\\n    parser = argparse.ArgumentParser()\\n    parser.add_argument(\\\"--input\\\", type=str)\\n    args = parser.parse_args()\\n\\n    lines = json.load(open(args.input))\\n    ct_anony_votes = 0\\n    all_users = set()\\n    all_models = set()\\n    for l in lines:\\n        if not l[\\\"anony\\\"]:\\n            continue\\n        all_users.add(l[\\\"judge\\\"])\\n        all_models.add(l[\\\"model_a\\\"])\\n        all_models.add(l[\\\"model_b\\\"])\\n        ct_anony_votes += 1\\n\\n    print(f\\\"#anony_vote: {ct_anony_votes}, #user: {len(all_users)}\\\")\\n    print(f\\\"#model: {len(all_models)}\\\")\\n\"},{\"source_archive\":\"Unified_Psychiatric_AI_Brain_Part1.zip\",\"source_path\":\"source_projects/ChatPsychiatrist-master/ChatPsychiatrist-master/fastchat/serve/monitor/inspect_conv.py\",\"language\":\"py\",\"content\":\"import argparse\\nimport code\\nimport datetime\\nimport json\\nimport os\\nfrom pytz import timezone\\nimport time\\n\\nimport pandas as pd\\nfrom tqdm import tqdm\\n\\n\\ndef get_log_files(max_num_files=None):\\n    dates = []\\n    for month in [4, 5]:\\n        for day in range(1, 32):\\n            dates.append(f\\\"2023-{month:02d}-{day:02d}\\\")\\n\\n    num_servers = 14\\n    filenames = []\\n    for d in dates:\\n        for i in range(num_servers):\\n            name = os.path.expanduser(f\\\"~/fastchat_logs/server{i}/{d}-conv.json\\\")\\n            if os.path.exists(name):\\n                filenames.append(name)\\n    max_num_files = max_num_files or len(filenames)\\n    filenames = filenames[-max_num_files:]\\n    return filenames\\n\\n\\ndef pretty_print_conversation(messages):\\n    for role, msg in messages:\\n        print(f\\\"[[{role}]]: {msg}\\\")\\n\\n\\ndef inspect_convs(log_files):\\n    data = []\\n    for filename in tqdm(log_files, desc=\\\"read files\\\"):\\n        for retry in range(5):\\n            try:\\n                lines = open(filename).readlines()\\n                break\\n            except FileNotFoundError:\\n                time.sleep(2)\\n\\n        for l in lines:\\n            row = json.loads(l)\\n\\n            if \\\"states\\\" not in row:\\n                continue\\n            if row[\\\"type\\\"] not in [\\\"leftvote\\\", \\\"rightvote\\\", \\\"bothbad_vote\\\"]:\\n                continue\\n\\n            model_names = row[\\\"states\\\"][0][\\\"model_name\\\"], row[\\\"states\\\"][1][\\\"model_name\\\"]\\n            if row[\\\"type\\\"] == \\\"leftvote\\\":\\n                winner, loser = model_names[0], model_names[1]\\n                winner_conv, loser_conv = row[\\\"states\\\"][0], row[\\\"states\\\"][1]\\n            elif row[\\\"type\\\"] == \\\"rightvote\\\":\\n                loser, winner = model_names[0], model_names[1]\\n                loser_conv, winner_conv = row[\\\"states\\\"][0], row[\\\"states\\\"][1]\\n\\n            if loser == \\\"bard\\\" and winner == \\\"vicuna-13b\\\":\\n                print(\\\"=\\\" * 20)\\n                print(f\\\"Winner: {winner}\\\")\\n                pretty_print_conversation(winner_conv[\\\"messages\\\"])\\n                print(f\\\"Loser: {loser}\\\")\\n                pretty_print_conversation(loser_conv[\\\"messages\\\"])\\n                print(\\\"=\\\" * 20)\\n                input()\\n\\n            # if row[\\\"type\\\"] == \\\"bothbad_vote\\\" and \\\"gpt-4\\\" in model_names:\\n            #    print(\\\"=\\\" * 20)\\n            #    print(f\\\"Model A: {model_names[0]}\\\")\\n            #    pretty_print_conversation(row[\\\"states\\\"][0][\\\"messages\\\"])\\n            #    print(f\\\"Model B: {model_names[1]}\\\")\\n            #    pretty_print_conversation(row[\\\"states\\\"][1][\\\"messages\\\"])\\n            #    print(\\\"=\\\" * 20)\\n            #    input()\\n\\n\\nif __name__ == \\\"__main__\\\":\\n    parser = argparse.ArgumentParser()\\n    parser.add_argument(\\\"--max-num-files\\\", type=int)\\n    args = parser.parse_args()\\n\\n    log_files = get_log_files(args.max_num_files)\\n    inspect_convs(log_files)\\n\"},{\"source_archive\":\"Unified_Psychiatric_AI_Brain_Part1.zip\",\"source_path\":\"source_projects/ChatPsychiatrist-master/ChatPsychiatrist-master/fastchat/serve/monitor/leaderboard_csv_to_html.py\",\"language\":\"py\",\"content\":\"\\\"\\\"\\\"\\nConvert a leaderboard csv file to html table used in the blog.\\n\\nUsage:\\npython3 leaderboard_csv_to_html.py --in leaderboard_table_20230619.csv\\n\\\"\\\"\\\"\\nimport argparse\\n\\nimport numpy as np\\n\\nfrom fastchat.serve.monitor.monitor import load_leaderboard_table_csv\\n\\n\\ndef model_hyperlink(model_name, link):\\n    return f'<a target=\\\"_blank\\\" href=\\\"{link}\\\"> {model_name} </a>'\\n\\n\\nif __name__ == \\\"__main__\\\":\\n    parser = argparse.ArgumentParser()\\n    parser.add_argument(\\\"--input\\\", type=str, required=True)\\n    args = parser.parse_args()\\n\\n    data = load_leaderboard_table_csv(args.input, add_hyperlink=False)\\n    headers = [\\n        \\\"Model\\\",\\n        \\\"MT-bench (score)\\\",\\n        \\\"Arena Elo rating\\\",\\n        \\\"MMLU\\\",\\n        \\\"License\\\",\\n    ]\\n    values = []\\n    for item in data:\\n        row = []\\n        for key in headers:\\n            value = item[key]\\n            row.append(value)\\n        row[0] = model_hyperlink(item[\\\"Model\\\"], item[\\\"Link\\\"])\\n        values.append(row)\\n    values.sort(key=lambda x: -x[1] if not np.isnan(x[1]) else 1e9)\\n\\n    for value in values:\\n        row = \\\"<tr>\\\"\\n        for x in value:\\n            try:\\n                if np.isnan(x):\\n                    x = \\\"-\\\"\\n            except TypeError:\\n                pass\\n            row += f\\\" <td>{x}</td> \\\"\\n        row += \\\"</tr>\\\"\\n        print(row)\\n\"},{\"source_archive\":\"Unified_Psychiatric_AI_Brain_Part1.zip\",\"source_path\":\"source_projects/ChatPsychiatrist-master/ChatPsychiatrist-master/fastchat/serve/monitor/basic_stats.py\",\"language\":\"py\",\"content\":\"import argparse\\nimport code\\nimport datetime\\nimport json\\nimport os\\nfrom pytz import timezone\\nimport time\\n\\nimport pandas as pd\\nimport plotly.express as px\\nimport plotly.graph_objects as go\\nfrom tqdm import tqdm\\n\\n\\nNUM_SERVERS = 14\\n\\n\\ndef get_log_files(max_num_files=None):\\n    dates = []\\n    for month in range(4, 8):\\n        for day in range(1, 33):\\n            dates.append(f\\\"2023-{month:02d}-{day:02d}\\\")\\n\\n    filenames = []\\n    for d in dates:\\n        for i in range(NUM_SERVERS):\\n            name = os.path.expanduser(f\\\"~/fastchat_logs/server{i}/{d}-conv.json\\\")\\n            if os.path.exists(name):\\n                filenames.append(name)\\n    max_num_files = max_num_files or len(filenames)\\n    filenames = filenames[-max_num_files:]\\n    return filenames\\n\\n\\ndef load_log_files(log_files):\\n    data = []\\n    for filename in tqdm(log_files, desc=\\\"read files\\\"):\\n        for retry in range(5):\\n            try:\\n                lines = open(filename).readlines()\\n                break\\n            except FileNotFoundError:\\n                time.sleep(2)\\n\\n        for l in lines:\\n            row = json.loads(l)\\n\\n            data.append(\\n                dict(\\n                    type=row[\\\"type\\\"],\\n                    tstamp=row[\\\"tstamp\\\"],\\n                    model=row.get(\\\"model\\\", \\\"\\\"),\\n                    models=row.get(\\\"models\\\", [\\\"\\\", \\\"\\\"]),\\n                )\\n            )\\n\\n    return data\\n\\n\\ndef get_anony_vote_df(df):\\n    anony_vote_df = df[\\n        df[\\\"type\\\"].isin([\\\"leftvote\\\", \\\"rightvote\\\", \\\"tievote\\\", \\\"bothbad_vote\\\"])\\n    ]\\n    anony_vote_df = anony_vote_df[anony_vote_df[\\\"models\\\"].apply(lambda x: x[0] == \\\"\\\")]\\n    return anony_vote_df\\n\\n\\ndef merge_counts(series, on, names):\\n    ret = pd.merge(series[0], series[1], on=on)\\n    for i in range(2, len(series)):\\n        ret = pd.merge(ret, series[i], on=on)\\n    ret = ret.reset_index()\\n    old_names = list(ret.columns)[-len(series) :]\\n    rename = {old_name: new_name for old_name, new_name in zip(old_names, names)}\\n    ret = ret.rename(columns=rename)\\n    return ret\\n\\n\\ndef report_basic_stats(log_files):\\n    df_all = load_log_files(log_files)\\n    df_all = pd.DataFrame(df_all)\\n    now_t = df_all[\\\"tstamp\\\"].max()\\n    df_1_hour = df_all[df_all[\\\"tstamp\\\"] > (now_t - 3600)]\\n    df_1_day = df_all[df_all[\\\"tstamp\\\"] > (now_t - 3600 * 24)]\\n    anony_vote_df_all = get_anony_vote_df(df_all)\\n\\n    # Chat trends\\n    chat_dates = [\\n        datetime.datetime.fromtimestamp(x, tz=timezone(\\\"US/Pacific\\\")).strftime(\\n            \\\"%Y-%m-%d\\\"\\n        )\\n        for x in df_all[df_all[\\\"type\\\"] == \\\"chat\\\"][\\\"tstamp\\\"]\\n    ]\\n    chat_dates_counts = pd.value_counts(chat_dates)\\n    vote_dates = [\\n        datetime.datetime.fromtimestamp(x, tz=timezone(\\\"US/Pacific\\\")).strftime(\\n            \\\"%Y-%m-%d\\\"\\n        )\\n        for x in anony_vote_df_all[\\\"tstamp\\\"]\\n    ]\\n    vote_dates_counts = pd.value_counts(vote_dates)\\n    chat_dates_bar = go.Figure(\\n        data=[\\n            go.Bar(\\n                name=\\\"Anony. Vote\\\",\\n                x=vote_dates_counts.index,\\n                y=vote_dates_counts,\\n                text=[f\\\"{val:.0f}\\\" for val in vote_dates_counts],\\n                textposition=\\\"auto\\\",\\n            ),\\n            go.Bar(\\n                name=\\\"Chat\\\",\\n                x=chat_dates_counts.index,\\n                y=chat_dates_counts,\\n                text=[f\\\"{val:.0f}\\\" for val in chat_dates_counts],\\n                textposition=\\\"auto\\\",\\n            ),\\n        ]\\n    )\\n    chat_dates_bar.update_layout(\\n        barmode=\\\"stack\\\",\\n        xaxis_title=\\\"Dates\\\",\\n        yaxis_title=\\\"Count\\\",\\n        height=300,\\n        width=1200,\\n    )\\n\\n    # Model call counts\\n    model_hist_all = df_all[df_all[\\\"type\\\"] == \\\"chat\\\"][\\\"model\\\"].value_counts()\\n    model_hist_1_day = df_1_day[df_1_day[\\\"type\\\"] == \\\"chat\\\"][\\\"model\\\"].value_counts()\\n    model_hist_1_hour = df_1_hour[df_1_hour[\\\"type\\\"] == \\\"chat\\\"][\\\"model\\\"].value_counts()\\n    model_hist = merge_counts(\\n        [model_hist_all, model_hist_1_day, model_hist_1_hour],\\n        on=\\\"model\\\",\\n        names=[\\\"All\\\", \\\"Last Day\\\", \\\"Last Hour\\\"],\\n    )\\n    model_hist_md = model_hist.to_markdown(index=False, tablefmt=\\\"github\\\")\\n\\n    # Action counts\\n    action_hist_all = df_all[\\\"type\\\"].value_counts()\\n    action_hist_1_day = df_1_day[\\\"type\\\"].value_counts()\\n    action_hist_1_hour = df_1_hour[\\\"type\\\"].value_counts()\\n    action_hist = merge_counts(\\n        [action_hist_all, action_hist_1_day, action_hist_1_hour],\\n        on=\\\"type\\\",\\n        names=[\\\"All\\\", \\\"Last Day\\\", \\\"Last Hour\\\"],\\n    )\\n    action_hist_md = action_hist.to_markdown(index=False, tablefmt=\\\"github\\\")\\n\\n    # Anony vote counts\\n    anony_vote_hist_all = anony_vote_df_all[\\\"type\\\"].value_counts()\\n    anony_vote_df_1_day = get_anony_vote_df(df_1_day)\\n    anony_vote_hist_1_day = anony_vote_df_1_day[\\\"type\\\"].value_counts()\\n    # anony_vote_df_1_hour = get_anony_vote_df(df_1_hour)\\n    # anony_vote_hist_1_hour = anony_vote_df_1_hour[\\\"type\\\"].value_counts()\\n    anony_vote_hist = merge_counts(\\n        [anony_vote_hist_all, anony_vote_hist_1_day],\\n        on=\\\"type\\\",\\n        names=[\\\"All\\\", \\\"Last Day\\\"],\\n    )\\n    anony_vote_hist_md = anony_vote_hist.to_markdown(index=False, tablefmt=\\\"github\\\")\\n\\n    # Last 24 hours\\n    chat_1_day = df_1_day[df_1_day[\\\"type\\\"] == \\\"chat\\\"]\\n    num_chats_last_24_hours = []\\n    base = df_1_day[\\\"tstamp\\\"].min()\\n    for i in range(24, 0, -1):\\n        left = base + (i - 1) * 3600\\n        right = base + i * 3600\\n        num = ((chat_1_day[\\\"tstamp\\\"] >= left) & (chat_1_day[\\\"tstamp\\\"] < right)).sum()\\n        num_chats_last_24_hours.append(num)\\n    times = [\\n        datetime.datetime.fromtimestamp(\\n            base + i * 3600, tz=timezone(\\\"US/Pacific\\\")\\n        ).strftime(\\\"%Y-%m-%d %H:%M:%S %Z\\\")\\n        for i in range(24, 0, -1)\\n    ]\\n    last_24_hours_df = pd.DataFrame({\\\"time\\\": times, \\\"value\\\": num_chats_last_24_hours})\\n    last_24_hours_md = last_24_hours_df.to_markdown(index=False, tablefmt=\\\"github\\\")\\n\\n    # Last update datetime\\n    last_updated_tstamp = now_t\\n    last_updated_datetime = datetime.datetime.fromtimestamp(\\n        last_updated_tstamp, tz=timezone(\\\"US/Pacific\\\")\\n    ).strftime(\\\"%Y-%m-%d %H:%M:%S %Z\\\")\\n\\n    # code.interact(local=locals())\\n\\n    return {\\n        \\\"chat_dates_bar\\\": chat_dates_bar,\\n        \\\"model_hist_md\\\": model_hist_md,\\n        \\\"action_hist_md\\\": action_hist_md,\\n        \\\"anony_vote_hist_md\\\": anony_vote_hist_md,\\n        \\\"num_chats_last_24_hours\\\": last_24_hours_md,\\n        \\\"last_updated_datetime\\\": last_updated_datetime,\\n    }\\n\\n\\nif __name__ == \\\"__main__\\\":\\n    parser = argparse.ArgumentParser()\\n    parser.add_argument(\\\"--max-num-files\\\", type=int)\\n    args = parser.parse_args()\\n\\n    log_files = get_log_files(args.max_num_files)\\n    basic_stats = report_basic_stats(log_files)\\n\\n    print(basic_stats[\\\"action_hist_md\\\"] + \\\"\\\\n\\\")\\n    print(basic_stats[\\\"model_hist_md\\\"] + \\\"\\\\n\\\")\\n    print(basic_stats[\\\"anony_vote_hist_md\\\"] + \\\"\\\\n\\\")\\n    print(basic_stats[\\\"num_chats_last_24_hours\\\"] + \\\"\\\\n\\\")\\n\"},{\"source_archive\":\"Unified_Psychiatric_AI_Brain_Part1.zip\",\"source_path\":\"source_projects/ChatPsychiatrist-master/ChatPsychiatrist-master/fastchat/serve/monitor/monitor.py\",\"language\":\"py\",\"content\":\"# sudo apt install pkg-config libicu-dev\\n# pip install pytz gradio gdown plotly polyglot pyicu pycld2 tabulate\\n\\nimport argparse\\nimport ast\\nimport pickle\\nimport os\\nimport threading\\nimport time\\n\\nimport gradio as gr\\nimport numpy as np\\n\\nfrom fastchat.serve.monitor.basic_stats import report_basic_stats, get_log_files\\nfrom fastchat.serve.monitor.clean_battle_data import clean_battle_data\\nfrom fastchat.serve.monitor.elo_analysis import report_elo_analysis_results\\nfrom fastchat.utils import build_logger, get_window_url_params_js\\n\\n\\nnotebook_url = \\\"https://colab.research.google.com/drive/1RAWb22-PFNI-X1gPVzc927SGUdfr6nsR?usp=sharing\\\"\\n\\n\\nbasic_component_values = [None] * 6\\nleader_component_values = [None] * 5\\n\\n\\ndef make_leaderboard_md(elo_results):\\n    leaderboard_md = f\\\"\\\"\\\"\\n# Leaderboard\\n| [Blog](https://lmsys.org/blog/2023-05-03-arena/) | [GitHub](https://github.com/lm-sys/FastChat) | [Paper](https://arxiv.org/abs/2306.05685) | [Dataset](https://huggingface.co/datasets/lmsys/chatbot_arena_conversations) | [Twitter](https://twitter.com/lmsysorg) | [Discord](https://discord.gg/HSWAKCrnFx) |\\n\\n\ud83c\udfc6 This leaderboard is based on the following three benchmarks.\\n- [Chatbot Arena](https://lmsys.org/blog/2023-05-03-arena/) - a crowdsourced, randomized battle platform. We use 50K+ user votes to compute Elo ratings.\\n- [MT-Bench](https://arxiv.org/abs/2306.05685) - a set of challenging multi-turn questions. We use GPT-4 to grade the model responses.\\n- [MMLU](https://arxiv.org/abs/2009.03300) (5-shot) - a test to measure a model's multitask accuracy on 57 tasks.\\n\\n\ud83d\udcbb We use [fastchat.llm_judge](https://github.com/lm-sys/FastChat/tree/main/fastchat/llm_judge) to compute MT-bench scores (single-answer grading on a scale of 10). The Arena Elo ratings are computed by this [notebook]({notebook_url}). The MMLU scores are computed by [InstructEval](https://github.com/declare-lab/instruct-eval) and [Chain-of-Thought Hub](https://github.com/FranxYao/chain-of-thought-hub). Higher values are better for all benchmarks. Empty cells mean not available.\\n\\\"\\\"\\\"\\n    return leaderboard_md\\n\\n\\ndef make_leaderboard_md_live(elo_results):\\n    leaderboard_md = f\\\"\\\"\\\"\\n# Leaderboard\\nLast updated: {elo_results[\\\"last_updated_datetime\\\"]}\\n{elo_results[\\\"leaderboard_table\\\"]}\\n\\\"\\\"\\\"\\n    return leaderboard_md\\n\\n\\ndef update_elo_components(max_num_files, elo_results_file):\\n    log_files = get_log_files(max_num_files)\\n\\n    # Leaderboard\\n    if elo_results_file is None:  # Do live update\\n        battles = clean_battle_data(log_files)\\n        elo_results = report_elo_analysis_results(battles)\\n\\n        leader_component_values[0] = make_leaderboard_md_live(elo_results)\\n        leader_component_values[1] = elo_results[\\\"win_fraction_heatmap\\\"]\\n        leader_component_values[2] = elo_results[\\\"battle_count_heatmap\\\"]\\n        leader_component_values[3] = elo_results[\\\"bootstrap_elo_rating\\\"]\\n        leader_component_values[4] = elo_results[\\\"average_win_rate_bar\\\"]\\n\\n    # Basic stats\\n    basic_stats = report_basic_stats(log_files)\\n    md0 = f\\\"Last updated: {basic_stats['last_updated_datetime']}\\\"\\n\\n    md1 = \\\"### Action Histogram\\\\n\\\"\\n    md1 += basic_stats[\\\"action_hist_md\\\"] + \\\"\\\\n\\\"\\n\\n    md2 = \\\"### Anony. Vote Histogram\\\\n\\\"\\n    md2 += basic_stats[\\\"anony_vote_hist_md\\\"] + \\\"\\\\n\\\"\\n\\n    md3 = \\\"### Model Call Histogram\\\\n\\\"\\n    md3 += basic_stats[\\\"model_hist_md\\\"] + \\\"\\\\n\\\"\\n\\n    md4 = \\\"### Model Call (Last 24 Hours)\\\\n\\\"\\n    md4 += basic_stats[\\\"num_chats_last_24_hours\\\"] + \\\"\\\\n\\\"\\n\\n    basic_component_values[0] = md0\\n    basic_component_values[1] = basic_stats[\\\"chat_dates_bar\\\"]\\n    basic_component_values[2] = md1\\n    basic_component_values[3] = md2\\n    basic_component_values[4] = md3\\n    basic_component_values[5] = md4\\n\\n\\ndef update_worker(max_num_files, interval, elo_results_file):\\n    while True:\\n        tic = time.time()\\n        update_elo_components(max_num_files, elo_results_file)\\n        durtaion = time.time() - tic\\n        print(f\\\"update duration: {durtaion:.2f} s\\\")\\n        time.sleep(max(interval - durtaion, 0))\\n\\n\\ndef load_demo(url_params, request: gr.Request):\\n    logger.info(f\\\"load_demo. ip: {request.client.host}. params: {url_params}\\\")\\n    return basic_component_values + leader_component_values\\n\\n\\ndef model_hyperlink(model_name, link):\\n    return f'<a target=\\\"_blank\\\" href=\\\"{link}\\\" style=\\\"color: var(--link-text-color); text-decoration: underline;text-decoration-style: dotted;\\\">{model_name}</a>'\\n\\n\\ndef load_leaderboard_table_csv(filename, add_hyperlink=True):\\n    lines = open(filename).readlines()\\n    heads = [v.strip() for v in lines[0].split(\\\",\\\")]\\n    rows = []\\n    for i in range(1, len(lines)):\\n        row = [v.strip() for v in lines[i].split(\\\",\\\")]\\n        for j in range(len(heads)):\\n            item = {}\\n            for h, v in zip(heads, row):\\n                if h == \\\"Arena Elo rating\\\":\\n                    if v != \\\"-\\\":\\n                        v = int(ast.literal_eval(v))\\n                    else:\\n                        v = np.nan\\n                elif h == \\\"MMLU\\\":\\n                    if v != \\\"-\\\":\\n                        v = round(ast.literal_eval(v) * 100, 1)\\n                    else:\\n                        v = np.nan\\n                elif h == \\\"MT-bench (win rate %)\\\":\\n                    if v != \\\"-\\\":\\n                        v = round(ast.literal_eval(v[:-1]), 1)\\n                    else:\\n                        v = np.nan\\n                elif h == \\\"MT-bench (score)\\\":\\n                    if v != \\\"-\\\":\\n                        v = round(ast.literal_eval(v), 2)\\n                    else:\\n                        v = np.nan\\n                item[h] = v\\n            if add_hyperlink:\\n                item[\\\"Model\\\"] = model_hyperlink(item[\\\"Model\\\"], item[\\\"Link\\\"])\\n        rows.append(item)\\n\\n    return rows\\n\\n\\ndef build_basic_stats_tab():\\n    empty = \\\"Loading ...\\\"\\n    basic_component_values[:] = [empty, None, empty, empty, empty, empty]\\n\\n    md0 = gr.Markdown(empty)\\n    gr.Markdown(\\\"#### Figure 1: Number of model calls and votes\\\")\\n    plot_1 = gr.Plot(show_label=False)\\n    with gr.Row():\\n        with gr.Column():\\n            md1 = gr.Markdown(empty)\\n        with gr.Column():\\n            md2 = gr.Markdown(empty)\\n    with gr.Row():\\n        with gr.Column():\\n            md3 = gr.Markdown(empty)\\n        with gr.Column():\\n            md4 = gr.Markdown(empty)\\n    return [md0, plot_1, md1, md2, md3, md4]\\n\\n\\ndef build_leaderboard_tab(elo_results_file, leaderboard_table_file):\\n    if elo_results_file is None:  # Do live update\\n        md = \\\"Loading ...\\\"\\n        p1 = p2 = p3 = p4 = None\\n    else:\\n        with open(elo_results_file, \\\"rb\\\") as fin:\\n            elo_results = pickle.load(fin)\\n\\n        md = make_leaderboard_md(elo_results)\\n        p1 = elo_results[\\\"win_fraction_heatmap\\\"]\\n        p2 = elo_results[\\\"battle_count_heatmap\\\"]\\n        p3 = elo_results[\\\"bootstrap_elo_rating\\\"]\\n        p4 = elo_results[\\\"average_win_rate_bar\\\"]\\n\\n    md_1 = gr.Markdown(md, elem_id=\\\"leaderboard_markdown\\\")\\n\\n    if leaderboard_table_file:\\n        data = load_leaderboard_table_csv(leaderboard_table_file)\\n        headers = [\\n            \\\"Model\\\",\\n            \\\"Arena Elo rating\\\",\\n            \\\"MT-bench (score)\\\",\\n            \\\"MMLU\\\",\\n            \\\"License\\\",\\n        ]\\n        values = []\\n        for item in data:\\n            row = []\\n            for key in headers:\\n                value = item[key]\\n                row.append(value)\\n            values.append(row)\\n        values.sort(key=lambda x: -x[1] if not np.isnan(x[1]) else 1e9)\\n\\n        headers[1] = \\\"\u2b50 \\\" + headers[1]\\n        headers[2] = \\\"\ud83d\udcc8 \\\" + headers[2]\\n\\n        gr.Dataframe(\\n            headers=headers,\\n            datatype=[\\\"markdown\\\", \\\"number\\\", \\\"number\\\", \\\"number\\\", \\\"str\\\"],\\n            value=values,\\n            elem_id=\\\"leaderboard_dataframe\\\",\\n        )\\n        gr.Markdown(\\n            \\\"If you want to see more models, please help us [add them](https://github.com/lm-sys/FastChat/blob/main/docs/arena.md#how-to-add-a-new-model).\\\"\\n        )\\n    else:\\n        pass\\n\\n    gr.Markdown(\\n        f\\\"\\\"\\\"## More Statistics for Chatbot Arena\\\\n\\nWe added some additional figures to show more statistics. The code for generating them is also included in this [notebook]({notebook_url}).\\nPlease note that you may see different orders from different ranking methods. This is expected for models that perform similarly, as demonstrated by the confidence interval in the bootstrap figure. Going forward, we prefer the classical Elo calculation because of its scalability and interpretability. You can find more discussions in this blog [post](https://lmsys.org/blog/2023-05-03-arena/).\\n\\\"\\\"\\\"\\n    )\\n\\n    leader_component_values[:] = [md, p1, p2, p3, p4]\\n\\n    with gr.Row():\\n        with gr.Column():\\n            gr.Markdown(\\n                \\\"#### Figure 1: Fraction of Model A Wins for All Non-tied A vs. B Battles\\\"\\n            )\\n            plot_1 = gr.Plot(p1, show_label=False)\\n        with gr.Column():\\n            gr.Markdown(\\n                \\\"#### Figure 2: Battle Count for Each Combination of Models (without Ties)\\\"\\n            )\\n            plot_2 = gr.Plot(p2, show_label=False)\\n    with gr.Row():\\n        with gr.Column():\\n            gr.Markdown(\\n                \\\"#### Figure 3: Bootstrap of Elo Estimates (1000 Rounds of Random Sampling)\\\"\\n            )\\n            plot_3 = gr.Plot(p3, show_label=False)\\n        with gr.Column():\\n            gr.Markdown(\\n                \\\"#### Figure 4: Average Win Rate Against All Other Models (Assuming Uniform Sampling and No Ties)\\\"\\n            )\\n            plot_4 = gr.Plot(p4, show_label=False)\\n    return [md_1, plot_1, plot_2, plot_3, plot_4]\\n\\n\\ndef build_demo(elo_results_file, leaderboard_table_file):\\n    text_size = gr.themes.sizes.text_lg\\n\\n    with gr.Blocks(\\n        title=\\\"Monitor\\\",\\n        theme=gr.themes.Base(text_size=text_size),\\n    ) as demo:\\n        with gr.Tabs() as tabs:\\n            with gr.Tab(\\\"Leaderboard\\\", id=0):\\n                leader_components = build_leaderboard_tab(\\n                    elo_results_file, leaderboard_table_file\\n                )\\n\\n            with gr.Tab(\\\"Basic Stats\\\", id=1):\\n                basic_components = build_basic_stats_tab()\\n\\n        url_params = gr.JSON(visible=False)\\n        demo.load(\\n            load_demo,\\n            [url_params],\\n            basic_components + leader_components,\\n            _js=get_window_url_params_js,\\n        )\\n\\n    return demo\\n\\n\\nif __name__ == \\\"__main__\\\":\\n    parser = argparse.ArgumentParser()\\n    parser.add_argument(\\\"--host\\\", type=str, default=\\\"0.0.0.0\\\")\\n    parser.add_argument(\\\"--port\\\", type=int)\\n    parser.add_argument(\\\"--share\\\", action=\\\"store_true\\\")\\n    parser.add_argument(\\\"--concurrency-count\\\", type=int, default=10)\\n    parser.add_argument(\\\"--update-interval\\\", type=int, default=300)\\n    parser.add_argument(\\\"--max-num-files\\\", type=int)\\n    parser.add_argument(\\\"--elo-results-file\\\", type=str)\\n    parser.add_argument(\\\"--leaderboard-table-file\\\", type=str)\\n    args = parser.parse_args()\\n\\n    logger = build_logger(\\\"monitor\\\", \\\"monitor.log\\\")\\n    logger.info(f\\\"args: {args}\\\")\\n\\n    if args.elo_results_file is None:  # Do live update\\n        update_thread = threading.Thread(\\n            target=update_worker,\\n            args=(args.max_num_files, args.update_interval, args.elo_results_file),\\n        )\\n        update_thread.start()\\n\\n    demo = build_demo(args.elo_results_file, args.leaderboard_table_file)\\n    demo.queue(\\n        concurrency_count=args.concurrency_count, status_update_rate=10, api_open=False\\n    ).launch(\\n        server_name=args.host, server_port=args.port, share=args.share, max_threads=200\\n    )\\n\"},{\"source_archive\":\"Unified_Psychiatric_AI_Brain_Part1.zip\",\"source_path\":\"source_projects/ChatPsychiatrist-master/ChatPsychiatrist-master/fastchat/serve/monitor/clean_battle_data.py\",\"language\":\"py\",\"content\":\"\\\"\\\"\\\"\\nClean chatbot arena battle log.\\n\\nUsage:\\npython3 clean_battle_data.py --mode conv_release\\n\\\"\\\"\\\"\\nimport argparse\\nimport datetime\\nimport json\\nimport os\\nfrom pytz import timezone\\nimport time\\n\\nfrom tqdm import tqdm\\n\\nfrom fastchat.serve.monitor.basic_stats import get_log_files, NUM_SERVERS\\nfrom fastchat.utils import detect_language\\n\\n\\nVOTES = [\\\"tievote\\\", \\\"leftvote\\\", \\\"rightvote\\\", \\\"bothbad_vote\\\"]\\nIDENTITY_WORDS = [\\n    \\\"vicuna\\\",\\n    \\\"lmsys\\\",\\n    \\\"koala\\\",\\n    \\\"uc berkeley\\\",\\n    \\\"open assistant\\\",\\n    \\\"laion\\\",\\n    \\\"chatglm\\\",\\n    \\\"chatgpt\\\",\\n    \\\"openai\\\",\\n    \\\"anthropic\\\",\\n    \\\"claude\\\",\\n    \\\"bard\\\",\\n    \\\"palm\\\",\\n    \\\"lamda\\\",\\n    \\\"google\\\",\\n    \\\"NETWORK ERROR DUE TO HIGH TRAFFIC. PLEASE REGENERATE OR REFRESH THIS PAGE.\\\",\\n]\\n\\nfor i in range(len(IDENTITY_WORDS)):\\n    IDENTITY_WORDS[i] = IDENTITY_WORDS[i].lower()\\n\\n\\ndef get_log_files(max_num_files=None):\\n    dates = []\\n    for month in [4, 5, 6, 7]:\\n        for day in range(1, 32):\\n            dates.append(f\\\"2023-{month:02d}-{day:02d}\\\")\\n\\n    filenames = []\\n    for d in dates:\\n        for i in range(NUM_SERVERS):\\n            name = os.path.expanduser(f\\\"~/fastchat_logs/server{i}/{d}-conv.json\\\")\\n            if os.path.exists(name):\\n                filenames.append(name)\\n    max_num_files = max_num_files or len(filenames)\\n    filenames = filenames[-max_num_files:]\\n    return filenames\\n\\n\\ndef remove_html(raw):\\n    if raw.startswith(\\\"<h3>\\\"):\\n        return raw[raw.find(\\\": \\\") + 2 : -len(\\\"</h3>\\\\n\\\")]\\n    return raw\\n\\n\\ndef to_openai_format(messages):\\n    roles = [\\\"user\\\", \\\"assistant\\\"]\\n    ret = []\\n    for i, x in enumerate(messages):\\n        ret.append({\\\"role\\\": roles[i % 2], \\\"content\\\": x[1]})\\n    return ret\\n\\n\\ndef clean_battle_data(log_files):\\n    data = []\\n    for filename in tqdm(log_files, desc=\\\"read files\\\"):\\n        for retry in range(5):\\n            try:\\n                lines = open(filename).readlines()\\n                break\\n            except FileNotFoundError:\\n                time.sleep(2)\\n\\n        for l in lines:\\n            row = json.loads(l)\\n            if row[\\\"type\\\"] in VOTES:\\n                data.append(row)\\n\\n    convert_type = {\\n        \\\"leftvote\\\": \\\"model_a\\\",\\n        \\\"rightvote\\\": \\\"model_b\\\",\\n        \\\"tievote\\\": \\\"tie\\\",\\n        \\\"bothbad_vote\\\": \\\"tie (bothbad)\\\",\\n    }\\n\\n    all_models = set()\\n    all_ips = dict()\\n    ct_anony = 0\\n    ct_invalid = 0\\n    ct_leaked_identity = 0\\n    battles = []\\n    for row in data:\\n        # Resolve model names\\n        models_public = [remove_html(row[\\\"models\\\"][0]), remove_html(row[\\\"models\\\"][1])]\\n        if \\\"model_name\\\" in row[\\\"states\\\"][0]:\\n            models_hidden = [\\n                row[\\\"states\\\"][0][\\\"model_name\\\"],\\n                row[\\\"states\\\"][1][\\\"model_name\\\"],\\n            ]\\n            if models_hidden[0] is None:\\n                models_hidden = models_public\\n        else:\\n            models_hidden = models_public\\n\\n        if (models_public[0] == \\\"\\\" and models_public[1] != \\\"\\\") or (\\n            models_public[1] == \\\"\\\" and models_public[0] != \\\"\\\"\\n        ):\\n            ct_invalid += 1\\n            continue\\n\\n        if models_public[0] == \\\"\\\" or models_public[0] == \\\"Model A\\\":\\n            anony = True\\n            models = models_hidden\\n            ct_anony += 1\\n        else:\\n            anony = False\\n            models = models_public\\n            if not models_public == models_hidden:\\n                ct_invalid += 1\\n                continue\\n\\n        # Detect langauge\\n        state = row[\\\"states\\\"][0]\\n        if state[\\\"offset\\\"] >= len(state[\\\"messages\\\"]):\\n            ct_invalid += 1\\n            continue\\n        lang_code = detect_language(state[\\\"messages\\\"][state[\\\"offset\\\"]][1])\\n\\n        # Drop conversations if the model names are leaked\\n        leaked_identity = False\\n        messages = \\\"\\\"\\n        for i in range(2):\\n            state = row[\\\"states\\\"][i]\\n            for role, msg in state[\\\"messages\\\"][state[\\\"offset\\\"] :]:\\n                if msg:\\n                    messages += msg.lower()\\n        for word in IDENTITY_WORDS:\\n            if word in messages:\\n                leaked_identity = True\\n                break\\n\\n        if leaked_identity:\\n            ct_leaked_identity += 1\\n            continue\\n\\n        # Replace bard with palm\\n        models = [\\n            m.replace(\\\"bard\\\", \\\"palm-2\\\")\\n            .replace(\\\"claude-v1\\\", \\\"claude-1\\\")\\n            .replace(\\\"claude-instant-v1\\\", \\\"claude-instant-1\\\")\\n            for m in models\\n        ]\\n\\n        question_id = row[\\\"states\\\"][0][\\\"conv_id\\\"]\\n        conversation_a = to_openai_format(\\n            row[\\\"states\\\"][0][\\\"messages\\\"][row[\\\"states\\\"][0][\\\"offset\\\"] :]\\n        )\\n        conversation_b = to_openai_format(\\n            row[\\\"states\\\"][1][\\\"messages\\\"][row[\\\"states\\\"][1][\\\"offset\\\"] :]\\n        )\\n\\n        ip = row[\\\"ip\\\"]\\n        if ip not in all_ips:\\n            all_ips[ip] = len(all_ips)\\n        user_id = all_ips[ip]\\n\\n        # Save the result\\n        battles.append(\\n            dict(\\n                question_id=question_id,\\n                model_a=models[0],\\n                model_b=models[1],\\n                winner=convert_type[row[\\\"type\\\"]],\\n                judge=f\\\"arena_user_{user_id}\\\",\\n                conversation_a=conversation_a,\\n                conversation_b=conversation_b,\\n                turn=len(conversation_a) // 2,\\n                anony=anony,\\n                language=lang_code,\\n                tstamp=row[\\\"tstamp\\\"],\\n            )\\n        )\\n\\n        all_models.update(models_hidden)\\n    battles.sort(key=lambda x: x[\\\"tstamp\\\"])\\n    last_updated_tstamp = battles[-1][\\\"tstamp\\\"]\\n\\n    last_updated_datetime = datetime.datetime.fromtimestamp(\\n        last_updated_tstamp, tz=timezone(\\\"US/Pacific\\\")\\n    ).strftime(\\\"%Y-%m-%d %H:%M:%S %Z\\\")\\n\\n    print(\\n        f\\\"#votes: {len(data)}, #invalid votes: {ct_invalid}, \\\"\\n        f\\\"#leaked_identity: {ct_leaked_identity}\\\"\\n    )\\n    print(f\\\"#battles: {len(battles)}, #anony: {ct_anony}\\\")\\n    print(f\\\"#models: {len(all_models)}, {all_models}\\\")\\n    print(f\\\"last-updated: {last_updated_datetime}\\\")\\n\\n    return battles\\n\\n\\nif __name__ == \\\"__main__\\\":\\n    parser = argparse.ArgumentParser()\\n    parser.add_argument(\\\"--max-num-files\\\", type=int)\\n    parser.add_argument(\\n        \\\"--mode\\\", type=str, choices=[\\\"simple\\\", \\\"conv_release\\\"], default=\\\"simple\\\"\\n    )\\n    args = parser.parse_args()\\n\\n    log_files = get_log_files(args.max_num_files)\\n    battles = clean_battle_data(log_files)\\n    last_updated_tstamp = battles[-1][\\\"tstamp\\\"]\\n    cutoff_date = datetime.datetime.fromtimestamp(\\n        last_updated_tstamp, tz=timezone(\\\"US/Pacific\\\")\\n    ).strftime(\\\"%Y%m%d\\\")\\n\\n    if args.mode == \\\"simple\\\":\\n        for x in battles:\\n            for key in [\\n                \\\"conversation_a\\\",\\n                \\\"conversation_b\\\",\\n                \\\"question_id\\\",\\n            ]:\\n                del x[key]\\n        print(\\\"Samples:\\\")\\n        for i in range(4):\\n            print(battles[i])\\n        output = f\\\"clean_battle_{cutoff_date}.json\\\"\\n    elif args.mode == \\\"conv_release\\\":\\n        new_battles = []\\n        for x in battles:\\n            if not x[\\\"anony\\\"]:\\n                continue\\n            for key in []:\\n                del x[key]\\n            new_battles.append(x)\\n        battles = new_battles\\n        output = f\\\"clean_battle_conv_{cutoff_date}.json\\\"\\n\\n    with open(output, \\\"w\\\") as fout:\\n        json.dump(battles, fout, indent=2, ensure_ascii=False)\\n    print(f\\\"Write cleaned data to {output}\\\")\\n\"},{\"source_archive\":\"Unified_Psychiatric_AI_Brain_Part1.zip\",\"source_path\":\"source_projects/ChatPsychiatrist-master/ChatPsychiatrist-master/fastchat/serve/monitor/tag_openai_moderation.py\",\"language\":\"py\",\"content\":\"\\\"\\\"\\\"\\nAdd OpenAI moderation API results to all conversations.\\n\\\"\\\"\\\"\\nimport argparse\\nfrom concurrent.futures import ThreadPoolExecutor\\nimport json\\nimport os\\nimport time\\n\\nimport openai\\nimport requests\\nfrom tqdm import tqdm\\n\\n\\nAPI_MAX_RETRY = 16\\nAPI_RETRY_SLEEP = 10\\nAPI_ERROR_OUTPUT = \\\"$ERROR$\\\"\\n\\n\\ndef tag_moderation(text):\\n    result = API_ERROR_OUTPUT\\n    for _ in range(API_MAX_RETRY):\\n        try:\\n            result = openai.Moderation.create(input=text)[\\\"results\\\"][0]\\n            break\\n        except openai.error.OpenAIError as e:\\n            print(type(e), e)\\n            time.sleep(API_RETRY_SLEEP)\\n\\n    return result\\n\\n\\ndef tag_openai_moderation(x):\\n    conv = x[\\\"conversation_a\\\"]\\n    user_prompts = \\\"\\\\n\\\".join([x[\\\"content\\\"] for x in conv if x[\\\"role\\\"] == \\\"user\\\"])\\n    result = tag_moderation(user_prompts)\\n    x[\\\"openai_moderation\\\"] = result\\n\\n\\nif __name__ == \\\"__main__\\\":\\n    parser = argparse.ArgumentParser()\\n    parser.add_argument(\\\"--input\\\", type=str, required=True)\\n    parser.add_argument(\\n        \\\"--parallel\\\", type=int, default=1, help=\\\"The number of concurrent API calls.\\\"\\n    )\\n    parser.add_argument(\\\"--first-n\\\", type=int)\\n    args = parser.parse_args()\\n\\n    battles = json.load(open(args.input))\\n\\n    if args.first_n:\\n        battles = battles[: args.first_n]\\n\\n    with ThreadPoolExecutor(args.parallel) as executor:\\n        for line in tqdm(\\n            executor.map(tag_openai_moderation, battles), total=len(battles)\\n        ):\\n            pass\\n\\n    output = args.input.replace(\\\".json\\\", \\\"_tagged.json\\\")\\n    with open(output, \\\"w\\\") as fout:\\n        json.dump(battles, fout, indent=2, ensure_ascii=False)\\n    print(f\\\"Write cleaned data to {output}\\\")\\n\"},{\"source_archive\":\"Unified_Psychiatric_AI_Brain_Part1.zip\",\"source_path\":\"source_projects/ChatPsychiatrist-master/ChatPsychiatrist-master/fastchat/serve/monitor/hf_space_leaderboard_app.py\",\"language\":\"py\",\"content\":\"\\\"\\\"\\\"A gradio app that renders a static leaderboard. This is used for Hugging Face Space.\\\"\\\"\\\"\\nimport ast\\nimport argparse\\nimport pickle\\n\\nimport gradio as gr\\nimport numpy as np\\n\\n\\nnotebook_url = \\\"https://colab.research.google.com/drive/1RAWb22-PFNI-X1gPVzc927SGUdfr6nsR?usp=sharing\\\"\\n\\n\\nbasic_component_values = [None] * 6\\nleader_component_values = [None] * 5\\n\\n\\ndef make_leaderboard_md(elo_results):\\n    leaderboard_md = f\\\"\\\"\\\"\\n# Leaderboard\\n| [Blog](https://lmsys.org/blog/2023-05-03-arena/) | [GitHub](https://github.com/lm-sys/FastChat) | [Paper](https://arxiv.org/abs/2306.05685) | [Twitter](https://twitter.com/lmsysorg) | [Discord](https://discord.gg/HSWAKCrnFx) |\\n\\n\ud83c\udfc6 This leaderboard is based on the following three benchmarks.\\n- [Chatbot Arena](https://lmsys.org/blog/2023-05-03-arena/) - a crowdsourced, randomized battle platform. We use 40K+ user votes to compute Elo ratings.\\n- [MT-Bench](https://arxiv.org/abs/2306.05685) - a set of challenging multi-turn questions. We use GPT-4 to grade the model responses.\\n- [MMLU](https://arxiv.org/abs/2009.03300) (5-shot) - a test to measure a model's multitask accuracy on 57 tasks.\\n\\n\ud83d\udcbb We use [fastchat.llm_judge](https://github.com/lm-sys/FastChat/tree/main/fastchat/llm_judge) to compute MT-bench scores (single-answer grading on a scale of 10) and win rates (against gpt-3.5). The Arena Elo ratings are computed by this [notebook]({notebook_url}). The MMLU scores are computed by [InstructEval](https://github.com/declare-lab/instruct-eval) and [Chain-of-Thought Hub](https://github.com/FranxYao/chain-of-thought-hub). Higher values are better for all benchmarks. Empty cells mean not available.\\n\\\"\\\"\\\"\\n    return leaderboard_md\\n\\n\\ndef make_leaderboard_md_live(elo_results):\\n    leaderboard_md = f\\\"\\\"\\\"\\n# Leaderboard\\nLast updated: {elo_results[\\\"last_updated_datetime\\\"]}\\n{elo_results[\\\"leaderboard_table\\\"]}\\n\\\"\\\"\\\"\\n    return leaderboard_md\\n\\n\\ndef update_elo_components(max_num_files, elo_results_file):\\n    log_files = get_log_files(max_num_files)\\n\\n    # Leaderboard\\n    if elo_results_file is None:  # Do live update\\n        battles = clean_battle_data(log_files)\\n        elo_results = report_elo_analysis_results(battles)\\n\\n        leader_component_values[0] = make_leaderboard_md_live(elo_results)\\n        leader_component_values[1] = elo_results[\\\"win_fraction_heatmap\\\"]\\n        leader_component_values[2] = elo_results[\\\"battle_count_heatmap\\\"]\\n        leader_component_values[3] = elo_results[\\\"bootstrap_elo_rating\\\"]\\n        leader_component_values[4] = elo_results[\\\"average_win_rate_bar\\\"]\\n\\n    # Basic stats\\n    basic_stats = report_basic_stats(log_files)\\n    md0 = f\\\"Last updated: {basic_stats['last_updated_datetime']}\\\"\\n\\n    md1 = \\\"### Action Histogram\\\\n\\\"\\n    md1 += basic_stats[\\\"action_hist_md\\\"] + \\\"\\\\n\\\"\\n\\n    md2 = \\\"### Anony. Vote Histogram\\\\n\\\"\\n    md2 += basic_stats[\\\"anony_vote_hist_md\\\"] + \\\"\\\\n\\\"\\n\\n    md3 = \\\"### Model Call Histogram\\\\n\\\"\\n    md3 += basic_stats[\\\"model_hist_md\\\"] + \\\"\\\\n\\\"\\n\\n    md4 = \\\"### Model Call (Last 24 Hours)\\\\n\\\"\\n    md4 += basic_stats[\\\"num_chats_last_24_hours\\\"] + \\\"\\\\n\\\"\\n\\n    basic_component_values[0] = md0\\n    basic_component_values[1] = basic_stats[\\\"chat_dates_bar\\\"]\\n    basic_component_values[2] = md1\\n    basic_component_values[3] = md2\\n    basic_component_values[4] = md3\\n    basic_component_values[5] = md4\\n\\n\\ndef update_worker(max_num_files, interval, elo_results_file):\\n    while True:\\n        tic = time.time()\\n        update_elo_components(max_num_files, elo_results_file)\\n        durtaion = time.time() - tic\\n        print(f\\\"update duration: {durtaion:.2f} s\\\")\\n        time.sleep(max(interval - durtaion, 0))\\n\\n\\ndef load_demo(url_params, request: gr.Request):\\n    logger.info(f\\\"load_demo. ip: {request.client.host}. params: {url_params}\\\")\\n    return basic_component_values + leader_component_values\\n\\n\\ndef model_hyperlink(model_name, link):\\n    return f'<a target=\\\"_blank\\\" href=\\\"{link}\\\" style=\\\"color: var(--link-text-color); text-decoration: underline;text-decoration-style: dotted;\\\">{model_name}</a>'\\n\\n\\ndef load_leaderboard_table_csv(filename, add_hyperlink=True):\\n    lines = open(filename).readlines()\\n    heads = [v.strip() for v in lines[0].split(\\\",\\\")]\\n    rows = []\\n    for i in range(1, len(lines)):\\n        row = [v.strip() for v in lines[i].split(\\\",\\\")]\\n        for j in range(len(heads)):\\n            item = {}\\n            for h, v in zip(heads, row):\\n                if h == \\\"Arena Elo rating\\\":\\n                    if v != \\\"-\\\":\\n                        v = int(ast.literal_eval(v))\\n                    else:\\n                        v = np.nan\\n                elif h == \\\"MMLU\\\":\\n                    if v != \\\"-\\\":\\n                        v = round(ast.literal_eval(v) * 100, 1)\\n                    else:\\n                        v = np.nan\\n                elif h == \\\"MT-bench (win rate %)\\\":\\n                    if v != \\\"-\\\":\\n                        v = round(ast.literal_eval(v[:-1]), 1)\\n                    else:\\n                        v = np.nan\\n                elif h == \\\"MT-bench (score)\\\":\\n                    if v != \\\"-\\\":\\n                        v = round(ast.literal_eval(v), 2)\\n                    else:\\n                        v = np.nan\\n                item[h] = v\\n            if add_hyperlink:\\n                item[\\\"Model\\\"] = model_hyperlink(item[\\\"Model\\\"], item[\\\"Link\\\"])\\n        rows.append(item)\\n\\n    return rows\\n\\n\\ndef build_basic_stats_tab():\\n    empty = \\\"Loading ...\\\"\\n    basic_component_values[:] = [empty, None, empty, empty, empty, empty]\\n\\n    md0 = gr.Markdown(empty)\\n    gr.Markdown(\\\"#### Figure 1: Number of model calls and votes\\\")\\n    plot_1 = gr.Plot(show_label=False)\\n    with gr.Row():\\n        with gr.Column():\\n            md1 = gr.Markdown(empty)\\n        with gr.Column():\\n            md2 = gr.Markdown(empty)\\n    with gr.Row():\\n        with gr.Column():\\n            md3 = gr.Markdown(empty)\\n        with gr.Column():\\n            md4 = gr.Markdown(empty)\\n    return [md0, plot_1, md1, md2, md3, md4]\\n\\n\\ndef build_leaderboard_tab(elo_results_file, leaderboard_table_file):\\n    if elo_results_file is None:  # Do live update\\n        md = \\\"Loading ...\\\"\\n        p1 = p2 = p3 = p4 = None\\n    else:\\n        with open(elo_results_file, \\\"rb\\\") as fin:\\n            elo_results = pickle.load(fin)\\n\\n        md = make_leaderboard_md(elo_results)\\n        p1 = elo_results[\\\"win_fraction_heatmap\\\"]\\n        p2 = elo_results[\\\"battle_count_heatmap\\\"]\\n        p3 = elo_results[\\\"bootstrap_elo_rating\\\"]\\n        p4 = elo_results[\\\"average_win_rate_bar\\\"]\\n\\n    md_1 = gr.Markdown(md, elem_id=\\\"leaderboard_markdown\\\")\\n\\n    if leaderboard_table_file:\\n        data = load_leaderboard_table_csv(leaderboard_table_file)\\n        headers = [\\n            \\\"Model\\\",\\n            \\\"Arena Elo rating\\\",\\n            \\\"MT-bench (score)\\\",\\n            \\\"MT-bench (win rate %)\\\",\\n            \\\"MMLU\\\",\\n            \\\"License\\\",\\n        ]\\n        values = []\\n        for item in data:\\n            row = []\\n            for key in headers:\\n                value = item[key]\\n                row.append(value)\\n            values.append(row)\\n        values.sort(key=lambda x: -x[1] if not np.isnan(x[1]) else 1e9)\\n\\n        headers[1] = \\\"\u2b50 \\\" + headers[1]\\n        headers[2] = \\\"\ud83d\udcc8 \\\" + headers[2]\\n\\n        gr.Dataframe(\\n            headers=headers,\\n            datatype=[\\\"markdown\\\", \\\"number\\\", \\\"number\\\", \\\"number\\\", \\\"number\\\", \\\"str\\\"],\\n            value=values,\\n            elem_id=\\\"leaderboard_dataframe\\\",\\n        )\\n        gr.Markdown(\\n            \\\"If you want to see more models, please help us [add them](https://github.com/lm-sys/FastChat/blob/main/docs/arena.md#how-to-add-a-new-model).\\\"\\n        )\\n    else:\\n        pass\\n\\n    gr.Markdown(\\n        f\\\"\\\"\\\"## More Statistics for Chatbot Arena\\\\n\\nWe added some additional figures to show more statistics. The code for generating them is also included in this [notebook]({notebook_url}).\\nPlease note that you may see different orders from different ranking methods. This is expected for models that perform similarly, as demonstrated by the confidence interval in the bootstrap figure. Going forward, we prefer the classical Elo calculation because of its scalability and interpretability. You can find more discussions in this blog [post](https://lmsys.org/blog/2023-05-03-arena/).\\n\\\"\\\"\\\"\\n    )\\n\\n    leader_component_values[:] = [md, p1, p2, p3, p4]\\n\\n    with gr.Row():\\n        with gr.Column():\\n            gr.Markdown(\\n                \\\"#### Figure 1: Fraction of Model A Wins for All Non-tied A vs. B Battles\\\"\\n            )\\n            plot_1 = gr.Plot(p1, show_label=False)\\n        with gr.Column():\\n            gr.Markdown(\\n                \\\"#### Figure 2: Battle Count for Each Combination of Models (without Ties)\\\"\\n            )\\n            plot_2 = gr.Plot(p2, show_label=False)\\n    with gr.Row():\\n        with gr.Column():\\n            gr.Markdown(\\n                \\\"#### Figure 3: Bootstrap of Elo Estimates (1000 Rounds of Random Sampling)\\\"\\n            )\\n            plot_3 = gr.Plot(p3, show_label=False)\\n        with gr.Column():\\n            gr.Markdown(\\n                \\\"#### Figure 4: Average Win Rate Against All Other Models (Assuming Uniform Sampling and No Ties)\\\"\\n            )\\n            plot_4 = gr.Plot(p4, show_label=False)\\n    return [md_1, plot_1, plot_2, plot_3, plot_4]\\n\\n\\ndef build_demo(elo_results_file, leaderboard_table_file):\\n    text_size = gr.themes.sizes.text_lg\\n\\n    with gr.Blocks(\\n        title=\\\"Chatbot Arena Leaderboard\\\",\\n        theme=gr.themes.Base(text_size=text_size),\\n    ) as demo:\\n        leader_components = build_leaderboard_tab(\\n            elo_results_file, leaderboard_table_file\\n        )\\n\\n    return demo\\n\\n\\nif __name__ == \\\"__main__\\\":\\n    parser = argparse.ArgumentParser()\\n    parser.add_argument(\\\"--share\\\", action=\\\"store_true\\\")\\n    args = parser.parse_args()\\n\\n    demo = build_demo(\\\"elo_results_20230619.pkl\\\", \\\"leaderboard_table_20230619.csv\\\")\\n    demo.launch(share=args.share)\\n\"},{\"source_archive\":\"Unified_Psychiatric_AI_Brain_Part1.zip\",\"source_path\":\"source_projects/ChatPsychiatrist-master/ChatPsychiatrist-master/fastchat/serve/monitor/elo_analysis.py\",\"language\":\"py\",\"content\":\"import argparse\\nfrom collections import defaultdict\\nimport datetime\\nimport json\\nimport math\\nimport pickle\\nfrom pytz import timezone\\n\\nimport numpy as np\\nimport pandas as pd\\nimport plotly.express as px\\nfrom tqdm import tqdm\\n\\nfrom fastchat.model.model_registry import get_model_info\\nfrom fastchat.serve.monitor.basic_stats import get_log_files\\nfrom fastchat.serve.monitor.clean_battle_data import clean_battle_data\\n\\n\\npd.options.display.float_format = \\\"{:.2f}\\\".format\\n\\n\\ndef compute_elo(battles, K=4, SCALE=400, BASE=10, INIT_RATING=1000):\\n    rating = defaultdict(lambda: INIT_RATING)\\n\\n    for rd, model_a, model_b, winner in battles[\\n        [\\\"model_a\\\", \\\"model_b\\\", \\\"winner\\\"]\\n    ].itertuples():\\n        ra = rating[model_a]\\n        rb = rating[model_b]\\n        ea = 1 / (1 + BASE ** ((rb - ra) / SCALE))\\n        eb = 1 / (1 + BASE ** ((ra - rb) / SCALE))\\n        if winner == \\\"model_a\\\":\\n            sa = 1\\n        elif winner == \\\"model_b\\\":\\n            sa = 0\\n        elif winner == \\\"tie\\\" or winner == \\\"tie (bothbad)\\\":\\n            sa = 0.5\\n        else:\\n            raise Exception(f\\\"unexpected vote {winner}\\\")\\n        rating[model_a] += K * (sa - ea)\\n        rating[model_b] += K * (1 - sa - eb)\\n\\n    return dict(rating)\\n\\n\\ndef get_bootstrap_result(battles, func_compute_elo, num_round=1000):\\n    rows = []\\n    for i in tqdm(range(num_round), desc=\\\"bootstrap\\\"):\\n        tmp_battles = battles.sample(frac=1.0, replace=True)\\n        rows.append(func_compute_elo(tmp_battles))\\n    df = pd.DataFrame(rows)\\n    return df[df.median().sort_values(ascending=False).index]\\n\\n\\ndef get_median_elo_from_bootstrap(bootstrap_df):\\n    median = dict(bootstrap_df.quantile(0.5))\\n    median = {k: int(v + 0.5) for k, v in median.items()}\\n    return median\\n\\n\\ndef compute_pairwise_win_fraction(battles, model_order):\\n    # Times each model wins as Model A\\n    a_win_ptbl = pd.pivot_table(\\n        battles[battles[\\\"winner\\\"] == \\\"model_a\\\"],\\n        index=\\\"model_a\\\",\\n        columns=\\\"model_b\\\",\\n        aggfunc=\\\"size\\\",\\n        fill_value=0,\\n    )\\n\\n    # Table counting times each model wins as Model B\\n    b_win_ptbl = pd.pivot_table(\\n        battles[battles[\\\"winner\\\"] == \\\"model_b\\\"],\\n        index=\\\"model_a\\\",\\n        columns=\\\"model_b\\\",\\n        aggfunc=\\\"size\\\",\\n        fill_value=0,\\n    )\\n\\n    # Table counting number of A-B pairs\\n    num_battles_ptbl = pd.pivot_table(\\n        battles, index=\\\"model_a\\\", columns=\\\"model_b\\\", aggfunc=\\\"size\\\", fill_value=0\\n    )\\n\\n    # Computing the proportion of wins for each model as A and as B\\n    # against all other models\\n    row_beats_col_freq = (a_win_ptbl + b_win_ptbl.T) / (\\n        num_battles_ptbl + num_battles_ptbl.T\\n    )\\n\\n    if model_order is None:\\n        prop_wins = row_beats_col_freq.mean(axis=1).sort_values(ascending=False)\\n        model_order = list(prop_wins.keys())\\n\\n    # Arrange ordering according to proprition of wins\\n    row_beats_col = row_beats_col_freq.loc[model_order, model_order]\\n    return row_beats_col\\n\\n\\ndef visualize_leaderboard_table(rating):\\n    models = list(rating.keys())\\n    models.sort(key=lambda k: -rating[k])\\n\\n    emoji_dict = {\\n        1: \\\"\ud83e\udd47\\\",\\n        2: \\\"\ud83e\udd48\\\",\\n        3: \\\"\ud83e\udd49\\\",\\n    }\\n\\n    md = \\\"\\\"\\n    md += \\\"| Rank | Model | Elo Rating | Description |\\\\n\\\"\\n    md += \\\"| --- | --- | --- | --- |\\\\n\\\"\\n    for i, model in enumerate(models):\\n        rank = i + 1\\n        minfo = get_model_info(model)\\n        emoji = emoji_dict.get(rank, \\\"\\\")\\n        md += f\\\"| {rank} | {emoji} [{model}]({minfo.link}) | {rating[model]:.0f} | {minfo.description} |\\\\n\\\"\\n\\n    return md\\n\\n\\ndef visualize_pairwise_win_fraction(battles, model_order):\\n    row_beats_col = compute_pairwise_win_fraction(battles, model_order)\\n    fig = px.imshow(\\n        row_beats_col,\\n        color_continuous_scale=\\\"RdBu\\\",\\n        text_auto=\\\".2f\\\",\\n        height=700,\\n        width=700,\\n    )\\n    fig.update_layout(\\n        xaxis_title=\\\"Model B\\\",\\n        yaxis_title=\\\"Model A\\\",\\n        xaxis_side=\\\"top\\\",\\n        title_y=0.07,\\n        title_x=0.5,\\n    )\\n    fig.update_traces(\\n        hovertemplate=\\\"Model A: %{y}<br>Model B: %{x}<br>Fraction of A Wins: %{z}<extra></extra>\\\"\\n    )\\n\\n    return fig\\n\\n\\ndef visualize_battle_count(battles, model_order):\\n    ptbl = pd.pivot_table(\\n        battles, index=\\\"model_a\\\", columns=\\\"model_b\\\", aggfunc=\\\"size\\\", fill_value=0\\n    )\\n    battle_counts = ptbl + ptbl.T\\n    fig = px.imshow(\\n        battle_counts.loc[model_order, model_order],\\n        text_auto=True,\\n        height=700,\\n        width=700,\\n    )\\n    fig.update_layout(\\n        xaxis_title=\\\"Model B\\\",\\n        yaxis_title=\\\"Model A\\\",\\n        xaxis_side=\\\"top\\\",\\n        title_y=0.07,\\n        title_x=0.5,\\n    )\\n    fig.update_traces(\\n        hovertemplate=\\\"Model A: %{y}<br>Model B: %{x}<br>Count: %{z}<extra></extra>\\\"\\n    )\\n    return fig\\n\\n\\ndef visualize_average_win_rate(battles):\\n    row_beats_col_freq = compute_pairwise_win_fraction(battles, None)\\n    fig = px.bar(\\n        row_beats_col_freq.mean(axis=1).sort_values(ascending=False),\\n        text_auto=\\\".2f\\\",\\n        height=500,\\n        width=700,\\n    )\\n    fig.update_layout(\\n        yaxis_title=\\\"Average Win Rate\\\", xaxis_title=\\\"Model\\\", showlegend=False\\n    )\\n    return fig\\n\\n\\ndef visualize_bootstrap_elo_rating(df):\\n    bars = (\\n        pd.DataFrame(\\n            dict(\\n                lower=df.quantile(0.025),\\n                rating=df.quantile(0.5),\\n                upper=df.quantile(0.975),\\n            )\\n        )\\n        .reset_index(names=\\\"model\\\")\\n        .sort_values(\\\"rating\\\", ascending=False)\\n    )\\n    bars[\\\"error_y\\\"] = bars[\\\"upper\\\"] - bars[\\\"rating\\\"]\\n    bars[\\\"error_y_minus\\\"] = bars[\\\"rating\\\"] - bars[\\\"lower\\\"]\\n    bars[\\\"rating_rounded\\\"] = np.round(bars[\\\"rating\\\"], 2)\\n    fig = px.scatter(\\n        bars,\\n        x=\\\"model\\\",\\n        y=\\\"rating\\\",\\n        error_y=\\\"error_y\\\",\\n        error_y_minus=\\\"error_y_minus\\\",\\n        text=\\\"rating_rounded\\\",\\n        height=500,\\n        width=700,\\n    )\\n    fig.update_layout(xaxis_title=\\\"Model\\\", yaxis_title=\\\"Rating\\\")\\n    return fig\\n\\n\\ndef report_elo_analysis_results(battles_json):\\n    battles = pd.DataFrame(battles_json)\\n    battles = battles.sort_values(ascending=True, by=[\\\"tstamp\\\"])\\n    # Only use anonymous votes\\n    battles = battles[battles[\\\"anony\\\"]].reset_index(drop=True)\\n    battles_no_ties = battles[~battles[\\\"winner\\\"].str.contains(\\\"tie\\\")]\\n\\n    # Online update\\n    elo_rating_online = compute_elo(battles)\\n\\n    # Bootstrap\\n    bootstrap_df = get_bootstrap_result(battles, compute_elo)\\n    elo_rating_median = get_median_elo_from_bootstrap(bootstrap_df)\\n    model_order = list(elo_rating_median.keys())\\n    model_order.sort(key=lambda k: -elo_rating_median[k])\\n\\n    # Plots\\n    leaderboard_table = visualize_leaderboard_table(elo_rating_median)\\n    win_fraction_heatmap = visualize_pairwise_win_fraction(battles_no_ties, model_order)\\n    battle_count_heatmap = visualize_battle_count(battles_no_ties, model_order)\\n    average_win_rate_bar = visualize_average_win_rate(battles_no_ties)\\n    bootstrap_elo_rating = visualize_bootstrap_elo_rating(bootstrap_df)\\n\\n    last_updated_tstamp = battles[\\\"tstamp\\\"].max()\\n    last_updated_datetime = datetime.datetime.fromtimestamp(\\n        last_updated_tstamp, tz=timezone(\\\"US/Pacific\\\")\\n    ).strftime(\\\"%Y-%m-%d %H:%M:%S %Z\\\")\\n\\n    return {\\n        \\\"elo_rating_online\\\": elo_rating_online,\\n        \\\"elo_rating_median\\\": elo_rating_median,\\n        \\\"leaderboard_table\\\": leaderboard_table,\\n        \\\"win_fraction_heatmap\\\": win_fraction_heatmap,\\n        \\\"battle_count_heatmap\\\": battle_count_heatmap,\\n        \\\"average_win_rate_bar\\\": average_win_rate_bar,\\n        \\\"bootstrap_elo_rating\\\": bootstrap_elo_rating,\\n        \\\"last_updated_datetime\\\": last_updated_datetime,\\n        \\\"last_updated_tstamp\\\": last_updated_tstamp,\\n    }\\n\\n\\ndef pretty_print_elo_rating(rating):\\n    model_order = list(rating.keys())\\n    model_order.sort(key=lambda k: -rating[k])\\n    for i, model in enumerate(model_order):\\n        print(f\\\"{i+1:2d}, {model:25s}, {rating[model]:.0f}\\\")\\n\\n\\nif __name__ == \\\"__main__\\\":\\n    parser = argparse.ArgumentParser()\\n    parser.add_argument(\\\"--clean-battle-file\\\", type=str)\\n    parser.add_argument(\\\"--max-num-files\\\", type=int)\\n    args = parser.parse_args()\\n\\n    np.random.seed(42)\\n\\n    if args.clean_battle_file:\\n        # Read data from a cleaned battle files\\n        battles = pd.read_json(args.clean_battle_file)\\n    else:\\n        # Read data from all log files\\n        log_files = get_log_files(args.max_num_files)\\n        battles = clean_battle_data(log_files)\\n\\n    results = report_elo_analysis_results(battles)\\n\\n    print(\\\"# Online\\\")\\n    pretty_print_elo_rating(results[\\\"elo_rating_online\\\"])\\n    print(\\\"# Median\\\")\\n    pretty_print_elo_rating(results[\\\"elo_rating_median\\\"])\\n    print(f\\\"last update : {results['last_updated_datetime']}\\\")\\n\\n    last_updated_tstamp = results[\\\"last_updated_tstamp\\\"]\\n    cutoff_date = datetime.datetime.fromtimestamp(\\n        last_updated_tstamp, tz=timezone(\\\"US/Pacific\\\")\\n    ).strftime(\\\"%Y%m%d\\\")\\n\\n    with open(f\\\"elo_results_{cutoff_date}.pkl\\\", \\\"wb\\\") as fout:\\n        pickle.dump(results, fout)\\n\"},{\"source_archive\":\"Unified_Psychiatric_AI_Brain_Part1.zip\",\"source_path\":\"source_projects/ChatPsychiatrist-master/ChatPsychiatrist-master/fastchat/serve/huggingface_api.py\",\"language\":\"py\",\"content\":\"\\\"\\\"\\\"\\nUse FastChat with Hugging Face generation APIs.\\n\\nUsage:\\npython3 -m fastchat.serve.huggingface_api --model lmsys/vicuna-7b-v1.3\\npython3 -m fastchat.serve.huggingface_api --model lmsys/fastchat-t5-3b-v1.0\\n\\\"\\\"\\\"\\nimport argparse\\nimport json\\n\\nimport torch\\nfrom transformers import AutoTokenizer, AutoModelForCausalLM\\n\\nfrom fastchat.model import load_model, get_conversation_template, add_model_args\\n\\n\\n@torch.inference_mode()\\ndef main(args):\\n    model, tokenizer = load_model(\\n        args.model_path,\\n        args.device,\\n        args.num_gpus,\\n        args.max_gpu_memory,\\n        args.load_8bit,\\n        args.cpu_offloading,\\n        revision=args.revision,\\n        debug=args.debug,\\n    )\\n\\n    msg = args.message\\n\\n    conv = get_conversation_template(args.model_path)\\n    conv.append_message(conv.roles[0], msg)\\n    conv.append_message(conv.roles[1], None)\\n    prompt = conv.get_prompt()\\n\\n    inputs = tokenizer([prompt])\\n    inputs = {k: torch.tensor(v).to(args.device) for k, v in inputs.items()}\\n    output_ids = model.generate(\\n        **inputs,\\n        do_sample=True,\\n        temperature=args.temperature,\\n        repetition_penalty=args.repetition_penalty,\\n        max_new_tokens=args.max_new_tokens,\\n    )\\n\\n    if model.config.is_encoder_decoder:\\n        output_ids = output_ids[0]\\n    else:\\n        output_ids = output_ids[0][len(inputs[\\\"input_ids\\\"][0]) :]\\n    outputs = tokenizer.decode(\\n        output_ids, skip_special_tokens=True, spaces_between_special_tokens=False\\n    )\\n\\n    print(f\\\"{conv.roles[0]}: {msg}\\\")\\n    print(f\\\"{conv.roles[1]}: {outputs}\\\")\\n\\n\\nif __name__ == \\\"__main__\\\":\\n    parser = argparse.ArgumentParser()\\n    add_model_args(parser)\\n    parser.add_argument(\\\"--temperature\\\", type=float, default=0.7)\\n    parser.add_argument(\\\"--repetition_penalty\\\", type=float, default=1.0)\\n    parser.add_argument(\\\"--max-new-tokens\\\", type=int, default=512)\\n    parser.add_argument(\\\"--debug\\\", action=\\\"store_true\\\")\\n    parser.add_argument(\\\"--message\\\", type=str, default=\\\"Hello! Who are you?\\\")\\n    args = parser.parse_args()\\n\\n    # Reset default repetition penalty for T5 models.\\n    if \\\"t5\\\" in args.model_path and args.repetition_penalty == 1.0:\\n        args.repetition_penalty = 1.2\\n\\n    main(args)\\n\"},{\"source_archive\":\"Unified_Psychiatric_AI_Brain_Part1.zip\",\"source_path\":\"source_projects/ChatPsychiatrist-master/ChatPsychiatrist-master/fastchat/serve/test_message.py\",\"language\":\"py\",\"content\":\"\\\"\\\"\\\"Send a test message.\\\"\\\"\\\"\\nimport argparse\\nimport json\\n\\nimport requests\\n\\nfrom fastchat.model.model_adapter import get_conversation_template\\n\\n\\ndef main():\\n    model_name = args.model_name\\n\\n    if args.worker_address:\\n        worker_addr = args.worker_address\\n    else:\\n        controller_addr = args.controller_address\\n        ret = requests.post(controller_addr + \\\"/refresh_all_workers\\\")\\n        ret = requests.post(controller_addr + \\\"/list_models\\\")\\n        models = ret.json()[\\\"models\\\"]\\n        models.sort()\\n        print(f\\\"Models: {models}\\\")\\n\\n        ret = requests.post(\\n            controller_addr + \\\"/get_worker_address\\\", json={\\\"model\\\": model_name}\\n        )\\n        worker_addr = ret.json()[\\\"address\\\"]\\n        print(f\\\"worker_addr: {worker_addr}\\\")\\n\\n    if worker_addr == \\\"\\\":\\n        print(f\\\"No available workers for {model_name}\\\")\\n        return\\n\\n    conv = get_conversation_template(model_name)\\n    conv.append_message(conv.roles[0], args.message)\\n    conv.append_message(conv.roles[1], None)\\n    prompt = conv.get_prompt()\\n\\n    headers = {\\\"User-Agent\\\": \\\"FastChat Client\\\"}\\n    gen_params = {\\n        \\\"model\\\": model_name,\\n        \\\"prompt\\\": prompt,\\n        \\\"temperature\\\": args.temperature,\\n        \\\"max_new_tokens\\\": args.max_new_tokens,\\n        \\\"stop\\\": conv.stop_str,\\n        \\\"stop_token_ids\\\": conv.stop_token_ids,\\n        \\\"echo\\\": False,\\n    }\\n    response = requests.post(\\n        worker_addr + \\\"/worker_generate_stream\\\",\\n        headers=headers,\\n        json=gen_params,\\n        stream=True,\\n    )\\n\\n    print(f\\\"{conv.roles[0]}: {args.message}\\\")\\n    print(f\\\"{conv.roles[1]}: \\\", end=\\\"\\\")\\n    prev = 0\\n    for chunk in response.iter_lines(decode_unicode=False, delimiter=b\\\"\\\\0\\\"):\\n        if chunk:\\n            data = json.loads(chunk.decode())\\n            output = data[\\\"text\\\"].strip()\\n            print(output[prev:], end=\\\"\\\", flush=True)\\n            prev = len(output)\\n    print(\\\"\\\")\\n\\n\\nif __name__ == \\\"__main__\\\":\\n    parser = argparse.ArgumentParser()\\n    parser.add_argument(\\n        \\\"--controller-address\\\", type=str, default=\\\"http://localhost:21001\\\"\\n    )\\n    parser.add_argument(\\\"--worker-address\\\", type=str)\\n    parser.add_argument(\\\"--model-name\\\", type=str, required=True)\\n    parser.add_argument(\\\"--temperature\\\", type=float, default=0.0)\\n    parser.add_argument(\\\"--max-new-tokens\\\", type=int, default=32)\\n    parser.add_argument(\\n        \\\"--message\\\", type=str, default=\\\"Tell me a story with more than 1000 words.\\\"\\n    )\\n    args = parser.parse_args()\\n\\n    main()\\n\"},{\"source_archive\":\"Unified_Psychiatric_AI_Brain_Part1.zip\",\"source_path\":\"source_projects/ChatPsychiatrist-master/ChatPsychiatrist-master/fastchat/serve/controller.py\",\"language\":\"py\",\"content\":\"\\\"\\\"\\\"\\nA controller manages distributed workers.\\nIt sends worker addresses to clients.\\n\\\"\\\"\\\"\\nimport argparse\\nimport asyncio\\nimport dataclasses\\nfrom enum import Enum, auto\\nimport json\\nimport logging\\nimport time\\nfrom typing import List, Union\\nimport threading\\n\\nfrom fastapi import FastAPI, Request\\nfrom fastapi.responses import StreamingResponse\\nimport numpy as np\\nimport requests\\nimport uvicorn\\n\\nfrom fastchat.constants import (\\n    CONTROLLER_HEART_BEAT_EXPIRATION,\\n    WORKER_API_TIMEOUT,\\n    ErrorCode,\\n    SERVER_ERROR_MSG,\\n)\\nfrom fastchat.utils import build_logger\\n\\n\\nlogger = build_logger(\\\"controller\\\", \\\"controller.log\\\")\\n\\n\\nclass DispatchMethod(Enum):\\n    LOTTERY = auto()\\n    SHORTEST_QUEUE = auto()\\n\\n    @classmethod\\n    def from_str(cls, name):\\n        if name == \\\"lottery\\\":\\n            return cls.LOTTERY\\n        elif name == \\\"shortest_queue\\\":\\n            return cls.SHORTEST_QUEUE\\n        else:\\n            raise ValueError(f\\\"Invalid dispatch method\\\")\\n\\n\\n@dataclasses.dataclass\\nclass WorkerInfo:\\n    model_names: List[str]\\n    speed: int\\n    queue_length: int\\n    check_heart_beat: bool\\n    last_heart_beat: str\\n\\n\\ndef heart_beat_controller(controller):\\n    while True:\\n        time.sleep(CONTROLLER_HEART_BEAT_EXPIRATION)\\n        controller.remove_stale_workers_by_expiration()\\n\\n\\nclass Controller:\\n    def __init__(self, dispatch_method: str):\\n        # Dict[str -> WorkerInfo]\\n        self.worker_info = {}\\n        self.dispatch_method = DispatchMethod.from_str(dispatch_method)\\n\\n        self.heart_beat_thread = threading.Thread(\\n            target=heart_beat_controller, args=(self,)\\n        )\\n        self.heart_beat_thread.start()\\n\\n    def register_worker(\\n        self, worker_name: str, check_heart_beat: bool, worker_status: dict\\n    ):\\n        if worker_name not in self.worker_info:\\n            logger.info(f\\\"Register a new worker: {worker_name}\\\")\\n        else:\\n            logger.info(f\\\"Register an existing worker: {worker_name}\\\")\\n\\n        if not worker_status:\\n            worker_status = self.get_worker_status(worker_name)\\n        if not worker_status:\\n            return False\\n\\n        self.worker_info[worker_name] = WorkerInfo(\\n            worker_status[\\\"model_names\\\"],\\n            worker_status[\\\"speed\\\"],\\n            worker_status[\\\"queue_length\\\"],\\n            check_heart_beat,\\n            time.time(),\\n        )\\n\\n        logger.info(f\\\"Register done: {worker_name}, {worker_status}\\\")\\n        return True\\n\\n    def get_worker_status(self, worker_name: str):\\n        try:\\n            r = requests.post(worker_name + \\\"/worker_get_status\\\", timeout=5)\\n        except requests.exceptions.RequestException as e:\\n            logger.error(f\\\"Get status fails: {worker_name}, {e}\\\")\\n            return None\\n\\n        if r.status_code != 200:\\n            logger.error(f\\\"Get status fails: {worker_name}, {r}\\\")\\n            return None\\n\\n        return r.json()\\n\\n    def remove_worker(self, worker_name: str):\\n        del self.worker_info[worker_name]\\n\\n    def refresh_all_workers(self):\\n        old_info = dict(self.worker_info)\\n        self.worker_info = {}\\n\\n        for w_name, w_info in old_info.items():\\n            if not self.register_worker(w_name, w_info.check_heart_beat, None):\\n                logger.info(f\\\"Remove stale worker: {w_name}\\\")\\n\\n    def list_models(self):\\n        model_names = set()\\n\\n        for w_name, w_info in self.worker_info.items():\\n            model_names.update(w_info.model_names)\\n\\n        return list(model_names)\\n\\n    def get_worker_address(self, model_name: str):\\n        if self.dispatch_method == DispatchMethod.LOTTERY:\\n            worker_names = []\\n            worker_speeds = []\\n            for w_name, w_info in self.worker_info.items():\\n                if model_name in w_info.model_names:\\n                    worker_names.append(w_name)\\n                    worker_speeds.append(w_info.speed)\\n            worker_speeds = np.array(worker_speeds, dtype=np.float32)\\n            norm = np.sum(worker_speeds)\\n            if norm < 1e-4:\\n                return \\\"\\\"\\n            worker_speeds = worker_speeds / norm\\n            if True:  # Directly return address\\n                pt = np.random.choice(np.arange(len(worker_names)), p=worker_speeds)\\n                worker_name = worker_names[pt]\\n                return worker_name\\n\\n            # Check status before returning\\n            while True:\\n                pt = np.random.choice(np.arange(len(worker_names)), p=worker_speeds)\\n                worker_name = worker_names[pt]\\n\\n                if self.get_worker_status(worker_name):\\n                    break\\n                else:\\n                    self.remove_worker(worker_name)\\n                    worker_speeds[pt] = 0\\n                    norm = np.sum(worker_speeds)\\n                    if norm < 1e-4:\\n                        return \\\"\\\"\\n                    worker_speeds = worker_speeds / norm\\n                    continue\\n            return worker_name\\n        elif self.dispatch_method == DispatchMethod.SHORTEST_QUEUE:\\n            worker_names = []\\n            worker_qlen = []\\n            for w_name, w_info in self.worker_info.items():\\n                if model_name in w_info.model_names:\\n                    worker_names.append(w_name)\\n                    worker_qlen.append(w_info.queue_length / w_info.speed)\\n            if len(worker_names) == 0:\\n                return \\\"\\\"\\n            min_index = np.argmin(worker_qlen)\\n            w_name = worker_names[min_index]\\n            self.worker_info[w_name].queue_length += 1\\n            logger.info(\\n                f\\\"names: {worker_names}, queue_lens: {worker_qlen}, ret: {w_name}\\\"\\n            )\\n            return w_name\\n        else:\\n            raise ValueError(f\\\"Invalid dispatch method: {self.dispatch_method}\\\")\\n\\n    def receive_heart_beat(self, worker_name: str, queue_length: int):\\n        if worker_name not in self.worker_info:\\n            logger.info(f\\\"Receive unknown heart beat. {worker_name}\\\")\\n            return False\\n\\n        self.worker_info[worker_name].queue_length = queue_length\\n        self.worker_info[worker_name].last_heart_beat = time.time()\\n        logger.info(f\\\"Receive heart beat. {worker_name}\\\")\\n        return True\\n\\n    def remove_stale_workers_by_expiration(self):\\n        expire = time.time() - CONTROLLER_HEART_BEAT_EXPIRATION\\n        to_delete = []\\n        for worker_name, w_info in self.worker_info.items():\\n            if w_info.check_heart_beat and w_info.last_heart_beat < expire:\\n                to_delete.append(worker_name)\\n\\n        for worker_name in to_delete:\\n            self.remove_worker(worker_name)\\n\\n    def handle_no_worker(self, params):\\n        logger.info(f\\\"no worker: {params['model']}\\\")\\n        ret = {\\n            \\\"text\\\": SERVER_ERROR_MSG,\\n            \\\"error_code\\\": ErrorCode.CONTROLLER_NO_WORKER,\\n        }\\n        return json.dumps(ret).encode() + b\\\"\\\\0\\\"\\n\\n    def handle_worker_timeout(self, worker_address):\\n        logger.info(f\\\"worker timeout: {worker_address}\\\")\\n        ret = {\\n            \\\"text\\\": SERVER_ERROR_MSG,\\n            \\\"error_code\\\": ErrorCode.CONTROLLER_WORKER_TIMEOUT,\\n        }\\n        return json.dumps(ret).encode() + b\\\"\\\\0\\\"\\n\\n    # Let the controller act as a worker to achieve hierarchical\\n    # management. This can be used to connect isolated sub networks.\\n    def worker_api_get_status(self):\\n        model_names = set()\\n        speed = 0\\n        queue_length = 0\\n\\n        for w_name in self.worker_info:\\n            worker_status = self.get_worker_status(w_name)\\n            if worker_status is not None:\\n                model_names.update(worker_status[\\\"model_names\\\"])\\n                speed += worker_status[\\\"speed\\\"]\\n                queue_length += worker_status[\\\"queue_length\\\"]\\n\\n        model_names = sorted(list(model_names))\\n        return {\\n            \\\"model_names\\\": model_names,\\n            \\\"speed\\\": speed,\\n            \\\"queue_length\\\": queue_length,\\n        }\\n\\n    def worker_api_generate_stream(self, params):\\n        worker_addr = self.get_worker_address(params[\\\"model\\\"])\\n        if not worker_addr:\\n            yield self.handle_no_worker(params)\\n\\n        try:\\n            response = requests.post(\\n                worker_addr + \\\"/worker_generate_stream\\\",\\n                json=params,\\n                stream=True,\\n                timeout=WORKER_API_TIMEOUT,\\n            )\\n            for chunk in response.iter_lines(decode_unicode=False, delimiter=b\\\"\\\\0\\\"):\\n                if chunk:\\n                    yield chunk + b\\\"\\\\0\\\"\\n        except requests.exceptions.RequestException as e:\\n            yield self.handle_worker_timeout(worker_addr)\\n\\n\\napp = FastAPI()\\n\\n\\n@app.post(\\\"/register_worker\\\")\\nasync def register_worker(request: Request):\\n    data = await request.json()\\n    controller.register_worker(\\n        data[\\\"worker_name\\\"], data[\\\"check_heart_beat\\\"], data.get(\\\"worker_status\\\", None)\\n    )\\n\\n\\n@app.post(\\\"/refresh_all_workers\\\")\\nasync def refresh_all_workers():\\n    models = controller.refresh_all_workers()\\n\\n\\n@app.post(\\\"/list_models\\\")\\nasync def list_models():\\n    models = controller.list_models()\\n    return {\\\"models\\\": models}\\n\\n\\n@app.post(\\\"/get_worker_address\\\")\\nasync def get_worker_address(request: Request):\\n    data = await request.json()\\n    addr = controller.get_worker_address(data[\\\"model\\\"])\\n    return {\\\"address\\\": addr}\\n\\n\\n@app.post(\\\"/receive_heart_beat\\\")\\nasync def receive_heart_beat(request: Request):\\n    data = await request.json()\\n    exist = controller.receive_heart_beat(data[\\\"worker_name\\\"], data[\\\"queue_length\\\"])\\n    return {\\\"exist\\\": exist}\\n\\n\\n@app.post(\\\"/worker_generate_stream\\\")\\nasync def worker_api_generate_stream(request: Request):\\n    params = await request.json()\\n    generator = controller.worker_api_generate_stream(params)\\n    return StreamingResponse(generator)\\n\\n\\n@app.post(\\\"/worker_get_status\\\")\\nasync def worker_api_get_status(request: Request):\\n    return controller.worker_api_get_status()\\n\\n\\nif __name__ == \\\"__main__\\\":\\n    parser = argparse.ArgumentParser()\\n    parser.add_argument(\\\"--host\\\", type=str, default=\\\"localhost\\\")\\n    parser.add_argument(\\\"--port\\\", type=int, default=21001)\\n    parser.add_argument(\\n        \\\"--dispatch-method\\\",\\n        type=str,\\n        choices=[\\\"lottery\\\", \\\"shortest_queue\\\"],\\n        default=\\\"shortest_queue\\\",\\n    )\\n    args = parser.parse_args()\\n    logger.info(f\\\"args: {args}\\\")\\n\\n    controller = Controller(args.dispatch_method)\\n    uvicorn.run(app, host=args.host, port=args.port, log_level=\\\"info\\\")\\n\"},{\"source_archive\":\"Unified_Psychiatric_AI_Brain_Part1.zip\",\"source_path\":\"source_projects/ChatPsychiatrist-master/ChatPsychiatrist-master/fastchat/serve/register_worker.py\",\"language\":\"py\",\"content\":\"\\\"\\\"\\\"\\nManually register workers.\\n\\nUsage:\\npython3 -m fastchat.serve.register_worker --controller http://localhost:21001 --worker-name http://localhost:21002\\n\\\"\\\"\\\"\\n\\nimport argparse\\n\\nimport requests\\n\\nif __name__ == \\\"__main__\\\":\\n    parser = argparse.ArgumentParser()\\n    parser.add_argument(\\\"--controller-address\\\", type=str)\\n    parser.add_argument(\\\"--worker-name\\\", type=str)\\n    parser.add_argument(\\\"--check-heart-beat\\\", action=\\\"store_true\\\")\\n    args = parser.parse_args()\\n\\n    url = args.controller_address + \\\"/register_worker\\\"\\n    data = {\\n        \\\"worker_name\\\": args.worker_name,\\n        \\\"check_heart_beat\\\": args.check_heart_beat,\\n        \\\"worker_status\\\": None,\\n    }\\n    r = requests.post(url, json=data)\\n    assert r.status_code == 200\\n\"},{\"source_archive\":\"Unified_Psychiatric_AI_Brain_Part1.zip\",\"source_path\":\"source_projects/ChatPsychiatrist-master/ChatPsychiatrist-master/fastchat/serve/gradio_web_server_multi.py\",\"language\":\"py\",\"content\":\"\\\"\\\"\\\"\\nThe gradio demo server with multiple tabs.\\nIt supports chatting with a single model or chatting with two models side-by-side.\\n\\\"\\\"\\\"\\n\\nimport argparse\\nimport pickle\\nimport time\\n\\nimport gradio as gr\\n\\nfrom fastchat.constants import (\\n    SESSION_EXPIRATION_TIME,\\n)\\nfrom fastchat.serve.gradio_block_arena_anony import (\\n    build_side_by_side_ui_anony,\\n    load_demo_side_by_side_anony,\\n    set_global_vars_anony,\\n)\\nfrom fastchat.serve.gradio_block_arena_named import (\\n    build_side_by_side_ui_named,\\n    load_demo_side_by_side_named,\\n    set_global_vars_named,\\n)\\nfrom fastchat.serve.gradio_web_server import (\\n    set_global_vars,\\n    block_css,\\n    build_single_model_ui,\\n    get_model_list,\\n    load_demo_single,\\n    ip_expiration_dict,\\n)\\nfrom fastchat.serve.monitor.monitor import build_leaderboard_tab\\nfrom fastchat.utils import (\\n    build_logger,\\n    get_window_url_params_js,\\n    parse_gradio_auth_creds,\\n)\\n\\nlogger = build_logger(\\\"gradio_web_server_multi\\\", \\\"gradio_web_server_multi.log\\\")\\n\\n\\ndef load_demo(url_params, request: gr.Request):\\n    global models\\n\\n    ip = request.client.host\\n    logger.info(f\\\"load_demo. ip: {ip}. params: {url_params}\\\")\\n    ip_expiration_dict[ip] = time.time() + SESSION_EXPIRATION_TIME\\n\\n    selected = 0\\n    if \\\"arena\\\" in url_params:\\n        selected = 1\\n    elif \\\"compare\\\" in url_params:\\n        selected = 2\\n    elif \\\"leaderboard\\\" in url_params:\\n        selected = 3\\n\\n    if args.model_list_mode == \\\"reload\\\":\\n        if args.anony_only_for_proprietary_model:\\n            models = get_model_list(args.controller_url, False, False, False)\\n        else:\\n            models = get_model_list(\\n                args.controller_url, args.add_chatgpt, args.add_claude, args.add_palm\\n            )\\n\\n    single_updates = load_demo_single(models, url_params)\\n\\n    models_anony = list(models)\\n    if args.anony_only_for_proprietary_model:\\n        # Only enable these models in anony battles.\\n        if args.add_chatgpt:\\n            models_anony += [\\\"gpt-4\\\", \\\"gpt-3.5-turbo\\\"]\\n        if args.add_claude:\\n            models_anony += [\\\"claude-2\\\", \\\"claude-instant-1\\\"]\\n        if args.add_palm:\\n            models_anony += [\\\"palm-2\\\"]\\n\\n    side_by_side_anony_updates = load_demo_side_by_side_anony(models_anony, url_params)\\n    side_by_side_named_updates = load_demo_side_by_side_named(models, url_params)\\n    return (\\n        (gr.Tabs.update(selected=selected),)\\n        + single_updates\\n        + side_by_side_anony_updates\\n        + side_by_side_named_updates\\n    )\\n\\n\\ndef build_demo(models, elo_results_file, leaderboard_table_file):\\n    with gr.Blocks(\\n        title=\\\"Chat with Open Large Language Models\\\",\\n        theme=gr.themes.Base(),\\n        css=block_css,\\n    ) as demo:\\n        with gr.Tabs() as tabs:\\n            with gr.Tab(\\\"Single Model\\\", id=0):\\n                (\\n                    a_state,\\n                    a_model_selector,\\n                    a_chatbot,\\n                    a_textbox,\\n                    a_send_btn,\\n                    a_button_row,\\n                    a_parameter_row,\\n                ) = build_single_model_ui(models, add_promotion_links=True)\\n                a_list = [\\n                    a_state,\\n                    a_model_selector,\\n                    a_chatbot,\\n                    a_textbox,\\n                    a_send_btn,\\n                    a_button_row,\\n                    a_parameter_row,\\n                ]\\n\\n            with gr.Tab(\\\"Chatbot Arena (battle)\\\", id=1):\\n                (\\n                    b_states,\\n                    b_model_selectors,\\n                    b_chatbots,\\n                    b_textbox,\\n                    b_send_btn,\\n                    b_button_row,\\n                    b_button_row2,\\n                    b_parameter_row,\\n                ) = build_side_by_side_ui_anony(models)\\n                b_list = (\\n                    b_states\\n                    + b_model_selectors\\n                    + b_chatbots\\n                    + [\\n                        b_textbox,\\n                        b_send_btn,\\n                        b_button_row,\\n                        b_button_row2,\\n                        b_parameter_row,\\n                    ]\\n                )\\n\\n            with gr.Tab(\\\"Chatbot Arena (side-by-side)\\\", id=2):\\n                (\\n                    c_states,\\n                    c_model_selectors,\\n                    c_chatbots,\\n                    c_textbox,\\n                    c_send_btn,\\n                    c_button_row,\\n                    c_button_row2,\\n                    c_parameter_row,\\n                ) = build_side_by_side_ui_named(models)\\n                c_list = (\\n                    c_states\\n                    + c_model_selectors\\n                    + c_chatbots\\n                    + [\\n                        c_textbox,\\n                        c_send_btn,\\n                        c_button_row,\\n                        c_button_row2,\\n                        c_parameter_row,\\n                    ]\\n                )\\n\\n            if elo_results_file:\\n                with gr.Tab(\\\"Leaderboard\\\", id=3):\\n                    build_leaderboard_tab(elo_results_file, leaderboard_table_file)\\n\\n        url_params = gr.JSON(visible=False)\\n\\n        if args.model_list_mode not in [\\\"once\\\", \\\"reload\\\"]:\\n            raise ValueError(f\\\"Unknown model list mode: {args.model_list_mode}\\\")\\n        demo.load(\\n            load_demo,\\n            [url_params],\\n            [tabs] + a_list + b_list + c_list,\\n            _js=get_window_url_params_js,\\n        )\\n\\n    return demo\\n\\n\\nif __name__ == \\\"__main__\\\":\\n    parser = argparse.ArgumentParser()\\n    parser.add_argument(\\\"--host\\\", type=str, default=\\\"0.0.0.0\\\")\\n    parser.add_argument(\\\"--port\\\", type=int)\\n    parser.add_argument(\\n        \\\"--share\\\",\\n        action=\\\"store_true\\\",\\n        help=\\\"Whether to generate a public, shareable link.\\\",\\n    )\\n    parser.add_argument(\\n        \\\"--controller-url\\\",\\n        type=str,\\n        default=\\\"http://localhost:21001\\\",\\n        help=\\\"The address of the controller.\\\",\\n    )\\n    parser.add_argument(\\n        \\\"--concurrency-count\\\",\\n        type=int,\\n        default=10,\\n        help=\\\"The concurrency count of the gradio queue.\\\",\\n    )\\n    parser.add_argument(\\n        \\\"--model-list-mode\\\",\\n        type=str,\\n        default=\\\"once\\\",\\n        choices=[\\\"once\\\", \\\"reload\\\"],\\n        help=\\\"Whether to load the model list once or reload the model list every time.\\\",\\n    )\\n    parser.add_argument(\\n        \\\"--moderate\\\", action=\\\"store_true\\\", help=\\\"Enable content moderation\\\"\\n    )\\n    parser.add_argument(\\n        \\\"--add-chatgpt\\\",\\n        action=\\\"store_true\\\",\\n        help=\\\"Add OpenAI's ChatGPT models (gpt-3.5-turbo, gpt-4)\\\",\\n    )\\n    parser.add_argument(\\n        \\\"--add-claude\\\",\\n        action=\\\"store_true\\\",\\n        help=\\\"Add Anthropic's Claude models (claude-2, claude-instant-1)\\\",\\n    )\\n    parser.add_argument(\\n        \\\"--add-palm\\\",\\n        action=\\\"store_true\\\",\\n        help=\\\"Add Google's PaLM model (PaLM 2 for Chat: chat-bison@001)\\\",\\n    )\\n    parser.add_argument(\\n        \\\"--anony-only-for-proprietary-model\\\",\\n        action=\\\"store_true\\\",\\n        help=\\\"Only add ChatGPT, Claude, Bard under anony battle tab\\\",\\n    )\\n    parser.add_argument(\\n        \\\"--gradio-auth-path\\\",\\n        type=str,\\n        help='Set the gradio authentication file path. The file should contain one or more user:password pairs in this format: \\\"u1:p1,u2:p2,u3:p3\\\"',\\n        default=None,\\n    )\\n    parser.add_argument(\\\"--elo-results-file\\\", type=str)\\n    parser.add_argument(\\\"--leaderboard-table-file\\\", type=str)\\n    args = parser.parse_args()\\n    logger.info(f\\\"args: {args}\\\")\\n\\n    # Set global variables\\n    set_global_vars(args.controller_url, args.moderate)\\n    set_global_vars_named(args.moderate)\\n    set_global_vars_anony(args.moderate)\\n    if args.anony_only_for_proprietary_model:\\n        models = get_model_list(args.controller_url, False, False, False)\\n    else:\\n        models = get_model_list(\\n            args.controller_url, args.add_chatgpt, args.add_claude, args.add_palm\\n        )\\n\\n    # Set authorization credentials\\n    auth = None\\n    if args.gradio_auth_path is not None:\\n        auth = parse_gradio_auth_creds(args.gradio_auth_path)\\n\\n    # Launch the demo\\n    demo = build_demo(models, args.elo_results_file, args.leaderboard_table_file)\\n    demo.queue(\\n        concurrency_count=args.concurrency_count, status_update_rate=10, api_open=False\\n    ).launch(\\n        server_name=args.host,\\n        server_port=args.port,\\n        share=args.share,\\n        max_threads=200,\\n        auth=auth,\\n    )\\n\"},{\"source_archive\":\"Unified_Psychiatric_AI_Brain_Part1.zip\",\"source_path\":\"source_projects/ChatPsychiatrist-master/ChatPsychiatrist-master/fastchat/serve/vllm_worker.py\",\"language\":\"py\",\"content\":\"\\\"\\\"\\\"\\nA model worker that executes the model based on vLLM.\\n\\nSee documentations at docs/vllm_integration.md\\n\\\"\\\"\\\"\\n\\nimport argparse\\nimport asyncio\\nimport json\\nfrom typing import List\\n\\nfrom fastapi import FastAPI, Request, BackgroundTasks\\nfrom fastapi.responses import StreamingResponse, JSONResponse\\nimport torch\\nimport uvicorn\\nfrom vllm import AsyncLLMEngine\\nfrom vllm.engine.arg_utils import AsyncEngineArgs\\nfrom vllm.sampling_params import SamplingParams\\nfrom vllm.utils import random_uuid\\n\\nfrom fastchat.serve.model_worker import (\\n    BaseModelWorker,\\n    logger,\\n    worker_id,\\n)\\nfrom fastchat.utils import get_context_length\\n\\n\\napp = FastAPI()\\n\\n\\nclass VLLMWorker(BaseModelWorker):\\n    def __init__(\\n        self,\\n        controller_addr: str,\\n        worker_addr: str,\\n        worker_id: str,\\n        model_path: str,\\n        model_names: List[str],\\n        limit_worker_concurrency: int,\\n        no_register: bool,\\n        llm_engine: AsyncLLMEngine,\\n    ):\\n        super().__init__(\\n            controller_addr,\\n            worker_addr,\\n            worker_id,\\n            model_path,\\n            model_names,\\n            limit_worker_concurrency,\\n        )\\n\\n        logger.info(\\n            f\\\"Loading the model {self.model_names} on worker {worker_id}, worker type: vLLM worker...\\\"\\n        )\\n        self.tokenizer = llm_engine.engine.tokenizer\\n        self.context_len = get_context_length(llm_engine.engine.model_config.hf_config)\\n\\n        if not no_register:\\n            self.init_heart_beat()\\n\\n    async def generate_stream(self, params):\\n        self.call_ct += 1\\n\\n        context = params.pop(\\\"prompt\\\")\\n        request_id = params.pop(\\\"request_id\\\")\\n        temperature = float(params.get(\\\"temperature\\\", 1.0))\\n        top_p = float(params.get(\\\"top_p\\\", 1.0))\\n        max_new_tokens = params.get(\\\"max_new_tokens\\\", 256)\\n        stop_str = params.get(\\\"stop\\\", None)\\n        stop_token_ids = params.get(\\\"stop_token_ids\\\", None) or []\\n        stop_token_ids.append(self.tokenizer.eos_token_id)\\n        echo = params.get(\\\"echo\\\", True)\\n\\n        # Handle stop_str\\n        if isinstance(stop_str, str) and stop_str != \\\"\\\":\\n            stop = [stop_str]\\n        elif isinstance(stop_str, list) and stop_str != []:\\n            stop = stop_str\\n        else:\\n            stop = []\\n\\n        for tid in stop_token_ids:\\n            stop.append(self.tokenizer.decode(tid))\\n\\n        # make sampling params in vllm\\n        top_p = max(top_p, 1e-5)\\n        if temperature <= 1e-5:\\n            top_p = 1.0\\n        sampling_params = SamplingParams(\\n            n=1,\\n            temperature=temperature,\\n            top_p=top_p,\\n            use_beam_search=False,\\n            stop=stop,\\n            max_tokens=max_new_tokens,\\n        )\\n        results_generator = engine.generate(context, sampling_params, request_id)\\n\\n        async for request_output in results_generator:\\n            prompt = request_output.prompt\\n            if echo:\\n                text_outputs = [\\n                    prompt + output.text for output in request_output.outputs\\n                ]\\n            else:\\n                text_outputs = [output.text for output in request_output.outputs]\\n            text_outputs = \\\" \\\".join(text_outputs)\\n            # Note: usage is not supported yet\\n            ret = {\\\"text\\\": text_outputs, \\\"error_code\\\": 0, \\\"usage\\\": {}}\\n            yield (json.dumps(ret) + \\\"\\\\0\\\").encode()\\n\\n    async def generate(self, params):\\n        async for x in self.generate_stream(params):\\n            pass\\n        return json.loads(x[:-1].decode())\\n\\n\\ndef release_worker_semaphore():\\n    worker.semaphore.release()\\n\\n\\ndef acquire_worker_semaphore():\\n    if worker.semaphore is None:\\n        worker.semaphore = asyncio.Semaphore(worker.limit_worker_concurrency)\\n    return worker.semaphore.acquire()\\n\\n\\ndef create_background_tasks(request_id):\\n    async def abort_request() -> None:\\n        await engine.abort(request_id)\\n\\n    background_tasks = BackgroundTasks()\\n    background_tasks.add_task(release_worker_semaphore)\\n    background_tasks.add_task(abort_request)\\n    return background_tasks\\n\\n\\n@app.post(\\\"/worker_generate_stream\\\")\\nasync def api_generate_stream(request: Request):\\n    params = await request.json()\\n    await acquire_worker_semaphore()\\n    request_id = random_uuid()\\n    params[\\\"request_id\\\"] = request_id\\n    generator = worker.generate_stream(params)\\n    background_tasks = create_background_tasks(request_id)\\n    return StreamingResponse(generator, background=background_tasks)\\n\\n\\n@app.post(\\\"/worker_generate\\\")\\nasync def api_generate(request: Request):\\n    params = await request.json()\\n    await acquire_worker_semaphore()\\n    request_id = random_uuid()\\n    params[\\\"request_id\\\"] = request_id\\n    output = await worker.generate(params)\\n    release_worker_semaphore()\\n    await engine.abort(request_id)\\n    return JSONResponse(output)\\n\\n\\n@app.post(\\\"/worker_get_status\\\")\\nasync def api_get_status(request: Request):\\n    return worker.get_status()\\n\\n\\n@app.post(\\\"/count_token\\\")\\nasync def api_count_token(request: Request):\\n    params = await request.json()\\n    return worker.count_token(params)\\n\\n\\n@app.post(\\\"/worker_get_conv_template\\\")\\nasync def api_get_conv(request: Request):\\n    return worker.get_conv_template()\\n\\n\\n@app.post(\\\"/model_details\\\")\\nasync def api_model_details(request: Request):\\n    return {\\\"context_length\\\": worker.context_len}\\n\\n\\nif __name__ == \\\"__main__\\\":\\n    parser = argparse.ArgumentParser()\\n    parser.add_argument(\\\"--host\\\", type=str, default=\\\"localhost\\\")\\n    parser.add_argument(\\\"--port\\\", type=int, default=21002)\\n    parser.add_argument(\\\"--worker-address\\\", type=str, default=\\\"http://localhost:21002\\\")\\n    parser.add_argument(\\n        \\\"--controller-address\\\", type=str, default=\\\"http://localhost:21001\\\"\\n    )\\n    parser.add_argument(\\\"--model-path\\\", type=str, default=\\\"lmsys/vicuna-7b-v1.3\\\")\\n    parser.add_argument(\\n        \\\"--model-names\\\",\\n        type=lambda s: s.split(\\\",\\\"),\\n        help=\\\"Optional display comma separated names\\\",\\n    )\\n    parser.add_argument(\\\"--limit-worker-concurrency\\\", type=int, default=1024)\\n    parser.add_argument(\\\"--no-register\\\", action=\\\"store_true\\\")\\n    parser.add_argument(\\\"--num-gpus\\\", type=int, default=1)\\n\\n    parser = AsyncEngineArgs.add_cli_args(parser)\\n    args = parser.parse_args()\\n    if args.model_path:\\n        args.model = args.model_path\\n    if args.num_gpus > 1:\\n        args.tensor_parallel_size = args.num_gpus\\n\\n    engine_args = AsyncEngineArgs.from_cli_args(args)\\n    engine = AsyncLLMEngine.from_engine_args(engine_args)\\n    worker = VLLMWorker(\\n        args.controller_address,\\n        args.worker_address,\\n        worker_id,\\n        args.model_path,\\n        args.model_names,\\n        args.limit_worker_concurrency,\\n        args.no_register,\\n        engine,\\n    )\\n    uvicorn.run(app, host=args.host, port=args.port, log_level=\\\"info\\\")\\n\"},{\"source_archive\":\"Unified_Psychiatric_AI_Brain_Part1.zip\",\"source_path\":\"source_projects/ChatPsychiatrist-master/ChatPsychiatrist-master/fastchat/serve/inference.py\",\"language\":\"py\",\"content\":\"\\\"\\\"\\\"Inference for FastChat models.\\\"\\\"\\\"\\nimport abc\\nimport gc\\nimport math\\nimport sys\\nimport time\\nfrom typing import Iterable, Optional, Dict\\nimport warnings\\n\\nimport psutil\\nimport torch\\nfrom transformers import (\\n    AutoTokenizer,\\n    AutoModelForCausalLM,\\n    LlamaTokenizer,\\n    LlamaForCausalLM,\\n    AutoModel,\\n    AutoModelForSeq2SeqLM,\\n    T5Tokenizer,\\n    AutoConfig,\\n)\\nfrom transformers.generation.logits_process import (\\n    LogitsProcessorList,\\n    RepetitionPenaltyLogitsProcessor,\\n    TemperatureLogitsWarper,\\n    TopKLogitsWarper,\\n    TopPLogitsWarper,\\n)\\n\\nfrom fastchat.conversation import get_conv_template, SeparatorStyle\\nfrom fastchat.model.model_adapter import (\\n    load_model,\\n    get_conversation_template,\\n    get_generate_stream_function,\\n)\\nfrom fastchat.modules.gptq import GptqConfig\\nfrom fastchat.utils import is_partial_stop, is_sentence_complete, get_context_length\\n\\n\\ndef prepare_logits_processor(\\n    temperature: float, repetition_penalty: float, top_p: float, top_k: int\\n) -> LogitsProcessorList:\\n    processor_list = LogitsProcessorList()\\n    # TemperatureLogitsWarper doesn't accept 0.0, 1.0 makes it a no-op so we skip two cases.\\n    if temperature >= 1e-5 and temperature != 1.0:\\n        processor_list.append(TemperatureLogitsWarper(temperature))\\n    if repetition_penalty > 1.0:\\n        processor_list.append(RepetitionPenaltyLogitsProcessor(repetition_penalty))\\n    if 1e-8 <= top_p < 1.0:\\n        processor_list.append(TopPLogitsWarper(top_p))\\n    if top_k > 0:\\n        processor_list.append(TopKLogitsWarper(top_k))\\n    return processor_list\\n\\n\\n@torch.inference_mode()\\ndef generate_stream(\\n    model,\\n    tokenizer,\\n    params: Dict,\\n    device: str,\\n    context_len: int,\\n    stream_interval: int = 2,\\n    judge_sent_end: bool = False,\\n):\\n    # Read parameters\\n    prompt = params[\\\"prompt\\\"]\\n    len_prompt = len(prompt)\\n    temperature = float(params.get(\\\"temperature\\\", 1.0))\\n    repetition_penalty = float(params.get(\\\"repetition_penalty\\\", 1.0))\\n    top_p = float(params.get(\\\"top_p\\\", 1.0))\\n    top_k = int(params.get(\\\"top_k\\\", -1))  # -1 means disable\\n    max_new_tokens = int(params.get(\\\"max_new_tokens\\\", 256))\\n    echo = bool(params.get(\\\"echo\\\", True))\\n    stop_str = params.get(\\\"stop\\\", None)\\n    stop_token_ids = params.get(\\\"stop_token_ids\\\", None) or []\\n    stop_token_ids.append(tokenizer.eos_token_id)\\n\\n    logits_processor = prepare_logits_processor(\\n        temperature, repetition_penalty, top_p, top_k\\n    )\\n    input_ids = tokenizer(prompt).input_ids\\n\\n    if model.config.is_encoder_decoder:\\n        max_src_len = context_len\\n    else:  # truncate\\n        max_src_len = context_len - max_new_tokens - 1\\n\\n    input_ids = input_ids[-max_src_len:]\\n    output_ids = list(input_ids)\\n    input_echo_len = len(input_ids)\\n\\n    if model.config.is_encoder_decoder:\\n        encoder_output = model.encoder(\\n            input_ids=torch.as_tensor([input_ids], device=device)\\n        )[0]\\n        start_ids = torch.as_tensor(\\n            [[model.generation_config.decoder_start_token_id]],\\n            dtype=torch.int64,\\n            device=device,\\n        )\\n\\n    past_key_values = out = None\\n    sent_interrupt = False\\n    for i in range(max_new_tokens):\\n        if i == 0:  # prefill\\n            if model.config.is_encoder_decoder:\\n                out = model.decoder(\\n                    input_ids=start_ids,\\n                    encoder_hidden_states=encoder_output,\\n                    use_cache=True,\\n                )\\n                logits = model.lm_head(out[0])\\n            else:\\n                out = model(torch.as_tensor([input_ids], device=device), use_cache=True)\\n                logits = out.logits\\n            past_key_values = out.past_key_values\\n        else:  # decoding\\n            if model.config.is_encoder_decoder:\\n                out = model.decoder(\\n                    input_ids=torch.as_tensor(\\n                        [[token] if not sent_interrupt else output_ids], device=device\\n                    ),\\n                    encoder_hidden_states=encoder_output,\\n                    use_cache=True,\\n                    past_key_values=past_key_values if not sent_interrupt else None,\\n                )\\n                sent_interrupt = False\\n\\n                logits = model.lm_head(out[0])\\n            else:\\n                out = model(\\n                    input_ids=torch.as_tensor(\\n                        [[token] if not sent_interrupt else output_ids], device=device\\n                    ),\\n                    use_cache=True,\\n                    past_key_values=past_key_values if not sent_interrupt else None,\\n                )\\n                sent_interrupt = False\\n                logits = out.logits\\n            past_key_values = out.past_key_values\\n\\n        if logits_processor:\\n            if repetition_penalty > 1.0:\\n                tmp_output_ids = torch.as_tensor([output_ids], device=logits.device)\\n            else:\\n                tmp_output_ids = None\\n            last_token_logits = logits_processor(tmp_output_ids, logits[:, -1, :])[0]\\n        else:\\n            last_token_logits = logits[0, -1, :]\\n\\n        if device == \\\"mps\\\":\\n            # Switch to CPU by avoiding some bugs in mps backend.\\n            last_token_logits = last_token_logits.float().to(\\\"cpu\\\")\\n\\n        if temperature < 1e-5 or top_p < 1e-8:  # greedy\\n            _, indices = torch.topk(last_token_logits, 2)\\n            tokens = [int(index) for index in indices.tolist()]\\n        else:\\n            probs = torch.softmax(last_token_logits, dim=-1)\\n            indices = torch.multinomial(probs, num_samples=2)\\n            tokens = [int(token) for token in indices.tolist()]\\n        token = tokens[0]\\n        output_ids.append(token)\\n\\n        if token in stop_token_ids:\\n            stopped = True\\n        else:\\n            stopped = False\\n\\n        # Yield the output tokens\\n        if i % stream_interval == 0 or i == max_new_tokens - 1 or stopped:\\n            if echo:\\n                tmp_output_ids = output_ids\\n                rfind_start = len_prompt\\n            else:\\n                tmp_output_ids = output_ids[input_echo_len:]\\n                rfind_start = 0\\n\\n            output = tokenizer.decode(\\n                tmp_output_ids,\\n                skip_special_tokens=True,\\n                spaces_between_special_tokens=False,\\n                clean_up_tokenization_spaces=True,\\n            )\\n            # TODO: For the issue of incomplete sentences interrupting output, apply a patch and others can also modify it to a more elegant way\\n            if judge_sent_end and stopped and not is_sentence_complete(output):\\n                if len(tokens) > 1:\\n                    token = tokens[1]\\n                    output_ids[-1] = token\\n                else:\\n                    output_ids.pop()\\n                stopped = False\\n                sent_interrupt = True\\n\\n            partially_stopped = False\\n            if stop_str:\\n                if isinstance(stop_str, str):\\n                    pos = output.rfind(stop_str, rfind_start)\\n                    if pos != -1:\\n                        output = output[:pos]\\n                        stopped = True\\n                    else:\\n                        partially_stopped = is_partial_stop(output, stop_str)\\n                elif isinstance(stop_str, Iterable):\\n                    for each_stop in stop_str:\\n                        pos = output.rfind(each_stop, rfind_start)\\n                        if pos != -1:\\n                            output = output[:pos]\\n                            stopped = True\\n                            break\\n                        else:\\n                            partially_stopped = is_partial_stop(output, each_stop)\\n                            if partially_stopped:\\n                                break\\n                else:\\n                    raise ValueError(\\\"Invalid stop field type.\\\")\\n\\n            # Prevent yielding partial stop sequence\\n            if not partially_stopped:\\n                yield {\\n                    \\\"text\\\": output,\\n                    \\\"usage\\\": {\\n                        \\\"prompt_tokens\\\": input_echo_len,\\n                        \\\"completion_tokens\\\": i,\\n                        \\\"total_tokens\\\": input_echo_len + i,\\n                    },\\n                    \\\"finish_reason\\\": None,\\n                }\\n\\n        if stopped:\\n            break\\n\\n    # Finish stream event, which contains finish reason\\n    if i == max_new_tokens - 1:\\n        finish_reason = \\\"length\\\"\\n    elif stopped:\\n        finish_reason = \\\"stop\\\"\\n    else:\\n        finish_reason = None\\n\\n    yield {\\n        \\\"text\\\": output,\\n        \\\"usage\\\": {\\n            \\\"prompt_tokens\\\": input_echo_len,\\n            \\\"completion_tokens\\\": i,\\n            \\\"total_tokens\\\": input_echo_len + i,\\n        },\\n        \\\"finish_reason\\\": finish_reason,\\n    }\\n\\n    # Clean\\n    del past_key_values, out\\n    gc.collect()\\n    torch.cuda.empty_cache()\\n    if device == \\\"xpu\\\":\\n        torch.xpu.empty_cache()\\n\\n\\nclass ChatIO(abc.ABC):\\n    @abc.abstractmethod\\n    def prompt_for_input(self, role: str) -> str:\\n        \\\"\\\"\\\"Prompt for input from a role.\\\"\\\"\\\"\\n\\n    @abc.abstractmethod\\n    def prompt_for_output(self, role: str):\\n        \\\"\\\"\\\"Prompt for output from a role.\\\"\\\"\\\"\\n\\n    @abc.abstractmethod\\n    def stream_output(self, output_stream):\\n        \\\"\\\"\\\"Stream output.\\\"\\\"\\\"\\n\\n\\ndef chat_loop(\\n    model_path: str,\\n    device: str,\\n    num_gpus: int,\\n    max_gpu_memory: str,\\n    load_8bit: bool,\\n    cpu_offloading: bool,\\n    conv_template: Optional[str],\\n    temperature: float,\\n    repetition_penalty: float,\\n    max_new_tokens: int,\\n    chatio: ChatIO,\\n    gptq_config: GptqConfig,\\n    revision: str,\\n    judge_sent_end: bool,\\n    debug: bool,\\n    history: bool = True,\\n):\\n    # Model\\n    model, tokenizer = load_model(\\n        model_path,\\n        device,\\n        num_gpus,\\n        max_gpu_memory,\\n        load_8bit,\\n        cpu_offloading,\\n        gptq_config,\\n        revision,\\n        debug,\\n    )\\n    generate_stream_func = get_generate_stream_function(model, model_path)\\n\\n    model_type = str(type(model)).lower()\\n    is_t5 = \\\"t5\\\" in model_type\\n    is_codet5p = \\\"codet5p\\\" in model_type\\n\\n    # Hardcode T5's default repetition penalty to be 1.2\\n    if is_t5 and repetition_penalty == 1.0:\\n        repetition_penalty = 1.2\\n\\n    # Set context length\\n    context_len = get_context_length(model.config)\\n\\n    # Chat\\n    def new_chat():\\n        if conv_template:\\n            conv = get_conv_template(conv_template)\\n        else:\\n            conv = get_conversation_template(model_path)\\n        return conv\\n\\n    conv = None\\n\\n    while True:\\n        if not history or not conv:\\n            conv = new_chat()\\n\\n        try:\\n            inp = chatio.prompt_for_input(conv.roles[0])\\n        except EOFError:\\n            inp = \\\"\\\"\\n\\n        if inp == \\\"!!exit\\\" or not inp:\\n            print(\\\"exit...\\\")\\n            break\\n\\n        if inp == \\\"!!reset\\\":\\n            print(\\\"resetting...\\\")\\n            conv = new_chat()\\n            continue\\n\\n        conv.append_message(conv.roles[0], inp)\\n        conv.append_message(conv.roles[1], None)\\n        prompt = conv.get_prompt()\\n\\n        if is_codet5p:  # codet5p is a code completion model.\\n            prompt = inp\\n\\n        gen_params = {\\n            \\\"model\\\": model_path,\\n            \\\"prompt\\\": prompt,\\n            \\\"temperature\\\": temperature,\\n            \\\"repetition_penalty\\\": repetition_penalty,\\n            \\\"max_new_tokens\\\": max_new_tokens,\\n            \\\"stop\\\": conv.stop_str,\\n            \\\"stop_token_ids\\\": conv.stop_token_ids,\\n            \\\"echo\\\": False,\\n        }\\n\\n        chatio.prompt_for_output(conv.roles[1])\\n        output_stream = generate_stream_func(\\n            model,\\n            tokenizer,\\n            gen_params,\\n            device,\\n            context_len=context_len,\\n            judge_sent_end=judge_sent_end,\\n        )\\n        t = time.time()\\n        outputs = chatio.stream_output(output_stream)\\n        duration = time.time() - t\\n        conv.update_last_message(outputs.strip())\\n\\n        if debug:\\n            num_tokens = len(tokenizer.encode(outputs))\\n            msg = {\\n                \\\"conv_template\\\": conv.name,\\n                \\\"prompt\\\": prompt,\\n                \\\"outputs\\\": outputs,\\n                \\\"speed (token/s)\\\": round(num_tokens / duration, 2),\\n            }\\n            print(f\\\"\\\\n{msg}\\\\n\\\")\\n\"},{\"source_archive\":\"Unified_Psychiatric_AI_Brain_Part1.zip\",\"source_path\":\"source_projects/ChatPsychiatrist-master/ChatPsychiatrist-master/fastchat/serve/openai_api_server.py\",\"language\":\"py\",\"content\":\"\\\"\\\"\\\"A server that provides OpenAI-compatible RESTful APIs. It supports:\\n\\n- Chat Completions. (Reference: https://platform.openai.com/docs/api-reference/chat)\\n- Completions. (Reference: https://platform.openai.com/docs/api-reference/completions)\\n- Embeddings. (Reference: https://platform.openai.com/docs/api-reference/embeddings)\\n\\nUsage:\\npython3 -m fastchat.serve.openai_api_server\\n\\\"\\\"\\\"\\nimport asyncio\\nimport argparse\\nimport asyncio\\nimport json\\nimport logging\\nimport os\\nfrom typing import Generator, Optional, Union, Dict, List, Any\\n\\nimport fastapi\\nfrom fastapi import Depends, HTTPException\\nfrom fastapi.middleware.cors import CORSMiddleware\\nfrom fastapi.responses import StreamingResponse, JSONResponse\\nfrom fastapi.security.http import HTTPAuthorizationCredentials, HTTPBearer\\nimport httpx\\nfrom pydantic import BaseSettings\\nimport shortuuid\\nimport tiktoken\\nimport uvicorn\\n\\nfrom fastchat.constants import (\\n    WORKER_API_TIMEOUT,\\n    WORKER_API_EMBEDDING_BATCH_SIZE,\\n    ErrorCode,\\n)\\nfrom fastchat.conversation import Conversation, SeparatorStyle\\nfrom fastchat.model.model_adapter import get_conversation_template\\nfrom fastapi.exceptions import RequestValidationError\\nfrom fastchat.protocol.openai_api_protocol import (\\n    ChatCompletionRequest,\\n    ChatCompletionResponse,\\n    ChatCompletionResponseStreamChoice,\\n    ChatCompletionStreamResponse,\\n    ChatMessage,\\n    ChatCompletionResponseChoice,\\n    CompletionRequest,\\n    CompletionResponse,\\n    CompletionResponseChoice,\\n    DeltaMessage,\\n    CompletionResponseStreamChoice,\\n    CompletionStreamResponse,\\n    EmbeddingsRequest,\\n    EmbeddingsResponse,\\n    ErrorResponse,\\n    ModelCard,\\n    ModelList,\\n    ModelPermission,\\n    UsageInfo,\\n)\\nfrom fastchat.protocol.api_protocol import (\\n    APIChatCompletionRequest,\\n    APITokenCheckRequest,\\n    APITokenCheckResponse,\\n    APITokenCheckResponseItem,\\n)\\n\\nlogger = logging.getLogger(__name__)\\n\\nconv_template_map = {}\\n\\n\\nclass AppSettings(BaseSettings):\\n    # The address of the model controller.\\n    controller_address: str = \\\"http://localhost:21001\\\"\\n    api_keys: List[str] = None\\n\\n\\napp_settings = AppSettings()\\napp = fastapi.FastAPI()\\nheaders = {\\\"User-Agent\\\": \\\"FastChat API Server\\\"}\\nget_bearer_token = HTTPBearer(auto_error=False)\\n\\n\\nasync def check_api_key(\\n    auth: Optional[HTTPAuthorizationCredentials] = Depends(get_bearer_token),\\n) -> str:\\n    if app_settings.api_keys:\\n        if auth is None or (token := auth.credentials) not in app_settings.api_keys:\\n            raise HTTPException(\\n                status_code=401,\\n                detail={\\n                    \\\"error\\\": {\\n                        \\\"message\\\": \\\"\\\",\\n                        \\\"type\\\": \\\"invalid_request_error\\\",\\n                        \\\"param\\\": None,\\n                        \\\"code\\\": \\\"invalid_api_key\\\",\\n                    }\\n                },\\n            )\\n        return token\\n    else:\\n        # api_keys not set; allow all\\n        return None\\n\\n\\ndef create_error_response(code: int, message: str) -> JSONResponse:\\n    return JSONResponse(\\n        ErrorResponse(message=message, code=code).dict(), status_code=400\\n    )\\n\\n\\n@app.exception_handler(RequestValidationError)\\nasync def validation_exception_handler(request, exc):\\n    return create_error_response(ErrorCode.VALIDATION_TYPE_ERROR, str(exc))\\n\\n\\nasync def check_model(request) -> Optional[JSONResponse]:\\n    controller_address = app_settings.controller_address\\n    ret = None\\n    async with httpx.AsyncClient() as client:\\n        try:\\n            _worker_addr = await get_worker_address(request.model, client)\\n        except:\\n            models_ret = await client.post(controller_address + \\\"/list_models\\\")\\n            models = models_ret.json()[\\\"models\\\"]\\n            ret = create_error_response(\\n                ErrorCode.INVALID_MODEL,\\n                f\\\"Only {'&&'.join(models)} allowed now, your model {request.model}\\\",\\n            )\\n    return ret\\n\\n\\nasync def check_length(request, prompt, max_tokens):\\n    async with httpx.AsyncClient() as client:\\n        worker_addr = await get_worker_address(request.model, client)\\n\\n        response = await client.post(\\n            worker_addr + \\\"/model_details\\\",\\n            headers=headers,\\n            json={\\\"model\\\": request.model},\\n            timeout=WORKER_API_TIMEOUT,\\n        )\\n        context_len = response.json()[\\\"context_length\\\"]\\n\\n        response = await client.post(\\n            worker_addr + \\\"/count_token\\\",\\n            headers=headers,\\n            json={\\\"model\\\": request.model, \\\"prompt\\\": prompt},\\n            timeout=WORKER_API_TIMEOUT,\\n        )\\n        token_num = response.json()[\\\"count\\\"]\\n\\n    if token_num + max_tokens > context_len:\\n        return create_error_response(\\n            ErrorCode.CONTEXT_OVERFLOW,\\n            f\\\"This model's maximum context length is {context_len} tokens. \\\"\\n            f\\\"However, you requested {max_tokens + token_num} tokens \\\"\\n            f\\\"({token_num} in the messages, \\\"\\n            f\\\"{max_tokens} in the completion). \\\"\\n            f\\\"Please reduce the length of the messages or completion.\\\",\\n        )\\n    else:\\n        return None\\n\\n\\ndef check_requests(request) -> Optional[JSONResponse]:\\n    # Check all params\\n    if request.max_tokens is not None and request.max_tokens <= 0:\\n        return create_error_response(\\n            ErrorCode.PARAM_OUT_OF_RANGE,\\n            f\\\"{request.max_tokens} is less than the minimum of 1 - 'max_tokens'\\\",\\n        )\\n    if request.n is not None and request.n <= 0:\\n        return create_error_response(\\n            ErrorCode.PARAM_OUT_OF_RANGE,\\n            f\\\"{request.n} is less than the minimum of 1 - 'n'\\\",\\n        )\\n    if request.temperature is not None and request.temperature < 0:\\n        return create_error_response(\\n            ErrorCode.PARAM_OUT_OF_RANGE,\\n            f\\\"{request.temperature} is less than the minimum of 0 - 'temperature'\\\",\\n        )\\n    if request.temperature is not None and request.temperature > 2:\\n        return create_error_response(\\n            ErrorCode.PARAM_OUT_OF_RANGE,\\n            f\\\"{request.temperature} is greater than the maximum of 2 - 'temperature'\\\",\\n        )\\n    if request.top_p is not None and request.top_p < 0:\\n        return create_error_response(\\n            ErrorCode.PARAM_OUT_OF_RANGE,\\n            f\\\"{request.top_p} is less than the minimum of 0 - 'top_p'\\\",\\n        )\\n    if request.top_p is not None and request.top_p > 1:\\n        return create_error_response(\\n            ErrorCode.PARAM_OUT_OF_RANGE,\\n            f\\\"{request.top_p} is greater than the maximum of 1 - 'temperature'\\\",\\n        )\\n    if request.stop is not None and (\\n        not isinstance(request.stop, str) and not isinstance(request.stop, list)\\n    ):\\n        return create_error_response(\\n            ErrorCode.PARAM_OUT_OF_RANGE,\\n            f\\\"{request.stop} is not valid under any of the given schemas - 'stop'\\\",\\n        )\\n\\n    return None\\n\\n\\ndef process_input(model_name, inp):\\n    if isinstance(inp, str):\\n        inp = [inp]\\n    elif isinstance(inp, list):\\n        if isinstance(inp[0], int):\\n            decoding = tiktoken.model.encoding_for_model(model_name)\\n            inp = [decoding.decode(inp)]\\n        elif isinstance(inp[0], list):\\n            decoding = tiktoken.model.encoding_for_model(model_name)\\n            inp = [decoding.decode(text) for text in inp]\\n\\n    return inp\\n\\n\\nasync def get_gen_params(\\n    model_name: str,\\n    messages: Union[str, List[Dict[str, str]]],\\n    *,\\n    temperature: float,\\n    top_p: float,\\n    max_tokens: Optional[int],\\n    echo: Optional[bool],\\n    stream: Optional[bool],\\n    stop: Optional[Union[str, List[str]]],\\n) -> Dict[str, Any]:\\n    conv = await get_conv(model_name)\\n    conv = Conversation(\\n        name=conv[\\\"name\\\"],\\n        system=conv[\\\"system\\\"],\\n        roles=conv[\\\"roles\\\"],\\n        messages=list(conv[\\\"messages\\\"]),  # prevent in-place modification\\n        offset=conv[\\\"offset\\\"],\\n        sep_style=SeparatorStyle(conv[\\\"sep_style\\\"]),\\n        sep=conv[\\\"sep\\\"],\\n        sep2=conv[\\\"sep2\\\"],\\n        stop_str=conv[\\\"stop_str\\\"],\\n        stop_token_ids=conv[\\\"stop_token_ids\\\"],\\n    )\\n\\n    if isinstance(messages, str):\\n        prompt = messages\\n    else:\\n        for message in messages:\\n            msg_role = message[\\\"role\\\"]\\n            if msg_role == \\\"system\\\":\\n                conv.system = message[\\\"content\\\"]\\n            elif msg_role == \\\"user\\\":\\n                conv.append_message(conv.roles[0], message[\\\"content\\\"])\\n            elif msg_role == \\\"assistant\\\":\\n                conv.append_message(conv.roles[1], message[\\\"content\\\"])\\n            else:\\n                raise ValueError(f\\\"Unknown role: {msg_role}\\\")\\n\\n        # Add a blank message for the assistant.\\n        conv.append_message(conv.roles[1], None)\\n        prompt = conv.get_prompt()\\n\\n    if max_tokens is None:\\n        max_tokens = 512\\n    gen_params = {\\n        \\\"model\\\": model_name,\\n        \\\"prompt\\\": prompt,\\n        \\\"temperature\\\": temperature,\\n        \\\"top_p\\\": top_p,\\n        \\\"max_new_tokens\\\": max_tokens,\\n        \\\"echo\\\": echo,\\n        \\\"stream\\\": stream,\\n    }\\n\\n    if not stop:\\n        gen_params.update(\\n            {\\\"stop\\\": conv.stop_str, \\\"stop_token_ids\\\": conv.stop_token_ids}\\n        )\\n    else:\\n        gen_params.update({\\\"stop\\\": stop})\\n\\n    logger.debug(f\\\"==== request ====\\\\n{gen_params}\\\")\\n    return gen_params\\n\\n\\nasync def get_worker_address(model_name: str, client: httpx.AsyncClient) -> str:\\n    \\\"\\\"\\\"\\n    Get worker address based on the requested model\\n\\n    :param model_name: The worker's model name\\n    :param client: The httpx client to use\\n    :return: Worker address from the controller\\n    :raises: :class:`ValueError`: No available worker for requested model\\n    \\\"\\\"\\\"\\n    controller_address = app_settings.controller_address\\n\\n    ret = await client.post(\\n        controller_address + \\\"/get_worker_address\\\", json={\\\"model\\\": model_name}\\n    )\\n    worker_addr = ret.json()[\\\"address\\\"]\\n    # No available worker\\n    if worker_addr == \\\"\\\":\\n        raise ValueError(f\\\"No available worker for {model_name}\\\")\\n\\n    logger.debug(f\\\"model_name: {model_name}, worker_addr: {worker_addr}\\\")\\n    return worker_addr\\n\\n\\nasync def get_conv(model_name: str):\\n    controller_address = app_settings.controller_address\\n    async with httpx.AsyncClient() as client:\\n        worker_addr = await get_worker_address(model_name, client)\\n        conv_template = conv_template_map.get((worker_addr, model_name))\\n        if conv_template is None:\\n            response = await client.post(\\n                worker_addr + \\\"/worker_get_conv_template\\\",\\n                headers=headers,\\n                json={\\\"model\\\": model_name},\\n                timeout=WORKER_API_TIMEOUT,\\n            )\\n            conv_template = response.json()[\\\"conv\\\"]\\n            conv_template_map[(worker_addr, model_name)] = conv_template\\n        return conv_template\\n\\n\\n@app.get(\\\"/v1/models\\\", dependencies=[Depends(check_api_key)])\\nasync def show_available_models():\\n    controller_address = app_settings.controller_address\\n    async with httpx.AsyncClient() as client:\\n        ret = await client.post(controller_address + \\\"/refresh_all_workers\\\")\\n        ret = await client.post(controller_address + \\\"/list_models\\\")\\n    models = ret.json()[\\\"models\\\"]\\n    models.sort()\\n    # TODO: return real model permission details\\n    model_cards = []\\n    for m in models:\\n        model_cards.append(ModelCard(id=m, root=m, permission=[ModelPermission()]))\\n    return ModelList(data=model_cards)\\n\\n\\n@app.post(\\\"/v1/chat/completions\\\", dependencies=[Depends(check_api_key)])\\nasync def create_chat_completion(request: ChatCompletionRequest):\\n    \\\"\\\"\\\"Creates a completion for the chat message\\\"\\\"\\\"\\n    error_check_ret = await check_model(request)\\n    if error_check_ret is not None:\\n        return error_check_ret\\n    error_check_ret = check_requests(request)\\n    if error_check_ret is not None:\\n        return error_check_ret\\n\\n    gen_params = await get_gen_params(\\n        request.model,\\n        request.messages,\\n        temperature=request.temperature,\\n        top_p=request.top_p,\\n        max_tokens=request.max_tokens,\\n        echo=False,\\n        stream=request.stream,\\n        stop=request.stop,\\n    )\\n    error_check_ret = await check_length(\\n        request, gen_params[\\\"prompt\\\"], gen_params[\\\"max_new_tokens\\\"]\\n    )\\n    if error_check_ret is not None:\\n        return error_check_ret\\n\\n    if request.stream:\\n        generator = chat_completion_stream_generator(\\n            request.model, gen_params, request.n\\n        )\\n        return StreamingResponse(generator, media_type=\\\"text/event-stream\\\")\\n\\n    choices = []\\n    chat_completions = []\\n    for i in range(request.n):\\n        content = asyncio.create_task(generate_completion(gen_params))\\n        chat_completions.append(content)\\n    try:\\n        all_tasks = await asyncio.gather(*chat_completions)\\n    except Exception as e:\\n        return create_error_response(ErrorCode.INTERNAL_ERROR, str(e))\\n    usage = UsageInfo()\\n    for i, content in enumerate(all_tasks):\\n        if content[\\\"error_code\\\"] != 0:\\n            return create_error_response(content[\\\"error_code\\\"], content[\\\"text\\\"])\\n        choices.append(\\n            ChatCompletionResponseChoice(\\n                index=i,\\n                message=ChatMessage(role=\\\"assistant\\\", content=content[\\\"text\\\"]),\\n                finish_reason=content.get(\\\"finish_reason\\\", \\\"stop\\\"),\\n            )\\n        )\\n        if \\\"usage\\\" in content:\\n            task_usage = UsageInfo.parse_obj(content[\\\"usage\\\"])\\n            for usage_key, usage_value in task_usage.dict().items():\\n                setattr(usage, usage_key, getattr(usage, usage_key) + usage_value)\\n\\n    return ChatCompletionResponse(model=request.model, choices=choices, usage=usage)\\n\\n\\nasync def chat_completion_stream_generator(\\n    model_name: str, gen_params: Dict[str, Any], n: int\\n) -> Generator[str, Any, None]:\\n    \\\"\\\"\\\"\\n    Event stream format:\\n    https://developer.mozilla.org/en-US/docs/Web/API/Server-sent_events/Using_server-sent_events#event_stream_format\\n    \\\"\\\"\\\"\\n    id = f\\\"chatcmpl-{shortuuid.random()}\\\"\\n    finish_stream_events = []\\n    for i in range(n):\\n        # First chunk with role\\n        choice_data = ChatCompletionResponseStreamChoice(\\n            index=i,\\n            delta=DeltaMessage(role=\\\"assistant\\\"),\\n            finish_reason=None,\\n        )\\n        chunk = ChatCompletionStreamResponse(\\n            id=id, choices=[choice_data], model=model_name\\n        )\\n        yield f\\\"data: {chunk.json(exclude_unset=True, ensure_ascii=False)}\\\\n\\\\n\\\"\\n\\n        previous_text = \\\"\\\"\\n        async for content in generate_completion_stream(gen_params):\\n            if content[\\\"error_code\\\"] != 0:\\n                yield f\\\"data: {json.dumps(content, ensure_ascii=False)}\\\\n\\\\n\\\"\\n                yield \\\"data: [DONE]\\\\n\\\\n\\\"\\n                return\\n            decoded_unicode = content[\\\"text\\\"].replace(\\\"\\\\ufffd\\\", \\\"\\\")\\n            delta_text = decoded_unicode[len(previous_text) :]\\n            previous_text = decoded_unicode\\n\\n            if len(delta_text) == 0:\\n                delta_text = None\\n            choice_data = ChatCompletionResponseStreamChoice(\\n                index=i,\\n                delta=DeltaMessage(content=delta_text),\\n                finish_reason=content.get(\\\"finish_reason\\\", None),\\n            )\\n            chunk = ChatCompletionStreamResponse(\\n                id=id, choices=[choice_data], model=model_name\\n            )\\n            if delta_text is None:\\n                if content.get(\\\"finish_reason\\\", None) is not None:\\n                    finish_stream_events.append(chunk)\\n                continue\\n            yield f\\\"data: {chunk.json(exclude_unset=True, ensure_ascii=False)}\\\\n\\\\n\\\"\\n    # There is not \\\"content\\\" field in the last delta message, so exclude_none to exclude field \\\"content\\\".\\n    for finish_chunk in finish_stream_events:\\n        yield f\\\"data: {finish_chunk.json(exclude_none=True, ensure_ascii=False)}\\\\n\\\\n\\\"\\n    yield \\\"data: [DONE]\\\\n\\\\n\\\"\\n\\n\\n@app.post(\\\"/v1/completions\\\", dependencies=[Depends(check_api_key)])\\nasync def create_completion(request: CompletionRequest):\\n    error_check_ret = await check_model(request)\\n    if error_check_ret is not None:\\n        return error_check_ret\\n    error_check_ret = check_requests(request)\\n    if error_check_ret is not None:\\n        return error_check_ret\\n\\n    request.prompt = process_input(request.model, request.prompt)\\n\\n    for text in request.prompt:\\n        error_check_ret = await check_length(request, text, request.max_tokens)\\n        if error_check_ret is not None:\\n            return error_check_ret\\n\\n    if request.stream:\\n        generator = generate_completion_stream_generator(request, request.n)\\n        return StreamingResponse(generator, media_type=\\\"text/event-stream\\\")\\n    else:\\n        text_completions = []\\n        for text in request.prompt:\\n            gen_params = await get_gen_params(\\n                request.model,\\n                text,\\n                temperature=request.temperature,\\n                top_p=request.top_p,\\n                max_tokens=request.max_tokens,\\n                echo=request.echo,\\n                stream=request.stream,\\n                stop=request.stop,\\n            )\\n            for i in range(request.n):\\n                content = asyncio.create_task(generate_completion(gen_params))\\n                text_completions.append(content)\\n\\n        try:\\n            all_tasks = await asyncio.gather(*text_completions)\\n        except Exception as e:\\n            return create_error_response(ErrorCode.INTERNAL_ERROR, str(e))\\n\\n        choices = []\\n        usage = UsageInfo()\\n        for i, content in enumerate(all_tasks):\\n            if content[\\\"error_code\\\"] != 0:\\n                return create_error_response(content[\\\"error_code\\\"], content[\\\"text\\\"])\\n            choices.append(\\n                CompletionResponseChoice(\\n                    index=i,\\n                    text=content[\\\"text\\\"],\\n                    logprobs=content.get(\\\"logprobs\\\", None),\\n                    finish_reason=content.get(\\\"finish_reason\\\", \\\"stop\\\"),\\n                )\\n            )\\n            task_usage = UsageInfo.parse_obj(content[\\\"usage\\\"])\\n            for usage_key, usage_value in task_usage.dict().items():\\n                setattr(usage, usage_key, getattr(usage, usage_key) + usage_value)\\n\\n        return CompletionResponse(\\n            model=request.model, choices=choices, usage=UsageInfo.parse_obj(usage)\\n        )\\n\\n\\nasync def generate_completion_stream_generator(request: CompletionRequest, n: int):\\n    model_name = request.model\\n    id = f\\\"cmpl-{shortuuid.random()}\\\"\\n    finish_stream_events = []\\n    for text in request.prompt:\\n        for i in range(n):\\n            previous_text = \\\"\\\"\\n            gen_params = await get_gen_params(\\n                request.model,\\n                text,\\n                temperature=request.temperature,\\n                top_p=request.top_p,\\n                max_tokens=request.max_tokens,\\n                echo=request.echo,\\n                stream=request.stream,\\n                stop=request.stop,\\n            )\\n            async for content in generate_completion_stream(gen_params):\\n                if content[\\\"error_code\\\"] != 0:\\n                    yield f\\\"data: {json.dumps(content, ensure_ascii=False)}\\\\n\\\\n\\\"\\n                    yield \\\"data: [DONE]\\\\n\\\\n\\\"\\n                    return\\n                decoded_unicode = content[\\\"text\\\"].replace(\\\"\\\\ufffd\\\", \\\"\\\")\\n                delta_text = decoded_unicode[len(previous_text) :]\\n                previous_text = decoded_unicode\\n                # todo: index is not apparent\\n                choice_data = CompletionResponseStreamChoice(\\n                    index=i,\\n                    text=delta_text,\\n                    logprobs=content.get(\\\"logprobs\\\", None),\\n                    finish_reason=content.get(\\\"finish_reason\\\", None),\\n                )\\n                chunk = CompletionStreamResponse(\\n                    id=id,\\n                    object=\\\"text_completion\\\",\\n                    choices=[choice_data],\\n                    model=model_name,\\n                )\\n                if len(delta_text) == 0:\\n                    if content.get(\\\"finish_reason\\\", None) is not None:\\n                        finish_stream_events.append(chunk)\\n                    continue\\n                yield f\\\"data: {chunk.json(exclude_unset=True, ensure_ascii=False)}\\\\n\\\\n\\\"\\n    # There is not \\\"content\\\" field in the last delta message, so exclude_none to exclude field \\\"content\\\".\\n    for finish_chunk in finish_stream_events:\\n        yield f\\\"data: {finish_chunk.json(exclude_unset=True, ensure_ascii=False)}\\\\n\\\\n\\\"\\n    yield \\\"data: [DONE]\\\\n\\\\n\\\"\\n\\n\\nasync def generate_completion_stream(payload: Dict[str, Any]):\\n    controller_address = app_settings.controller_address\\n    async with httpx.AsyncClient() as client:\\n        worker_addr = await get_worker_address(payload[\\\"model\\\"], client)\\n        delimiter = b\\\"\\\\0\\\"\\n        async with client.stream(\\n            \\\"POST\\\",\\n            worker_addr + \\\"/worker_generate_stream\\\",\\n            headers=headers,\\n            json=payload,\\n            timeout=WORKER_API_TIMEOUT,\\n        ) as response:\\n            # content = await response.aread()\\n            async for raw_chunk in response.aiter_raw():\\n                for chunk in raw_chunk.split(delimiter):\\n                    if not chunk:\\n                        continue\\n                    data = json.loads(chunk.decode())\\n                    yield data\\n\\n\\nasync def generate_completion(payload: Dict[str, Any]):\\n    async with httpx.AsyncClient() as client:\\n        worker_addr = await get_worker_address(payload[\\\"model\\\"], client)\\n\\n        response = await client.post(\\n            worker_addr + \\\"/worker_generate\\\",\\n            headers=headers,\\n            json=payload,\\n            timeout=WORKER_API_TIMEOUT,\\n        )\\n        completion = response.json()\\n        return completion\\n\\n\\n@app.post(\\\"/v1/embeddings\\\", dependencies=[Depends(check_api_key)])\\n@app.post(\\\"/v1/engines/{model_name}/embeddings\\\", dependencies=[Depends(check_api_key)])\\nasync def create_embeddings(request: EmbeddingsRequest, model_name: str = None):\\n    \\\"\\\"\\\"Creates embeddings for the text\\\"\\\"\\\"\\n    if request.model is None:\\n        request.model = model_name\\n    error_check_ret = await check_model(request)\\n    if error_check_ret is not None:\\n        return error_check_ret\\n\\n    request.input = process_input(request.model, request.input)\\n\\n    data = []\\n    token_num = 0\\n    batch_size = WORKER_API_EMBEDDING_BATCH_SIZE\\n    batches = [\\n        request.input[i : min(i + batch_size, len(request.input))]\\n        for i in range(0, len(request.input), batch_size)\\n    ]\\n    for num_batch, batch in enumerate(batches):\\n        payload = {\\n            \\\"model\\\": request.model,\\n            \\\"input\\\": batch,\\n        }\\n        embedding = await get_embedding(payload)\\n        if \\\"error_code\\\" in embedding and embedding[\\\"error_code\\\"] != 0:\\n            return create_error_response(embedding[\\\"error_code\\\"], embedding[\\\"text\\\"])\\n        data += [\\n            {\\n                \\\"object\\\": \\\"embedding\\\",\\n                \\\"embedding\\\": emb,\\n                \\\"index\\\": num_batch * batch_size + i,\\n            }\\n            for i, emb in enumerate(embedding[\\\"embedding\\\"])\\n        ]\\n        token_num += embedding[\\\"token_num\\\"]\\n    return EmbeddingsResponse(\\n        data=data,\\n        model=request.model,\\n        usage=UsageInfo(\\n            prompt_tokens=token_num,\\n            total_tokens=token_num,\\n            completion_tokens=None,\\n        ),\\n    ).dict(exclude_none=True)\\n\\n\\nasync def get_embedding(payload: Dict[str, Any]):\\n    controller_address = app_settings.controller_address\\n    model_name = payload[\\\"model\\\"]\\n    async with httpx.AsyncClient() as client:\\n        worker_addr = await get_worker_address(model_name, client)\\n\\n        response = await client.post(\\n            worker_addr + \\\"/worker_get_embeddings\\\",\\n            headers=headers,\\n            json=payload,\\n            timeout=WORKER_API_TIMEOUT,\\n        )\\n        embedding = response.json()\\n        return embedding\\n\\n\\n### GENERAL API - NOT OPENAI COMPATIBLE ###\\n\\n\\n@app.post(\\\"/api/v1/token_check\\\")\\nasync def count_tokens(request: APITokenCheckRequest):\\n    \\\"\\\"\\\"\\n    Checks the token count for each message in your list\\n    This is not part of the OpenAI API spec.\\n    \\\"\\\"\\\"\\n    checkedList = []\\n    async with httpx.AsyncClient() as client:\\n        for item in request.prompts:\\n            worker_addr = await get_worker_address(item.model, client)\\n\\n            response = await client.post(\\n                worker_addr + \\\"/model_details\\\",\\n                headers=headers,\\n                json={\\\"model\\\": item.model},\\n                timeout=WORKER_API_TIMEOUT,\\n            )\\n            context_len = response.json()[\\\"context_length\\\"]\\n\\n            response = await client.post(\\n                worker_addr + \\\"/count_token\\\",\\n                headers=headers,\\n                json={\\\"prompt\\\": item.prompt, \\\"model\\\": item.model},\\n                timeout=WORKER_API_TIMEOUT,\\n            )\\n            token_num = response.json()[\\\"count\\\"]\\n\\n            can_fit = True\\n            if token_num + item.max_tokens > context_len:\\n                can_fit = False\\n\\n            checkedList.append(\\n                APITokenCheckResponseItem(\\n                    fits=can_fit, contextLength=context_len, tokenCount=token_num\\n                )\\n            )\\n\\n    return APITokenCheckResponse(prompts=checkedList)\\n\\n\\n@app.post(\\\"/api/v1/chat/completions\\\")\\nasync def create_chat_completion(request: APIChatCompletionRequest):\\n    \\\"\\\"\\\"Creates a completion for the chat message\\\"\\\"\\\"\\n    error_check_ret = await check_model(request)\\n    if error_check_ret is not None:\\n        return error_check_ret\\n    error_check_ret = check_requests(request)\\n    if error_check_ret is not None:\\n        return error_check_ret\\n\\n    gen_params = await get_gen_params(\\n        request.model,\\n        request.messages,\\n        temperature=request.temperature,\\n        top_p=request.top_p,\\n        max_tokens=request.max_tokens,\\n        echo=False,\\n        stream=request.stream,\\n        stop=request.stop,\\n    )\\n\\n    if request.repetition_penalty is not None:\\n        gen_params[\\\"repetition_penalty\\\"] = request.repetition_penalty\\n\\n    error_check_ret = await check_length(\\n        request, gen_params[\\\"prompt\\\"], gen_params[\\\"max_new_tokens\\\"]\\n    )\\n    if error_check_ret is not None:\\n        return error_check_ret\\n\\n    if request.stream:\\n        generator = chat_completion_stream_generator(\\n            request.model, gen_params, request.n\\n        )\\n        return StreamingResponse(generator, media_type=\\\"text/event-stream\\\")\\n\\n    choices = []\\n    chat_completions = []\\n    for i in range(request.n):\\n        content = asyncio.create_task(generate_completion(gen_params))\\n        chat_completions.append(content)\\n    try:\\n        all_tasks = await asyncio.gather(*chat_completions)\\n    except Exception as e:\\n        return create_error_response(ErrorCode.INTERNAL_ERROR, str(e))\\n    usage = UsageInfo()\\n    for i, content in enumerate(all_tasks):\\n        if content[\\\"error_code\\\"] != 0:\\n            return create_error_response(content[\\\"error_code\\\"], content[\\\"text\\\"])\\n        choices.append(\\n            ChatCompletionResponseChoice(\\n                index=i,\\n                message=ChatMessage(role=\\\"assistant\\\", content=content[\\\"text\\\"]),\\n                finish_reason=content.get(\\\"finish_reason\\\", \\\"stop\\\"),\\n            )\\n        )\\n        task_usage = UsageInfo.parse_obj(content[\\\"usage\\\"])\\n        for usage_key, usage_value in task_usage.dict().items():\\n            setattr(usage, usage_key, getattr(usage, usage_key) + usage_value)\\n\\n    return ChatCompletionResponse(model=request.model, choices=choices, usage=usage)\\n\\n\\n### END GENERAL API - NOT OPENAI COMPATIBLE ###\\n\\n\\nif __name__ == \\\"__main__\\\":\\n    parser = argparse.ArgumentParser(\\n        description=\\\"FastChat ChatGPT-Compatible RESTful API server.\\\"\\n    )\\n    parser.add_argument(\\\"--host\\\", type=str, default=\\\"localhost\\\", help=\\\"host name\\\")\\n    parser.add_argument(\\\"--port\\\", type=int, default=8000, help=\\\"port number\\\")\\n    parser.add_argument(\\n        \\\"--controller-address\\\", type=str, default=\\\"http://localhost:21001\\\"\\n    )\\n    parser.add_argument(\\n        \\\"--allow-credentials\\\", action=\\\"store_true\\\", help=\\\"allow credentials\\\"\\n    )\\n    parser.add_argument(\\n        \\\"--allowed-origins\\\", type=json.loads, default=[\\\"*\\\"], help=\\\"allowed origins\\\"\\n    )\\n    parser.add_argument(\\n        \\\"--allowed-methods\\\", type=json.loads, default=[\\\"*\\\"], help=\\\"allowed methods\\\"\\n    )\\n    parser.add_argument(\\n        \\\"--allowed-headers\\\", type=json.loads, default=[\\\"*\\\"], help=\\\"allowed headers\\\"\\n    )\\n    parser.add_argument(\\n        \\\"--api-keys\\\",\\n        type=lambda s: s.split(\\\",\\\"),\\n        help=\\\"Optional list of comma separated API keys\\\",\\n    )\\n    args = parser.parse_args()\\n\\n    app.add_middleware(\\n        CORSMiddleware,\\n        allow_origins=args.allowed_origins,\\n        allow_credentials=args.allow_credentials,\\n        allow_methods=args.allowed_methods,\\n        allow_headers=args.allowed_headers,\\n    )\\n    app_settings.controller_address = args.controller_address\\n    app_settings.api_keys = args.api_keys\\n\\n    logger.info(f\\\"args: {args}\\\")\\n\\n    uvicorn.run(app, host=args.host, port=args.port, log_level=\\\"info\\\")\\n\"},{\"source_archive\":\"Unified_Psychiatric_AI_Brain_Part1.zip\",\"source_path\":\"source_projects/ChatPsychiatrist-master/ChatPsychiatrist-master/fastchat/serve/gateway/README.md\",\"language\":\"md\",\"content\":\"# fastchat Nginx Gateway\\n\\n## Purpose of the Gateway\\n\\nThe Nginx gateway serves the following purposes:\\n\\n1. Protects Gradio servers by acting as a firewall.\\n2. Facilitates dynamic mounting and unmounting of Gradio servers.\\n3. Provides load balancing for Gradio servers.\\n4. Offers additional security features, such as total connection limit.\\n5. Reduces attack surface by requiring only a single public port to be exposed for serving.\\n\\n## Deployment and Updating of the Gateway\\n\\n### Installing Nginx\\n\\nOn Debian-based distributions (e.g., Ubuntu):\\n\\n```bash\\nsudo apt update\\nsudo apt install nginx\\n```\\nOn Red Hat-based distributions (e.g., CentOS, Fedora):\\n\\n```bash\\nsudo yum install epel-release\\nsudo yum install nginx\\n```\\n\\n### Deployment\\n\\nCopy `nginx.conf` to `/etc/nginx/nginx.conf` (need sudo permission).\\n\\nReplace the port number 7860 in `server localhost:7860` with the port where you deploy the Gradio web server.\\n\\nModify `upstream websocket` to configure Gradio servers behind the gateway.\\n\\nLastly, update Nginx.\\n\\n\\n### HTTPS Deployment with a Public Domain URL\\n\\nMake sure you obtain the HTTPS certificate and the private key used to generate the certificate.\\n\\nFill the addresses to your certificate and private key in the `[PATH_TO_SSL_CERT]` and `[PATH_TO_PRIVATE_KEY]` fields.\\n\\nIf you have your own domain url to serve the chatbot, replace the chat.lmsys.org url with your own domain url.\\n\\n### Updating\\n\\nEvery time when `/etc/nginx/nginx.conf` is modified, you need to update the Nginx service:\\n\\n```bash\\nsudo nginx -t  # check `/etc/nginx/nginx.conf`\\nsudo systemctl reload nginx  # restart Nginx service to load the new config\\nsudo systemctl status nginx  # check the status of the Nginx service. It should be active (running).\\n```\\n\"},{\"source_archive\":\"Unified_Psychiatric_AI_Brain_Part1.zip\",\"source_path\":\"source_projects/ChatPsychiatrist-master/ChatPsychiatrist-master/fastchat/serve/gradio_web_server.py\",\"language\":\"py\",\"content\":\"\\\"\\\"\\\"\\nThe gradio demo server for chatting with a single model.\\n\\\"\\\"\\\"\\n\\nimport argparse\\nfrom collections import defaultdict\\nimport datetime\\nimport json\\nimport os\\nimport random\\nimport time\\nimport uuid\\n\\nimport gradio as gr\\nimport requests\\n\\nfrom fastchat.conversation import SeparatorStyle\\nfrom fastchat.constants import (\\n    LOGDIR,\\n    WORKER_API_TIMEOUT,\\n    ErrorCode,\\n    MODERATION_MSG,\\n    CONVERSATION_LIMIT_MSG,\\n    SERVER_ERROR_MSG,\\n    INACTIVE_MSG,\\n    INPUT_CHAR_LEN_LIMIT,\\n    CONVERSATION_TURN_LIMIT,\\n    SESSION_EXPIRATION_TIME,\\n)\\nfrom fastchat.model.model_adapter import get_conversation_template\\nfrom fastchat.model.model_registry import model_info\\nfrom fastchat.serve.api_provider import (\\n    anthropic_api_stream_iter,\\n    openai_api_stream_iter,\\n    palm_api_stream_iter,\\n    init_palm_chat,\\n)\\nfrom fastchat.utils import (\\n    build_logger,\\n    violates_moderation,\\n    get_window_url_params_js,\\n    parse_gradio_auth_creds,\\n)\\n\\n\\nlogger = build_logger(\\\"gradio_web_server\\\", \\\"gradio_web_server.log\\\")\\n\\nheaders = {\\\"User-Agent\\\": \\\"FastChat Client\\\"}\\n\\nno_change_btn = gr.Button.update()\\nenable_btn = gr.Button.update(interactive=True)\\ndisable_btn = gr.Button.update(interactive=False)\\n\\ncontroller_url = None\\nenable_moderation = False\\n\\nlearn_more_md = \\\"\\\"\\\"\\n### License\\nThe service is a research preview intended for non-commercial use only, subject to the model [License](https://github.com/facebookresearch/llama/blob/main/MODEL_CARD.md) of LLaMA, [Terms of Use](https://openai.com/policies/terms-of-use) of the data generated by OpenAI, and [Privacy Practices](https://chrome.google.com/webstore/detail/sharegpt-share-your-chatg/daiacboceoaocpibfodeljbdfacokfjb) of ShareGPT. Please contact us if you find any potential violation.\\n\\\"\\\"\\\"\\n\\nip_expiration_dict = defaultdict(lambda: 0)\\n\\n\\nclass State:\\n    def __init__(self, model_name):\\n        self.conv = get_conversation_template(model_name)\\n        self.conv_id = uuid.uuid4().hex\\n        self.skip_next = False\\n        self.model_name = model_name\\n\\n        if model_name == \\\"palm-2\\\":\\n            # According to release note, \\\"chat-bison@001\\\" is PaLM 2 for chat.\\n            # https://cloud.google.com/vertex-ai/docs/release-notes#May_10_2023\\n            self.palm_chat = init_palm_chat(\\\"chat-bison@001\\\")\\n\\n    def to_gradio_chatbot(self):\\n        return self.conv.to_gradio_chatbot()\\n\\n    def dict(self):\\n        base = self.conv.dict()\\n        base.update(\\n            {\\n                \\\"conv_id\\\": self.conv_id,\\n                \\\"model_name\\\": self.model_name,\\n            }\\n        )\\n        return base\\n\\n\\ndef set_global_vars(controller_url_, enable_moderation_):\\n    global controller_url, enable_moderation\\n    controller_url = controller_url_\\n    enable_moderation = enable_moderation_\\n\\n\\ndef get_conv_log_filename():\\n    t = datetime.datetime.now()\\n    name = os.path.join(LOGDIR, f\\\"{t.year}-{t.month:02d}-{t.day:02d}-conv.json\\\")\\n    return name\\n\\n\\ndef get_model_list(controller_url, add_chatgpt, add_claude, add_palm):\\n    ret = requests.post(controller_url + \\\"/refresh_all_workers\\\")\\n    assert ret.status_code == 200\\n    ret = requests.post(controller_url + \\\"/list_models\\\")\\n    models = ret.json()[\\\"models\\\"]\\n\\n    # Add API providers\\n    if add_chatgpt:\\n        models += [\\\"gpt-3.5-turbo\\\", \\\"gpt-4\\\"]\\n    if add_claude:\\n        models += [\\\"claude-2\\\", \\\"claude-instant-1\\\"]\\n    if add_palm:\\n        models += [\\\"palm-2\\\"]\\n\\n    priority = {k: f\\\"___{i:02d}\\\" for i, k in enumerate(model_info)}\\n    models.sort(key=lambda x: priority.get(x, x))\\n    logger.info(f\\\"Models: {models}\\\")\\n    return models\\n\\n\\ndef load_demo_single(models, url_params):\\n    selected_model = models[0] if len(models) > 0 else \\\"\\\"\\n    if \\\"model\\\" in url_params:\\n        model = url_params[\\\"model\\\"]\\n        if model in models:\\n            selected_model = model\\n\\n    dropdown_update = gr.Dropdown.update(\\n        choices=models, value=selected_model, visible=True\\n    )\\n\\n    state = None\\n    return (\\n        state,\\n        dropdown_update,\\n        gr.Chatbot.update(visible=True),\\n        gr.Textbox.update(visible=True),\\n        gr.Button.update(visible=True),\\n        gr.Row.update(visible=True),\\n        gr.Accordion.update(visible=True),\\n    )\\n\\n\\ndef load_demo(url_params, request: gr.Request):\\n    global models\\n\\n    ip = request.client.host\\n    logger.info(f\\\"load_demo. ip: {ip}. params: {url_params}\\\")\\n    ip_expiration_dict[ip] = time.time() + SESSION_EXPIRATION_TIME\\n\\n    if args.model_list_mode == \\\"reload\\\":\\n        models = get_model_list(\\n            controller_url, args.add_chatgpt, args.add_claude, args.add_palm\\n        )\\n\\n    return load_demo_single(models, url_params)\\n\\n\\ndef vote_last_response(state, vote_type, model_selector, request: gr.Request):\\n    with open(get_conv_log_filename(), \\\"a\\\") as fout:\\n        data = {\\n            \\\"tstamp\\\": round(time.time(), 4),\\n            \\\"type\\\": vote_type,\\n            \\\"model\\\": model_selector,\\n            \\\"state\\\": state.dict(),\\n            \\\"ip\\\": request.client.host,\\n        }\\n        fout.write(json.dumps(data) + \\\"\\\\n\\\")\\n\\n\\ndef upvote_last_response(state, model_selector, request: gr.Request):\\n    logger.info(f\\\"upvote. ip: {request.client.host}\\\")\\n    vote_last_response(state, \\\"upvote\\\", model_selector, request)\\n    return (\\\"\\\",) + (disable_btn,) * 3\\n\\n\\ndef downvote_last_response(state, model_selector, request: gr.Request):\\n    logger.info(f\\\"downvote. ip: {request.client.host}\\\")\\n    vote_last_response(state, \\\"downvote\\\", model_selector, request)\\n    return (\\\"\\\",) + (disable_btn,) * 3\\n\\n\\ndef flag_last_response(state, model_selector, request: gr.Request):\\n    logger.info(f\\\"flag. ip: {request.client.host}\\\")\\n    vote_last_response(state, \\\"flag\\\", model_selector, request)\\n    return (\\\"\\\",) + (disable_btn,) * 3\\n\\n\\ndef regenerate(state, request: gr.Request):\\n    logger.info(f\\\"regenerate. ip: {request.client.host}\\\")\\n    state.conv.update_last_message(None)\\n    return (state, state.to_gradio_chatbot(), \\\"\\\") + (disable_btn,) * 5\\n\\n\\ndef clear_history(request: gr.Request):\\n    logger.info(f\\\"clear_history. ip: {request.client.host}\\\")\\n    state = None\\n    return (state, [], \\\"\\\") + (disable_btn,) * 5\\n\\n\\ndef add_text(state, model_selector, text, request: gr.Request):\\n    ip = request.client.host\\n    logger.info(f\\\"add_text. ip: {ip}. len: {len(text)}\\\")\\n\\n    if state is None:\\n        state = State(model_selector)\\n\\n    if len(text) <= 0:\\n        state.skip_next = True\\n        return (state, state.to_gradio_chatbot(), \\\"\\\") + (no_change_btn,) * 5\\n\\n    # if ip_expiration_dict[ip] < time.time():\\n    #     logger.info(f\\\"inactive. ip: {request.client.host}. text: {text}\\\")\\n    #     state.skip_next = True\\n    #     return (state, state.to_gradio_chatbot(), INACTIVE_MSG) + (no_change_btn,) * 5\\n\\n    if enable_moderation:\\n        flagged = violates_moderation(text)\\n        if flagged:\\n            logger.info(f\\\"violate moderation. ip: {request.client.host}. text: {text}\\\")\\n            state.skip_next = True\\n            return (state, state.to_gradio_chatbot(), MODERATION_MSG) + (\\n                no_change_btn,\\n            ) * 5\\n\\n    conv = state.conv\\n    if (len(conv.messages) - conv.offset) // 2 >= CONVERSATION_TURN_LIMIT:\\n        logger.info(f\\\"conversation turn limit. ip: {request.client.host}. text: {text}\\\")\\n        state.skip_next = True\\n        return (state, state.to_gradio_chatbot(), CONVERSATION_LIMIT_MSG) + (\\n            no_change_btn,\\n        ) * 5\\n\\n    text = text[:INPUT_CHAR_LEN_LIMIT]  # Hard cut-off\\n    conv.append_message(conv.roles[0], text)\\n    conv.append_message(conv.roles[1], None)\\n    return (state, state.to_gradio_chatbot(), \\\"\\\") + (disable_btn,) * 5\\n\\n\\ndef post_process_code(code):\\n    sep = \\\"\\\\n```\\\"\\n    if sep in code:\\n        blocks = code.split(sep)\\n        if len(blocks) % 2 == 1:\\n            for i in range(1, len(blocks), 2):\\n                blocks[i] = blocks[i].replace(\\\"\\\\\\\\_\\\", \\\"_\\\")\\n        code = sep.join(blocks)\\n    return code\\n\\n\\ndef model_worker_stream_iter(\\n    conv,\\n    model_name,\\n    worker_addr,\\n    prompt,\\n    temperature,\\n    repetition_penalty,\\n    top_p,\\n    max_new_tokens,\\n):\\n    # Make requests\\n    gen_params = {\\n        \\\"model\\\": model_name,\\n        \\\"prompt\\\": prompt,\\n        \\\"temperature\\\": temperature,\\n        \\\"repetition_penalty\\\": repetition_penalty,\\n        \\\"top_p\\\": top_p,\\n        \\\"max_new_tokens\\\": max_new_tokens,\\n        \\\"stop\\\": conv.stop_str,\\n        \\\"stop_token_ids\\\": conv.stop_token_ids,\\n        \\\"echo\\\": False,\\n    }\\n    logger.info(f\\\"==== request ====\\\\n{gen_params}\\\")\\n\\n    # Stream output\\n    response = requests.post(\\n        worker_addr + \\\"/worker_generate_stream\\\",\\n        headers=headers,\\n        json=gen_params,\\n        stream=True,\\n        timeout=WORKER_API_TIMEOUT,\\n    )\\n    for chunk in response.iter_lines(decode_unicode=False, delimiter=b\\\"\\\\0\\\"):\\n        if chunk:\\n            data = json.loads(chunk.decode())\\n            yield data\\n\\n\\ndef bot_response(state, temperature, top_p, max_new_tokens, request: gr.Request):\\n    logger.info(f\\\"bot_response. ip: {request.client.host}\\\")\\n    start_tstamp = time.time()\\n    temperature = float(temperature)\\n    top_p = float(top_p)\\n    max_new_tokens = int(max_new_tokens)\\n\\n    if state.skip_next:\\n        # This generate call is skipped due to invalid inputs\\n        state.skip_next = False\\n        yield (state, state.to_gradio_chatbot()) + (no_change_btn,) * 5\\n        return\\n\\n    conv, model_name = state.conv, state.model_name\\n    if model_name == \\\"gpt-3.5-turbo\\\" or model_name == \\\"gpt-4\\\":\\n        prompt = conv.to_openai_api_messages()\\n        stream_iter = openai_api_stream_iter(\\n            model_name, prompt, temperature, top_p, max_new_tokens\\n        )\\n    elif model_name == \\\"claude-2\\\" or model_name == \\\"claude-instant-1\\\":\\n        prompt = conv.get_prompt()\\n        stream_iter = anthropic_api_stream_iter(\\n            model_name, prompt, temperature, top_p, max_new_tokens\\n        )\\n    elif model_name == \\\"palm-2\\\":\\n        stream_iter = palm_api_stream_iter(\\n            state.palm_chat, conv.messages[-2][1], temperature, top_p, max_new_tokens\\n        )\\n    else:\\n        # Query worker address\\n        ret = requests.post(\\n            controller_url + \\\"/get_worker_address\\\", json={\\\"model\\\": model_name}\\n        )\\n        worker_addr = ret.json()[\\\"address\\\"]\\n        logger.info(f\\\"model_name: {model_name}, worker_addr: {worker_addr}\\\")\\n\\n        # No available worker\\n        if worker_addr == \\\"\\\":\\n            conv.update_last_message(SERVER_ERROR_MSG)\\n            yield (\\n                state,\\n                state.to_gradio_chatbot(),\\n                disable_btn,\\n                disable_btn,\\n                disable_btn,\\n                enable_btn,\\n                enable_btn,\\n            )\\n            return\\n\\n        # Construct prompt.\\n        # We need to call it here, so it will not be affected by \\\"\u258c\\\".\\n        prompt = conv.get_prompt()\\n\\n        # Set repetition_penalty\\n        if \\\"t5\\\" in model_name:\\n            repetition_penalty = 1.2\\n        else:\\n            repetition_penalty = 1.0\\n\\n        stream_iter = model_worker_stream_iter(\\n            conv,\\n            model_name,\\n            worker_addr,\\n            prompt,\\n            temperature,\\n            repetition_penalty,\\n            top_p,\\n            max_new_tokens,\\n        )\\n\\n    conv.update_last_message(\\\"\u258c\\\")\\n    yield (state, state.to_gradio_chatbot()) + (disable_btn,) * 5\\n\\n    try:\\n        for data in stream_iter:\\n            if data[\\\"error_code\\\"] == 0:\\n                output = data[\\\"text\\\"].strip()\\n                if \\\"vicuna\\\" in model_name:\\n                    output = post_process_code(output)\\n                conv.update_last_message(output + \\\"\u258c\\\")\\n                yield (state, state.to_gradio_chatbot()) + (disable_btn,) * 5\\n            else:\\n                output = data[\\\"text\\\"] + f\\\"\\\\n\\\\n(error_code: {data['error_code']})\\\"\\n                conv.update_last_message(output)\\n                yield (state, state.to_gradio_chatbot()) + (\\n                    disable_btn,\\n                    disable_btn,\\n                    disable_btn,\\n                    enable_btn,\\n                    enable_btn,\\n                )\\n                return\\n            time.sleep(0.015)\\n    except requests.exceptions.RequestException as e:\\n        conv.update_last_message(\\n            f\\\"{SERVER_ERROR_MSG}\\\\n\\\\n\\\"\\n            f\\\"(error_code: {ErrorCode.GRADIO_REQUEST_ERROR}, {e})\\\"\\n        )\\n        yield (state, state.to_gradio_chatbot()) + (\\n            disable_btn,\\n            disable_btn,\\n            disable_btn,\\n            enable_btn,\\n            enable_btn,\\n        )\\n        return\\n    except Exception as e:\\n        conv.update_last_message(\\n            f\\\"{SERVER_ERROR_MSG}\\\\n\\\\n\\\"\\n            f\\\"(error_code: {ErrorCode.GRADIO_STREAM_UNKNOWN_ERROR}, {e})\\\"\\n        )\\n        yield (state, state.to_gradio_chatbot()) + (\\n            disable_btn,\\n            disable_btn,\\n            disable_btn,\\n            enable_btn,\\n            enable_btn,\\n        )\\n        return\\n\\n    # Delete \\\"\u258c\\\"\\n    conv.update_last_message(conv.messages[-1][-1][:-1])\\n    yield (state, state.to_gradio_chatbot()) + (enable_btn,) * 5\\n\\n    finish_tstamp = time.time()\\n    logger.info(f\\\"{output}\\\")\\n\\n    with open(get_conv_log_filename(), \\\"a\\\") as fout:\\n        data = {\\n            \\\"tstamp\\\": round(finish_tstamp, 4),\\n            \\\"type\\\": \\\"chat\\\",\\n            \\\"model\\\": model_name,\\n            \\\"gen_params\\\": {\\n                \\\"temperature\\\": temperature,\\n                \\\"top_p\\\": top_p,\\n                \\\"max_new_tokens\\\": max_new_tokens,\\n            },\\n            \\\"start\\\": round(start_tstamp, 4),\\n            \\\"finish\\\": round(finish_tstamp, 4),\\n            \\\"state\\\": state.dict(),\\n            \\\"ip\\\": request.client.host,\\n        }\\n        fout.write(json.dumps(data) + \\\"\\\\n\\\")\\n\\n\\nblock_css = \\\"\\\"\\\"\\n#notice_markdown {\\n    font-size: 104%\\n}\\n#notice_markdown th {\\n    display: none;\\n}\\n#notice_markdown td {\\n    padding-top: 6px;\\n    padding-bottom: 6px;\\n}\\n#leaderboard_markdown {\\n    font-size: 104%\\n}\\n#leaderboard_markdown td {\\n    padding-top: 6px;\\n    padding-bottom: 6px;\\n}\\n#leaderboard_dataframe td {\\n    line-height: 0.1em;\\n}\\n\\\"\\\"\\\"\\n\\n\\ndef get_model_description_md(models):\\n    model_description_md = \\\"\\\"\\\"\\n| | | |\\n| ---- | ---- | ---- |\\n\\\"\\\"\\\"\\n    ct = 0\\n    visited = set()\\n    for i, name in enumerate(models):\\n        if name in model_info:\\n            minfo = model_info[name]\\n            if minfo.simple_name in visited:\\n                continue\\n            visited.add(minfo.simple_name)\\n            one_model_md = f\\\"[{minfo.simple_name}]({minfo.link}): {minfo.description}\\\"\\n        else:\\n            visited.add(name)\\n            one_model_md = (\\n                f\\\"[{name}](): Add the description at fastchat/model/model_registry.py\\\"\\n            )\\n\\n        if ct % 3 == 0:\\n            model_description_md += \\\"|\\\"\\n        model_description_md += f\\\" {one_model_md} |\\\"\\n        if ct % 3 == 2:\\n            model_description_md += \\\"\\\\n\\\"\\n        ct += 1\\n    return model_description_md\\n\\n\\ndef build_single_model_ui(models, add_promotion_links=False):\\n    promotion = (\\n        \\\"\\\"\\\"\\n- Introducing Llama 2: The Next Generation Open Source Large Language Model. [[Website]](https://ai.meta.com/llama/)\\n- Vicuna: An Open-Source Chatbot Impressing GPT-4 with 90% ChatGPT Quality. [[Blog]](https://lmsys.org/blog/2023-03-30-vicuna/)\\n- | [GitHub](https://github.com/lm-sys/FastChat) | [Twitter](https://twitter.com/lmsysorg) | [Discord](https://discord.gg/HSWAKCrnFx) |\\n\\\"\\\"\\\"\\n        if add_promotion_links\\n        else \\\"\\\"\\n    )\\n\\n    notice_markdown = f\\\"\\\"\\\"\\n# \ud83c\udfd4\ufe0f Chat with Open Large Language Models\\n{promotion}\\n\\n### Terms of use\\nBy using this service, users are required to agree to the following terms: The service is a research preview intended for non-commercial use only. It only provides limited safety measures and may generate offensive content. It must not be used for any illegal, harmful, violent, racist, or sexual purposes. **The service collects user dialogue data and reserves the right to distribute it under a Creative Commons Attribution (CC-BY) license.**\\n\\n### Choose a model to chat with\\n\\\"\\\"\\\"\\n\\n    state = gr.State()\\n    model_description_md = get_model_description_md(models)\\n    gr.Markdown(notice_markdown + model_description_md, elem_id=\\\"notice_markdown\\\")\\n\\n    with gr.Row(elem_id=\\\"model_selector_row\\\"):\\n        model_selector = gr.Dropdown(\\n            choices=models,\\n            value=models[0] if len(models) > 0 else \\\"\\\",\\n            interactive=True,\\n            show_label=False,\\n            container=False,\\n        )\\n\\n    chatbot = gr.Chatbot(\\n        elem_id=\\\"chatbot\\\",\\n        label=\\\"Scroll down and start chatting\\\",\\n        visible=False,\\n        height=550,\\n    )\\n    with gr.Row():\\n        with gr.Column(scale=20):\\n            textbox = gr.Textbox(\\n                show_label=False,\\n                placeholder=\\\"Enter text and press ENTER\\\",\\n                visible=False,\\n                container=False,\\n            )\\n        with gr.Column(scale=1, min_width=50):\\n            send_btn = gr.Button(value=\\\"Send\\\", visible=False)\\n\\n    with gr.Row(visible=False) as button_row:\\n        upvote_btn = gr.Button(value=\\\"\ud83d\udc4d  Upvote\\\", interactive=False)\\n        downvote_btn = gr.Button(value=\\\"\ud83d\udc4e  Downvote\\\", interactive=False)\\n        flag_btn = gr.Button(value=\\\"\u26a0\ufe0f  Flag\\\", interactive=False)\\n        regenerate_btn = gr.Button(value=\\\"\ud83d\udd04  Regenerate\\\", interactive=False)\\n        clear_btn = gr.Button(value=\\\"\ud83d\uddd1\ufe0f  Clear history\\\", interactive=False)\\n\\n    with gr.Accordion(\\\"Parameters\\\", open=False, visible=False) as parameter_row:\\n        temperature = gr.Slider(\\n            minimum=0.0,\\n            maximum=1.0,\\n            value=0.7,\\n            step=0.1,\\n            interactive=True,\\n            label=\\\"Temperature\\\",\\n        )\\n        top_p = gr.Slider(\\n            minimum=0.0,\\n            maximum=1.0,\\n            value=1.0,\\n            step=0.1,\\n            interactive=True,\\n            label=\\\"Top P\\\",\\n        )\\n        max_output_tokens = gr.Slider(\\n            minimum=16,\\n            maximum=1024,\\n            value=512,\\n            step=64,\\n            interactive=True,\\n            label=\\\"Max output tokens\\\",\\n        )\\n\\n    gr.Markdown(learn_more_md)\\n\\n    # Register listeners\\n    btn_list = [upvote_btn, downvote_btn, flag_btn, regenerate_btn, clear_btn]\\n    upvote_btn.click(\\n        upvote_last_response,\\n        [state, model_selector],\\n        [textbox, upvote_btn, downvote_btn, flag_btn],\\n    )\\n    downvote_btn.click(\\n        downvote_last_response,\\n        [state, model_selector],\\n        [textbox, upvote_btn, downvote_btn, flag_btn],\\n    )\\n    flag_btn.click(\\n        flag_last_response,\\n        [state, model_selector],\\n        [textbox, upvote_btn, downvote_btn, flag_btn],\\n    )\\n    regenerate_btn.click(regenerate, state, [state, chatbot, textbox] + btn_list).then(\\n        bot_response,\\n        [state, temperature, top_p, max_output_tokens],\\n        [state, chatbot] + btn_list,\\n    )\\n    clear_btn.click(clear_history, None, [state, chatbot, textbox] + btn_list)\\n\\n    model_selector.change(clear_history, None, [state, chatbot, textbox] + btn_list)\\n\\n    textbox.submit(\\n        add_text, [state, model_selector, textbox], [state, chatbot, textbox] + btn_list\\n    ).then(\\n        bot_response,\\n        [state, temperature, top_p, max_output_tokens],\\n        [state, chatbot] + btn_list,\\n    )\\n    send_btn.click(\\n        add_text, [state, model_selector, textbox], [state, chatbot, textbox] + btn_list\\n    ).then(\\n        bot_response,\\n        [state, temperature, top_p, max_output_tokens],\\n        [state, chatbot] + btn_list,\\n    )\\n\\n    return state, model_selector, chatbot, textbox, send_btn, button_row, parameter_row\\n\\n\\ndef build_demo(models):\\n    with gr.Blocks(\\n        title=\\\"Chat with Open Large Language Models\\\",\\n        theme=gr.themes.Base(),\\n        css=block_css,\\n    ) as demo:\\n        url_params = gr.JSON(visible=False)\\n\\n        (\\n            state,\\n            model_selector,\\n            chatbot,\\n            textbox,\\n            send_btn,\\n            button_row,\\n            parameter_row,\\n        ) = build_single_model_ui(models)\\n\\n        if args.model_list_mode not in [\\\"once\\\", \\\"reload\\\"]:\\n            raise ValueError(f\\\"Unknown model list mode: {args.model_list_mode}\\\")\\n        demo.load(\\n            load_demo,\\n            [url_params],\\n            [\\n                state,\\n                model_selector,\\n                chatbot,\\n                textbox,\\n                send_btn,\\n                button_row,\\n                parameter_row,\\n            ],\\n            _js=get_window_url_params_js,\\n        )\\n\\n    return demo\\n\\n\\nif __name__ == \\\"__main__\\\":\\n    parser = argparse.ArgumentParser()\\n    parser.add_argument(\\\"--host\\\", type=str, default=\\\"0.0.0.0\\\")\\n    parser.add_argument(\\\"--port\\\", type=int)\\n    parser.add_argument(\\n        \\\"--share\\\",\\n        action=\\\"store_true\\\",\\n        help=\\\"Whether to generate a public, shareable link.\\\",\\n    )\\n    parser.add_argument(\\n        \\\"--controller-url\\\",\\n        type=str,\\n        default=\\\"http://localhost:21001\\\",\\n        help=\\\"The address of the controller.\\\",\\n    )\\n    parser.add_argument(\\n        \\\"--concurrency-count\\\",\\n        type=int,\\n        default=10,\\n        help=\\\"The concurrency count of the gradio queue.\\\",\\n    )\\n    parser.add_argument(\\n        \\\"--model-list-mode\\\",\\n        type=str,\\n        default=\\\"once\\\",\\n        choices=[\\\"once\\\", \\\"reload\\\"],\\n        help=\\\"Whether to load the model list once or reload the model list every time.\\\",\\n    )\\n    parser.add_argument(\\n        \\\"--moderate\\\", action=\\\"store_true\\\", help=\\\"Enable content moderation\\\"\\n    )\\n    parser.add_argument(\\n        \\\"--add-chatgpt\\\",\\n        action=\\\"store_true\\\",\\n        help=\\\"Add OpenAI's ChatGPT models (gpt-3.5-turbo, gpt-4)\\\",\\n    )\\n    parser.add_argument(\\n        \\\"--add-claude\\\",\\n        action=\\\"store_true\\\",\\n        help=\\\"Add Anthropic's Claude models (claude-2, claude-instant-1)\\\",\\n    )\\n    parser.add_argument(\\n        \\\"--add-palm\\\",\\n        action=\\\"store_true\\\",\\n        help=\\\"Add Google's PaLM model (PaLM 2 for Chat: chat-bison@001)\\\",\\n    )\\n    parser.add_argument(\\n        \\\"--gradio-auth-path\\\",\\n        type=str,\\n        help='Set the gradio authentication file path. The file should contain one or more user:password pairs in this format: \\\"u1:p1,u2:p2,u3:p3\\\"',\\n        default=None,\\n    )\\n    args = parser.parse_args()\\n    logger.info(f\\\"args: {args}\\\")\\n\\n    # Set global variables\\n    set_global_vars(args.controller_url, args.moderate)\\n    models = get_model_list(\\n        args.controller_url, args.add_chatgpt, args.add_claude, args.add_palm\\n    )\\n\\n    # Set authorization credentials\\n    auth = None\\n    if args.gradio_auth_path is not None:\\n        auth = parse_gradio_auth_creds(args.gradio_auth_path)\\n\\n    # Launch the demo\\n    demo = build_demo(models)\\n    demo.queue(\\n        concurrency_count=args.concurrency_count, status_update_rate=10, api_open=False\\n    ).launch(\\n        server_name=args.host,\\n        server_port=args.port,\\n        share=args.share,\\n        max_threads=200,\\n        auth=auth,\\n    )\\n\"},{\"source_archive\":\"Unified_Psychiatric_AI_Brain_Part1.zip\",\"source_path\":\"source_projects/ChatPsychiatrist-master/ChatPsychiatrist-master/fastchat/serve/gradio_block_arena_anony.py\",\"language\":\"py\",\"content\":\"\\\"\\\"\\\"\\nChatbot Arena (battle) tab.\\nUsers chat with two anonymous models.\\n\\\"\\\"\\\"\\n\\nimport json\\nimport time\\n\\nimport gradio as gr\\nimport numpy as np\\n\\nfrom fastchat.constants import (\\n    MODERATION_MSG,\\n    CONVERSATION_LIMIT_MSG,\\n    INACTIVE_MSG,\\n    INPUT_CHAR_LEN_LIMIT,\\n    CONVERSATION_TURN_LIMIT,\\n)\\nfrom fastchat.model.model_adapter import get_conversation_template\\nfrom fastchat.serve.gradio_block_arena_named import flash_buttons\\nfrom fastchat.serve.gradio_web_server import (\\n    State,\\n    bot_response,\\n    get_conv_log_filename,\\n    no_change_btn,\\n    enable_btn,\\n    disable_btn,\\n    learn_more_md,\\n    ip_expiration_dict,\\n)\\nfrom fastchat.utils import (\\n    build_logger,\\n    violates_moderation,\\n)\\n\\nlogger = build_logger(\\\"gradio_web_server_multi\\\", \\\"gradio_web_server_multi.log\\\")\\n\\nnum_sides = 2\\nenable_moderation = False\\nanony_names = [\\\"\\\", \\\"\\\"]\\nmodels = []\\n\\n\\ndef set_global_vars_anony(enable_moderation_):\\n    global enable_moderation\\n    enable_moderation = enable_moderation_\\n\\n\\ndef load_demo_side_by_side_anony(models_, url_params):\\n    global models\\n    models = models_\\n\\n    states = (None,) * num_sides\\n    selector_updates = (\\n        gr.Markdown.update(visible=True),\\n        gr.Markdown.update(visible=True),\\n    )\\n\\n    return (\\n        states\\n        + selector_updates\\n        + (gr.Chatbot.update(visible=True),) * num_sides\\n        + (\\n            gr.Textbox.update(visible=True),\\n            gr.Box.update(visible=True),\\n            gr.Row.update(visible=True),\\n            gr.Row.update(visible=True),\\n            gr.Accordion.update(visible=True),\\n        )\\n    )\\n\\n\\ndef vote_last_response(states, vote_type, model_selectors, request: gr.Request):\\n    with open(get_conv_log_filename(), \\\"a\\\") as fout:\\n        data = {\\n            \\\"tstamp\\\": round(time.time(), 4),\\n            \\\"type\\\": vote_type,\\n            \\\"models\\\": [x for x in model_selectors],\\n            \\\"states\\\": [x.dict() for x in states],\\n            \\\"ip\\\": request.client.host,\\n        }\\n        fout.write(json.dumps(data) + \\\"\\\\n\\\")\\n\\n    if \\\":\\\" not in model_selectors[0]:\\n        for i in range(15):\\n            names = (\\n                \\\"### Model A: \\\" + states[0].model_name,\\n                \\\"### Model B: \\\" + states[1].model_name,\\n            )\\n            yield names + (\\\"\\\",) + (disable_btn,) * 4\\n            time.sleep(0.2)\\n    else:\\n        names = (\\n            \\\"### Model A: \\\" + states[0].model_name,\\n            \\\"### Model B: \\\" + states[1].model_name,\\n        )\\n        yield names + (\\\"\\\",) + (disable_btn,) * 4\\n\\n\\ndef leftvote_last_response(\\n    state0, state1, model_selector0, model_selector1, request: gr.Request\\n):\\n    logger.info(f\\\"leftvote (anony). ip: {request.client.host}\\\")\\n    for x in vote_last_response(\\n        [state0, state1], \\\"leftvote\\\", [model_selector0, model_selector1], request\\n    ):\\n        yield x\\n\\n\\ndef rightvote_last_response(\\n    state0, state1, model_selector0, model_selector1, request: gr.Request\\n):\\n    logger.info(f\\\"rightvote (anony). ip: {request.client.host}\\\")\\n    for x in vote_last_response(\\n        [state0, state1], \\\"rightvote\\\", [model_selector0, model_selector1], request\\n    ):\\n        yield x\\n\\n\\ndef tievote_last_response(\\n    state0, state1, model_selector0, model_selector1, request: gr.Request\\n):\\n    logger.info(f\\\"tievote (anony). ip: {request.client.host}\\\")\\n    for x in vote_last_response(\\n        [state0, state1], \\\"tievote\\\", [model_selector0, model_selector1], request\\n    ):\\n        yield x\\n\\n\\ndef bothbad_vote_last_response(\\n    state0, state1, model_selector0, model_selector1, request: gr.Request\\n):\\n    logger.info(f\\\"bothbad_vote (anony). ip: {request.client.host}\\\")\\n    for x in vote_last_response(\\n        [state0, state1], \\\"bothbad_vote\\\", [model_selector0, model_selector1], request\\n    ):\\n        yield x\\n\\n\\ndef regenerate(state0, state1, request: gr.Request):\\n    logger.info(f\\\"regenerate (anony). ip: {request.client.host}\\\")\\n    states = [state0, state1]\\n    for i in range(num_sides):\\n        states[i].conv.update_last_message(None)\\n    return states + [x.to_gradio_chatbot() for x in states] + [\\\"\\\"] + [disable_btn] * 6\\n\\n\\ndef clear_history(request: gr.Request):\\n    logger.info(f\\\"clear_history (anony). ip: {request.client.host}\\\")\\n    return (\\n        [None] * num_sides + [None] * num_sides + anony_names + [\\\"\\\"] + [disable_btn] * 6\\n    )\\n\\n\\ndef share_click(state0, state1, model_selector0, model_selector1, request: gr.Request):\\n    logger.info(f\\\"share (anony). ip: {request.client.host}\\\")\\n    if state0 is not None and state1 is not None:\\n        vote_last_response(\\n            [state0, state1], \\\"share\\\", [model_selector0, model_selector1], request\\n        )\\n\\n\\nSAMPLING_WEIGHTS = {\\n    # tier 0\\n    \\\"gpt-4\\\": 1.5,\\n    \\\"gpt-3.5-turbo\\\": 1.5,\\n    \\\"claude-2\\\": 1.5,\\n    \\\"claude-instant-1\\\": 1.5,\\n    \\\"llama-2-13b-chat\\\": 1.5,\\n    \\\"vicuna-33b\\\": 1.5,\\n    \\\"vicuna-13b\\\": 1.5,\\n    \\\"mpt-30b-chat\\\": 1.5,\\n    # tier 1\\n    \\\"palm-2\\\": 1.0,\\n    \\\"wizardlm-13b\\\": 1.0,\\n    \\\"guanaco-33b\\\": 1.0,\\n    \\\"vicuna-7b\\\": 1.0,\\n    \\\"llama-2-7b-chat\\\": 1.0,\\n    # tier 2\\n    \\\"mpt-7b-chat\\\": 0.5,\\n    \\\"oasst-pythia-12b\\\": 0.5,\\n    \\\"RWKV-4-Raven-14B\\\": 0.5,\\n    \\\"fastchat-t5-3b\\\": 0.5,\\n    \\\"alpaca-13b\\\": 0.5,\\n    \\\"chatglm-6b\\\": 0.5,\\n    # deprecated\\n    \\\"gpt4all-13b-snoozy\\\": 1.0,\\n    \\\"koala-13b\\\": 1.0,\\n    \\\"stablelm-tuned-alpha-7b\\\": 0.1,\\n    \\\"dolly-v2-12b\\\": 0.1,\\n    \\\"llama-13b\\\": 0.1,\\n}\\n\\nSAMPLING_BOOST_MODELS = [\\\"llama-2-13b-chat\\\", \\\"llama-2-7b-chat\\\", \\\"claude-2\\\"]\\n\\nmodel_pairs = []\\nmodel_pairs_weights = []\\n\\n\\ndef add_text(\\n    state0, state1, model_selector0, model_selector1, text, request: gr.Request\\n):\\n    ip = request.client.host\\n    logger.info(f\\\"add_text (anony). ip: {ip}. len: {len(text)}\\\")\\n    states = [state0, state1]\\n    model_selectors = [model_selector0, model_selector1]\\n\\n    # Init states if necessary\\n    if states[0] is None:\\n        assert states[1] is None\\n        global model_pairs, model_pairs_weights\\n\\n        # Pick two models\\n        if len(model_pairs) == 0:\\n            for i in range(len(models)):\\n                for j in range(len(models)):\\n                    if i == j:\\n                        continue\\n                    a = models[i]\\n                    b = models[j]\\n                    w = SAMPLING_WEIGHTS.get(a, 1.0) * SAMPLING_WEIGHTS.get(b, 1.0)\\n                    if a in SAMPLING_BOOST_MODELS or b in SAMPLING_BOOST_MODELS:\\n                        w *= 10\\n                    model_pairs.append((a, b))\\n                    model_pairs_weights.append(w)\\n\\n            model_pairs_weights = model_pairs_weights / np.sum(model_pairs_weights)\\n            # for p, w in zip(model_pairs, model_pairs_weights):\\n            #    print(p, w)\\n\\n        if len(model_pairs) >= 1:\\n            idx = np.random.choice(len(model_pairs), p=model_pairs_weights)\\n            model_left, model_right = model_pairs[idx]\\n        else:\\n            model_left = model_right = models[0]\\n\\n        states = [\\n            State(model_left),\\n            State(model_right),\\n        ]\\n\\n    if len(text) <= 0:\\n        for i in range(num_sides):\\n            states[i].skip_next = True\\n        return (\\n            states\\n            + [x.to_gradio_chatbot() for x in states]\\n            + [\\\"\\\"]\\n            + [\\n                no_change_btn,\\n            ]\\n            * 6\\n        )\\n\\n    if ip_expiration_dict[ip] < time.time():\\n        logger.info(f\\\"inactive (anony). ip: {request.client.host}. text: {text}\\\")\\n        for i in range(num_sides):\\n            states[i].skip_next = True\\n        return (\\n            states\\n            + [x.to_gradio_chatbot() for x in states]\\n            + [INACTIVE_MSG]\\n            + [\\n                no_change_btn,\\n            ]\\n            * 6\\n        )\\n\\n    if enable_moderation:\\n        flagged = violates_moderation(text)\\n        if flagged:\\n            logger.info(\\n                f\\\"violate moderation (anony). ip: {request.client.host}. text: {text}\\\"\\n            )\\n            for i in range(num_sides):\\n                states[i].skip_next = True\\n            return (\\n                states\\n                + [x.to_gradio_chatbot() for x in states]\\n                + [MODERATION_MSG]\\n                + [\\n                    no_change_btn,\\n                ]\\n                * 6\\n            )\\n\\n    conv = states[0].conv\\n    if (len(conv.messages) - conv.offset) // 2 >= CONVERSATION_TURN_LIMIT:\\n        logger.info(f\\\"conversation turn limit. ip: {request.client.host}. text: {text}\\\")\\n        for i in range(num_sides):\\n            states[i].skip_next = True\\n        return (\\n            states\\n            + [x.to_gradio_chatbot() for x in states]\\n            + [CONVERSATION_LIMIT_MSG]\\n            + [\\n                no_change_btn,\\n            ]\\n            * 6\\n        )\\n\\n    text = text[:INPUT_CHAR_LEN_LIMIT]  # Hard cut-off\\n    for i in range(num_sides):\\n        states[i].conv.append_message(states[i].conv.roles[0], text)\\n        states[i].conv.append_message(states[i].conv.roles[1], None)\\n        states[i].skip_next = False\\n\\n    return (\\n        states\\n        + [x.to_gradio_chatbot() for x in states]\\n        + [\\\"\\\"]\\n        + [\\n            disable_btn,\\n        ]\\n        * 6\\n    )\\n\\n\\ndef bot_response_multi(\\n    state0,\\n    state1,\\n    temperature,\\n    top_p,\\n    max_new_tokens,\\n    request: gr.Request,\\n):\\n    logger.info(f\\\"bot_response_multi (anony). ip: {request.client.host}\\\")\\n\\n    if state0.skip_next:\\n        # This generate call is skipped due to invalid inputs\\n        yield (\\n            state0,\\n            state1,\\n            state0.to_gradio_chatbot(),\\n            state1.to_gradio_chatbot(),\\n        ) + (no_change_btn,) * 6\\n        return\\n\\n    states = [state0, state1]\\n    gen = []\\n    for i in range(num_sides):\\n        gen.append(\\n            bot_response(\\n                states[i],\\n                temperature,\\n                top_p,\\n                max_new_tokens,\\n                request,\\n            )\\n        )\\n\\n    chatbots = [None] * num_sides\\n    while True:\\n        stop = True\\n        for i in range(num_sides):\\n            try:\\n                ret = next(gen[i])\\n                states[i], chatbots[i] = ret[0], ret[1]\\n                stop = False\\n            except StopIteration:\\n                pass\\n        yield states + chatbots + [disable_btn] * 6\\n        if stop:\\n            break\\n\\n\\ndef build_side_by_side_ui_anony(models):\\n    notice_markdown = \\\"\\\"\\\"\\n# \u2694\ufe0f  Chatbot Arena \u2694\ufe0f \\n### Rules\\n- Chat with two anonymous models side-by-side and vote for which one is better!\\n- You can do multiple rounds of conversations before voting.\\n- The names of the models will be revealed after your vote. Conversations with identity keywords (e.g., ChatGPT, Bard, Vicuna) or any votes after the names are revealed will not count towards the leaderboard.\\n- Click \\\"Clear history\\\" to start a new round.\\n- | [Blog](https://lmsys.org/blog/2023-05-03-arena/) | [GitHub](https://github.com/lm-sys/FastChat) | [Paper](https://arxiv.org/abs/2306.05685) | [Twitter](https://twitter.com/lmsysorg) | [Discord](https://discord.gg/HSWAKCrnFx) |\\n\\n### Terms of use\\nBy using this service, users are required to agree to the following terms: The service is a research preview intended for non-commercial use only. It only provides limited safety measures and may generate offensive content. It must not be used for any illegal, harmful, violent, racist, or sexual purposes. **The service collects user dialogue data and reserves the right to distribute it under a Creative Commons Attribution (CC-BY) license.** The demo works better on desktop devices with a wide screen.\\n\\n### Battle\\nPlease scroll down and start chatting. You can view a leaderboard of participating models in the fourth tab above labeled 'Leaderboard' or by clicking [here](?leaderboard). The models include both closed-source models (e.g., ChatGPT) and open-source models (e.g., Vicuna).\\n\\\"\\\"\\\"\\n\\n    states = [gr.State() for _ in range(num_sides)]\\n    model_selectors = [None] * num_sides\\n    chatbots = [None] * num_sides\\n\\n    gr.Markdown(notice_markdown, elem_id=\\\"notice_markdown\\\")\\n\\n    with gr.Box(elem_id=\\\"share-region-anony\\\"):\\n        with gr.Row():\\n            for i in range(num_sides):\\n                with gr.Column():\\n                    model_selectors[i] = gr.Markdown(anony_names[i])\\n\\n        with gr.Row():\\n            for i in range(num_sides):\\n                label = \\\"Model A\\\" if i == 0 else \\\"Model B\\\"\\n                with gr.Column():\\n                    chatbots[i] = gr.Chatbot(\\n                        label=label, elem_id=f\\\"chatbot\\\", visible=False, height=550\\n                    )\\n\\n        with gr.Box() as button_row:\\n            with gr.Row():\\n                leftvote_btn = gr.Button(value=\\\"\ud83d\udc48  A is better\\\", interactive=False)\\n                rightvote_btn = gr.Button(value=\\\"\ud83d\udc49  B is better\\\", interactive=False)\\n                tie_btn = gr.Button(value=\\\"\ud83e\udd1d  Tie\\\", interactive=False)\\n                bothbad_btn = gr.Button(value=\\\"\ud83d\udc4e  Both are bad\\\", interactive=False)\\n\\n    with gr.Row():\\n        with gr.Column(scale=20):\\n            textbox = gr.Textbox(\\n                show_label=False,\\n                placeholder=\\\"Enter text and press ENTER\\\",\\n                visible=False,\\n                container=False,\\n            )\\n        with gr.Column(scale=1, min_width=50):\\n            send_btn = gr.Button(value=\\\"Send\\\", visible=False)\\n\\n    with gr.Row() as button_row2:\\n        regenerate_btn = gr.Button(value=\\\"\ud83d\udd04  Regenerate\\\", interactive=False)\\n        clear_btn = gr.Button(value=\\\"\ud83d\uddd1\ufe0f  Clear history\\\", interactive=False)\\n        share_btn = gr.Button(value=\\\"\ud83d\udcf7  Share\\\")\\n\\n    with gr.Accordion(\\\"Parameters\\\", open=False, visible=True) as parameter_row:\\n        temperature = gr.Slider(\\n            minimum=0.0,\\n            maximum=1.0,\\n            value=0.7,\\n            step=0.1,\\n            interactive=True,\\n            label=\\\"Temperature\\\",\\n        )\\n        top_p = gr.Slider(\\n            minimum=0.0,\\n            maximum=1.0,\\n            value=1.0,\\n            step=0.1,\\n            interactive=True,\\n            label=\\\"Top P\\\",\\n        )\\n        max_output_tokens = gr.Slider(\\n            minimum=16,\\n            maximum=1024,\\n            value=512,\\n            step=64,\\n            interactive=True,\\n            label=\\\"Max output tokens\\\",\\n        )\\n\\n    gr.Markdown(learn_more_md)\\n\\n    # Register listeners\\n    btn_list = [\\n        leftvote_btn,\\n        rightvote_btn,\\n        tie_btn,\\n        bothbad_btn,\\n        regenerate_btn,\\n        clear_btn,\\n    ]\\n    leftvote_btn.click(\\n        leftvote_last_response,\\n        states + model_selectors,\\n        model_selectors + [textbox, leftvote_btn, rightvote_btn, tie_btn, bothbad_btn],\\n    )\\n    rightvote_btn.click(\\n        rightvote_last_response,\\n        states + model_selectors,\\n        model_selectors + [textbox, leftvote_btn, rightvote_btn, tie_btn, bothbad_btn],\\n    )\\n    tie_btn.click(\\n        tievote_last_response,\\n        states + model_selectors,\\n        model_selectors + [textbox, leftvote_btn, rightvote_btn, tie_btn, bothbad_btn],\\n    )\\n    bothbad_btn.click(\\n        bothbad_vote_last_response,\\n        states + model_selectors,\\n        model_selectors + [textbox, leftvote_btn, rightvote_btn, tie_btn, bothbad_btn],\\n    )\\n    regenerate_btn.click(\\n        regenerate, states, states + chatbots + [textbox] + btn_list\\n    ).then(\\n        bot_response_multi,\\n        states + [temperature, top_p, max_output_tokens],\\n        states + chatbots + btn_list,\\n    ).then(\\n        flash_buttons, [], btn_list\\n    )\\n    clear_btn.click(\\n        clear_history, None, states + chatbots + model_selectors + [textbox] + btn_list\\n    )\\n\\n    share_js = \\\"\\\"\\\"\\nfunction (a, b, c, d) {\\n    const captureElement = document.querySelector('#share-region-anony');\\n    html2canvas(captureElement)\\n        .then(canvas => {\\n            canvas.style.display = 'none'\\n            document.body.appendChild(canvas)\\n            return canvas\\n        })\\n        .then(canvas => {\\n            const image = canvas.toDataURL('image/png')\\n            const a = document.createElement('a')\\n            a.setAttribute('download', 'chatbot-arena.png')\\n            a.setAttribute('href', image)\\n            a.click()\\n            canvas.remove()\\n        });\\n    return [a, b, c, d];\\n}\\n\\\"\\\"\\\"\\n    share_btn.click(share_click, states + model_selectors, [], _js=share_js)\\n\\n    textbox.submit(\\n        add_text,\\n        states + model_selectors + [textbox],\\n        states + chatbots + [textbox] + btn_list,\\n    ).then(\\n        bot_response_multi,\\n        states + [temperature, top_p, max_output_tokens],\\n        states + chatbots + btn_list,\\n    ).then(\\n        flash_buttons, [], btn_list\\n    )\\n\\n    send_btn.click(\\n        add_text,\\n        states + model_selectors + [textbox],\\n        states + chatbots + [textbox] + btn_list,\\n    ).then(\\n        bot_response_multi,\\n        states + [temperature, top_p, max_output_tokens],\\n        states + chatbots + btn_list,\\n    ).then(\\n        flash_buttons, [], btn_list\\n    )\\n\\n    return (\\n        states,\\n        model_selectors,\\n        chatbots,\\n        textbox,\\n        send_btn,\\n        button_row,\\n        button_row2,\\n        parameter_row,\\n    )\\n\"},{\"source_archive\":\"Unified_Psychiatric_AI_Brain_Part1.zip\",\"source_path\":\"source_projects/ChatPsychiatrist-master/ChatPsychiatrist-master/fastchat/serve/model_worker.py\",\"language\":\"py\",\"content\":\"\\\"\\\"\\\"\\nA model worker that executes the model.\\n\\\"\\\"\\\"\\nimport argparse\\nimport asyncio\\nimport dataclasses\\nimport logging\\nimport json\\nimport os\\nimport time\\nfrom typing import List\\nimport threading\\nimport uuid\\n\\nfrom fastapi import FastAPI, Request, BackgroundTasks\\nfrom fastapi.responses import StreamingResponse, JSONResponse\\nimport requests\\n\\ntry:\\n    from transformers import (\\n        AutoTokenizer,\\n        AutoModelForCausalLM,\\n        LlamaTokenizer,\\n        AutoModel,\\n    )\\nexcept ImportError:\\n    from transformers import (\\n        AutoTokenizer,\\n        AutoModelForCausalLM,\\n        LLaMATokenizer,\\n        AutoModel,\\n    )\\nimport torch\\nimport torch.nn.functional as F\\nimport uvicorn\\n\\nfrom fastchat.constants import WORKER_HEART_BEAT_INTERVAL, ErrorCode, SERVER_ERROR_MSG\\nfrom fastchat.conversation import get_conv_template\\nfrom fastchat.model.model_adapter import (\\n    load_model,\\n    add_model_args,\\n    get_conversation_template,\\n    get_generate_stream_function,\\n)\\nfrom fastchat.modules.gptq import GptqConfig\\nfrom fastchat.utils import build_logger, pretty_print_semaphore, get_context_length\\n\\n\\nworker_id = str(uuid.uuid4())[:8]\\nlogger = build_logger(\\\"model_worker\\\", f\\\"model_worker_{worker_id}.log\\\")\\n\\napp = FastAPI()\\n\\n\\ndef heart_beat_worker(obj):\\n    while True:\\n        time.sleep(WORKER_HEART_BEAT_INTERVAL)\\n        obj.send_heart_beat()\\n\\n\\nclass BaseModelWorker:\\n    def __init__(\\n        self,\\n        controller_addr: str,\\n        worker_addr: str,\\n        worker_id: str,\\n        model_path: str,\\n        model_names: List[str],\\n        limit_worker_concurrency: int,\\n        conv_template: str = None,\\n    ):\\n        self.controller_addr = controller_addr\\n        self.worker_addr = worker_addr\\n        self.worker_id = worker_id\\n        if model_path.endswith(\\\"/\\\"):\\n            model_path = model_path[:-1]\\n        self.model_names = model_names or [model_path.split(\\\"/\\\")[-1]]\\n        self.limit_worker_concurrency = limit_worker_concurrency\\n        if conv_template:\\n            self.conv = get_conv_template(conv_template)\\n        else:\\n            self.conv = get_conversation_template(model_path)\\n        self.conv.sep_style = int(self.conv.sep_style)\\n        self.tokenizer = None\\n        self.context_len = None\\n        self.call_ct = 0\\n        self.semaphore = None\\n\\n        self.heart_beat_thread = None\\n\\n    def init_heart_beat(self):\\n        self.register_to_controller()\\n        self.heart_beat_thread = threading.Thread(\\n            target=heart_beat_worker, args=(self,)\\n        )\\n        self.heart_beat_thread.start()\\n\\n    def register_to_controller(self):\\n        logger.info(\\\"Register to controller\\\")\\n\\n        url = self.controller_addr + \\\"/register_worker\\\"\\n        data = {\\n            \\\"worker_name\\\": self.worker_addr,\\n            \\\"check_heart_beat\\\": True,\\n            \\\"worker_status\\\": self.get_status(),\\n        }\\n        r = requests.post(url, json=data)\\n        assert r.status_code == 200\\n\\n    def send_heart_beat(self):\\n        logger.info(\\n            f\\\"Send heart beat. Models: {self.model_names}. \\\"\\n            f\\\"Semaphore: {pretty_print_semaphore(self.semaphore)}. \\\"\\n            f\\\"call_ct: {self.call_ct}. \\\"\\n            f\\\"worker_id: {self.worker_id}. \\\"\\n        )\\n\\n        url = self.controller_addr + \\\"/receive_heart_beat\\\"\\n\\n        while True:\\n            try:\\n                ret = requests.post(\\n                    url,\\n                    json={\\n                        \\\"worker_name\\\": self.worker_addr,\\n                        \\\"queue_length\\\": self.get_queue_length(),\\n                    },\\n                    timeout=5,\\n                )\\n                exist = ret.json()[\\\"exist\\\"]\\n                break\\n            except requests.exceptions.RequestException as e:\\n                logger.error(f\\\"heart beat error: {e}\\\")\\n            time.sleep(5)\\n\\n        if not exist:\\n            self.register_to_controller()\\n\\n    def get_queue_length(self):\\n        if (\\n            self.semaphore is None\\n            or self.semaphore._value is None\\n            or self.semaphore._waiters is None\\n        ):\\n            return 0\\n        else:\\n            return (\\n                self.limit_worker_concurrency\\n                - self.semaphore._value\\n                + len(self.semaphore._waiters)\\n            )\\n\\n    def get_status(self):\\n        return {\\n            \\\"model_names\\\": self.model_names,\\n            \\\"speed\\\": 1,\\n            \\\"queue_length\\\": self.get_queue_length(),\\n        }\\n\\n    def count_token(self, params):\\n        prompt = params[\\\"prompt\\\"]\\n        input_ids = self.tokenizer(prompt).input_ids\\n        input_echo_len = len(input_ids)\\n\\n        ret = {\\n            \\\"count\\\": input_echo_len,\\n            \\\"error_code\\\": 0,\\n        }\\n        return ret\\n\\n    def get_conv_template(self):\\n        return {\\\"conv\\\": self.conv}\\n\\n\\nclass ModelWorker(BaseModelWorker):\\n    def __init__(\\n        self,\\n        controller_addr: str,\\n        worker_addr: str,\\n        worker_id: str,\\n        model_path: str,\\n        model_names: List[str],\\n        limit_worker_concurrency: int,\\n        no_register: bool,\\n        device: str,\\n        num_gpus: int,\\n        max_gpu_memory: str,\\n        load_8bit: bool = False,\\n        cpu_offloading: bool = False,\\n        gptq_config: bool = None,\\n        stream_interval: int = 2,\\n        conv_template: str = None,\\n    ):\\n        super().__init__(\\n            controller_addr,\\n            worker_addr,\\n            worker_id,\\n            model_path,\\n            model_names,\\n            limit_worker_concurrency,\\n            conv_template=conv_template,\\n        )\\n\\n        logger.info(f\\\"Loading the model {self.model_names} on worker {worker_id} ...\\\")\\n        self.model, self.tokenizer = load_model(\\n            model_path,\\n            device,\\n            num_gpus,\\n            max_gpu_memory,\\n            load_8bit,\\n            cpu_offloading,\\n            gptq_config,\\n        )\\n        self.device = device\\n        if self.tokenizer.pad_token == None:\\n            self.tokenizer.pad_token = self.tokenizer.eos_token\\n        self.context_len = get_context_length(self.model.config)\\n        self.generate_stream_func = get_generate_stream_function(self.model, model_path)\\n        self.stream_interval = stream_interval\\n\\n        if not no_register:\\n            self.init_heart_beat()\\n\\n    def generate_stream_gate(self, params):\\n        self.call_ct += 1\\n\\n        try:\\n            for output in self.generate_stream_func(\\n                self.model,\\n                self.tokenizer,\\n                params,\\n                self.device,\\n                self.context_len,\\n                self.stream_interval,\\n            ):\\n                ret = {\\n                    \\\"text\\\": output[\\\"text\\\"],\\n                    \\\"error_code\\\": 0,\\n                }\\n                if \\\"usage\\\" in output:\\n                    ret[\\\"usage\\\"] = output[\\\"usage\\\"]\\n                if \\\"finish_reason\\\" in output:\\n                    ret[\\\"finish_reason\\\"] = output[\\\"finish_reason\\\"]\\n                if \\\"logprobs\\\" in output:\\n                    ret[\\\"logprobs\\\"] = output[\\\"logprobs\\\"]\\n                yield json.dumps(ret).encode() + b\\\"\\\\0\\\"\\n        except torch.cuda.OutOfMemoryError as e:\\n            ret = {\\n                \\\"text\\\": f\\\"{SERVER_ERROR_MSG}\\\\n\\\\n({e})\\\",\\n                \\\"error_code\\\": ErrorCode.CUDA_OUT_OF_MEMORY,\\n            }\\n            yield json.dumps(ret).encode() + b\\\"\\\\0\\\"\\n        except (ValueError, RuntimeError) as e:\\n            ret = {\\n                \\\"text\\\": f\\\"{SERVER_ERROR_MSG}\\\\n\\\\n({e})\\\",\\n                \\\"error_code\\\": ErrorCode.INTERNAL_ERROR,\\n            }\\n            yield json.dumps(ret).encode() + b\\\"\\\\0\\\"\\n\\n    def generate_gate(self, params):\\n        for x in self.generate_stream_gate(params):\\n            pass\\n        return json.loads(x[:-1].decode())\\n\\n    @torch.inference_mode()\\n    def get_embeddings(self, params):\\n        self.call_ct += 1\\n\\n        try:\\n            tokenizer = self.tokenizer\\n            is_llama = \\\"llama\\\" in str(\\n                type(self.model)\\n            )  # llama supports batch inference\\n            is_chatglm = \\\"chatglm\\\" in str(type(self.model))\\n            is_t5 = \\\"t5\\\" in str(type(self.model))\\n            if is_llama:\\n                encoding = tokenizer.batch_encode_plus(\\n                    params[\\\"input\\\"], padding=True, return_tensors=\\\"pt\\\"\\n                )\\n                input_ids = encoding[\\\"input_ids\\\"].to(self.device)\\n                attention_mask = encoding[\\\"attention_mask\\\"].to(self.device)\\n                model_output = self.model(\\n                    input_ids, attention_mask, output_hidden_states=True\\n                )\\n                data = model_output.hidden_states[-1]\\n                mask = attention_mask.unsqueeze(-1).expand(data.size()).float()\\n                masked_embeddings = data * mask\\n                sum_embeddings = torch.sum(masked_embeddings, dim=1)\\n                seq_length = torch.sum(mask, dim=1)\\n                embedding = sum_embeddings / seq_length\\n                normalized_embeddings = F.normalize(embedding, p=2, dim=1)\\n                ret = {\\n                    \\\"embedding\\\": normalized_embeddings.tolist(),\\n                    \\\"token_num\\\": torch.sum(attention_mask).item(),\\n                }\\n            else:\\n                embedding = []\\n                token_num = 0\\n                for text in params[\\\"input\\\"]:\\n                    input_ids = tokenizer.encode(text, return_tensors=\\\"pt\\\").to(\\n                        self.device\\n                    )\\n                    if is_t5:\\n                        model_output = self.model(\\n                            input_ids, decoder_input_ids=input_ids\\n                        )\\n                    else:\\n                        model_output = self.model(input_ids, output_hidden_states=True)\\n                    if is_chatglm:\\n                        data = (model_output.hidden_states[-1].transpose(0, 1))[0]\\n                    elif is_t5:\\n                        data = model_output.encoder_last_hidden_state[0]\\n                    else:\\n                        data = model_output.hidden_states[-1][0]\\n                    data = F.normalize(torch.mean(data, dim=0), p=2, dim=0)\\n                    embedding.append(data.tolist())\\n                    token_num += len(input_ids[0])\\n                ret = {\\n                    \\\"embedding\\\": embedding,\\n                    \\\"token_num\\\": token_num,\\n                }\\n        except torch.cuda.OutOfMemoryError as e:\\n            ret = {\\n                \\\"text\\\": f\\\"{SERVER_ERROR_MSG}\\\\n\\\\n({e})\\\",\\n                \\\"error_code\\\": ErrorCode.CUDA_OUT_OF_MEMORY,\\n            }\\n        except (ValueError, RuntimeError) as e:\\n            ret = {\\n                \\\"text\\\": f\\\"{SERVER_ERROR_MSG}\\\\n\\\\n({e})\\\",\\n                \\\"error_code\\\": ErrorCode.INTERNAL_ERROR,\\n            }\\n        return ret\\n\\n\\ndef release_worker_semaphore():\\n    worker.semaphore.release()\\n\\n\\ndef acquire_worker_semaphore():\\n    if worker.semaphore is None:\\n        worker.semaphore = asyncio.Semaphore(worker.limit_worker_concurrency)\\n    return worker.semaphore.acquire()\\n\\n\\ndef create_background_tasks():\\n    background_tasks = BackgroundTasks()\\n    background_tasks.add_task(release_worker_semaphore)\\n    return background_tasks\\n\\n\\n@app.post(\\\"/worker_generate_stream\\\")\\nasync def api_generate_stream(request: Request):\\n    params = await request.json()\\n    await acquire_worker_semaphore()\\n    generator = worker.generate_stream_gate(params)\\n    background_tasks = create_background_tasks()\\n    return StreamingResponse(generator, background=background_tasks)\\n\\n\\n@app.post(\\\"/worker_generate\\\")\\nasync def api_generate(request: Request):\\n    params = await request.json()\\n    await acquire_worker_semaphore()\\n    output = worker.generate_gate(params)\\n    release_worker_semaphore()\\n    return JSONResponse(output)\\n\\n\\n@app.post(\\\"/worker_get_embeddings\\\")\\nasync def api_get_embeddings(request: Request):\\n    params = await request.json()\\n    await acquire_worker_semaphore()\\n    embedding = worker.get_embeddings(params)\\n    release_worker_semaphore()\\n    return JSONResponse(content=embedding)\\n\\n\\n@app.post(\\\"/worker_get_status\\\")\\nasync def api_get_status(request: Request):\\n    return worker.get_status()\\n\\n\\n@app.post(\\\"/count_token\\\")\\nasync def api_count_token(request: Request):\\n    params = await request.json()\\n    return worker.count_token(params)\\n\\n\\n@app.post(\\\"/worker_get_conv_template\\\")\\nasync def api_get_conv(request: Request):\\n    return worker.get_conv_template()\\n\\n\\n@app.post(\\\"/model_details\\\")\\nasync def api_model_details(request: Request):\\n    return {\\\"context_length\\\": worker.context_len}\\n\\n\\nif __name__ == \\\"__main__\\\":\\n    parser = argparse.ArgumentParser()\\n    parser.add_argument(\\\"--host\\\", type=str, default=\\\"localhost\\\")\\n    parser.add_argument(\\\"--port\\\", type=int, default=21002)\\n    parser.add_argument(\\\"--worker-address\\\", type=str, default=\\\"http://localhost:21002\\\")\\n    parser.add_argument(\\n        \\\"--controller-address\\\", type=str, default=\\\"http://localhost:21001\\\"\\n    )\\n    add_model_args(parser)\\n    parser.add_argument(\\n        \\\"--model-names\\\",\\n        type=lambda s: s.split(\\\",\\\"),\\n        help=\\\"Optional display comma separated names\\\",\\n    )\\n    parser.add_argument(\\n        \\\"--conv-template\\\", type=str, default=None, help=\\\"Conversation prompt template.\\\"\\n    )\\n    parser.add_argument(\\n        \\\"--limit-worker-concurrency\\\",\\n        type=int,\\n        default=5,\\n        help=\\\"Limit the model concurrency to prevent OOM.\\\",\\n    )\\n    parser.add_argument(\\\"--stream-interval\\\", type=int, default=2)\\n    parser.add_argument(\\\"--no-register\\\", action=\\\"store_true\\\")\\n    args = parser.parse_args()\\n    logger.info(f\\\"args: {args}\\\")\\n\\n    if args.gpus:\\n        if len(args.gpus.split(\\\",\\\")) < args.num_gpus:\\n            raise ValueError(\\n                f\\\"Larger --num-gpus ({args.num_gpus}) than --gpus {args.gpus}!\\\"\\n            )\\n        os.environ[\\\"CUDA_VISIBLE_DEVICES\\\"] = args.gpus\\n\\n    gptq_config = GptqConfig(\\n        ckpt=args.gptq_ckpt or args.model_path,\\n        wbits=args.gptq_wbits,\\n        groupsize=args.gptq_groupsize,\\n        act_order=args.gptq_act_order,\\n    )\\n\\n    worker = ModelWorker(\\n        args.controller_address,\\n        args.worker_address,\\n        worker_id,\\n        args.model_path,\\n        args.model_names,\\n        args.limit_worker_concurrency,\\n        no_register=args.no_register,\\n        device=args.device,\\n        num_gpus=args.num_gpus,\\n        max_gpu_memory=args.max_gpu_memory,\\n        load_8bit=args.load_8bit,\\n        cpu_offloading=args.cpu_offloading,\\n        gptq_config=gptq_config,\\n        stream_interval=args.stream_interval,\\n        conv_template=args.conv_template,\\n    )\\n    uvicorn.run(app, host=args.host, port=args.port, log_level=\\\"info\\\")\\n\"},{\"source_archive\":\"Unified_Psychiatric_AI_Brain_Part1.zip\",\"source_path\":\"source_projects/ChatPsychiatrist-master/ChatPsychiatrist-master/fastchat/utils.py\",\"language\":\"py\",\"content\":\"\\\"\\\"\\\"\\nCommon utilities.\\n\\\"\\\"\\\"\\nfrom asyncio import AbstractEventLoop\\nimport json\\nimport logging\\nimport logging.handlers\\nimport os\\nimport platform\\nimport sys\\nfrom typing import AsyncGenerator, Generator\\nimport warnings\\n\\nimport requests\\n\\nfrom fastchat.constants import LOGDIR\\n\\n\\nhandler = None\\nvisited_loggers = set()\\n\\n\\ndef build_logger(logger_name, logger_filename):\\n    global handler\\n\\n    formatter = logging.Formatter(\\n        fmt=\\\"%(asctime)s | %(levelname)s | %(name)s | %(message)s\\\",\\n        datefmt=\\\"%Y-%m-%d %H:%M:%S\\\",\\n    )\\n\\n    # Set the format of root handlers\\n    if not logging.getLogger().handlers:\\n        if sys.version_info[1] >= 9:\\n            # This is for windows\\n            logging.basicConfig(level=logging.INFO, encoding=\\\"utf-8\\\")\\n        else:\\n            if platform.system() == \\\"Windows\\\":\\n                warnings.warn(\\n                    \\\"If you are running on Windows, \\\"\\n                    \\\"we recommend you use Python >= 3.9 for UTF-8 encoding.\\\"\\n                )\\n            logging.basicConfig(level=logging.INFO)\\n    logging.getLogger().handlers[0].setFormatter(formatter)\\n\\n    # Redirect stdout and stderr to loggers\\n    stdout_logger = logging.getLogger(\\\"stdout\\\")\\n    stdout_logger.setLevel(logging.INFO)\\n    sl = StreamToLogger(stdout_logger, logging.INFO)\\n    sys.stdout = sl\\n\\n    stderr_logger = logging.getLogger(\\\"stderr\\\")\\n    stderr_logger.setLevel(logging.ERROR)\\n    sl = StreamToLogger(stderr_logger, logging.ERROR)\\n    sys.stderr = sl\\n\\n    # Get logger\\n    logger = logging.getLogger(logger_name)\\n    logger.setLevel(logging.INFO)\\n\\n    os.makedirs(LOGDIR, exist_ok=True)\\n    filename = os.path.join(LOGDIR, logger_filename)\\n    handler = logging.handlers.TimedRotatingFileHandler(\\n        filename, when=\\\"D\\\", utc=True, encoding=\\\"utf-8\\\"\\n    )\\n    handler.setFormatter(formatter)\\n\\n    for l in [stdout_logger, stderr_logger, logger]:\\n        if l in visited_loggers:\\n            continue\\n        visited_loggers.add(l)\\n        l.addHandler(handler)\\n\\n    return logger\\n\\n\\nclass StreamToLogger(object):\\n    \\\"\\\"\\\"\\n    Fake file-like stream object that redirects writes to a logger instance.\\n    \\\"\\\"\\\"\\n\\n    def __init__(self, logger, log_level=logging.INFO):\\n        self.terminal = sys.stdout\\n        self.logger = logger\\n        self.log_level = log_level\\n        self.linebuf = \\\"\\\"\\n\\n    def __getattr__(self, attr):\\n        return getattr(self.terminal, attr)\\n\\n    def write(self, buf):\\n        temp_linebuf = self.linebuf + buf\\n        self.linebuf = \\\"\\\"\\n        for line in temp_linebuf.splitlines(True):\\n            # From the io.TextIOWrapper docs:\\n            #   On output, if newline is None, any '\\\\n' characters written\\n            #   are translated to the system default line separator.\\n            # By default sys.stdout.write() expects '\\\\n' newlines and then\\n            # translates them so this is still cross platform.\\n            if line[-1] == \\\"\\\\n\\\":\\n                encoded_message = line.encode(\\\"utf-8\\\", \\\"ignore\\\").decode(\\\"utf-8\\\")\\n                self.logger.log(self.log_level, encoded_message.rstrip())\\n            else:\\n                self.linebuf += line\\n\\n    def flush(self):\\n        if self.linebuf != \\\"\\\":\\n            encoded_message = self.linebuf.encode(\\\"utf-8\\\", \\\"ignore\\\").decode(\\\"utf-8\\\")\\n            self.logger.log(self.log_level, encoded_message.rstrip())\\n        self.linebuf = \\\"\\\"\\n\\n\\ndef disable_torch_init():\\n    \\\"\\\"\\\"\\n    Disable the redundant torch default initialization to accelerate model creation.\\n    \\\"\\\"\\\"\\n    import torch\\n\\n    setattr(torch.nn.Linear, \\\"reset_parameters\\\", lambda self: None)\\n    setattr(torch.nn.LayerNorm, \\\"reset_parameters\\\", lambda self: None)\\n\\n\\ndef get_gpu_memory(max_gpus=None):\\n    \\\"\\\"\\\"Get available memory for each GPU.\\\"\\\"\\\"\\n    import torch\\n\\n    gpu_memory = []\\n    num_gpus = (\\n        torch.cuda.device_count()\\n        if max_gpus is None\\n        else min(max_gpus, torch.cuda.device_count())\\n    )\\n\\n    for gpu_id in range(num_gpus):\\n        with torch.cuda.device(gpu_id):\\n            device = torch.cuda.current_device()\\n            gpu_properties = torch.cuda.get_device_properties(device)\\n            total_memory = gpu_properties.total_memory / (1024**3)\\n            allocated_memory = torch.cuda.memory_allocated() / (1024**3)\\n            available_memory = total_memory - allocated_memory\\n            gpu_memory.append(available_memory)\\n    return gpu_memory\\n\\n\\ndef violates_moderation(text):\\n    \\\"\\\"\\\"\\n    Check whether the text violates OpenAI moderation API.\\n    \\\"\\\"\\\"\\n    import openai\\n\\n    try:\\n        flagged = openai.Moderation.create(input=text)[\\\"results\\\"][0][\\\"flagged\\\"]\\n    except openai.error.OpenAIError as e:\\n        flagged = False\\n    except (KeyError, IndexError) as e:\\n        flagged = False\\n\\n    return flagged\\n\\n\\ndef clean_flant5_ckpt(ckpt_path):\\n    \\\"\\\"\\\"\\n    Flan-t5 trained with HF+FSDP saves corrupted  weights for shared embeddings,\\n    Use this function to make sure it can be correctly loaded.\\n    \\\"\\\"\\\"\\n    import torch\\n\\n    index_file = os.path.join(ckpt_path, \\\"pytorch_model.bin.index.json\\\")\\n    index_json = json.load(open(index_file, \\\"r\\\"))\\n\\n    weightmap = index_json[\\\"weight_map\\\"]\\n\\n    share_weight_file = weightmap[\\\"shared.weight\\\"]\\n    share_weight = torch.load(os.path.join(ckpt_path, share_weight_file))[\\n        \\\"shared.weight\\\"\\n    ]\\n\\n    for weight_name in [\\\"decoder.embed_tokens.weight\\\", \\\"encoder.embed_tokens.weight\\\"]:\\n        weight_file = weightmap[weight_name]\\n        weight = torch.load(os.path.join(ckpt_path, weight_file))\\n        weight[weight_name] = share_weight\\n        torch.save(weight, os.path.join(ckpt_path, weight_file))\\n\\n\\ndef pretty_print_semaphore(semaphore):\\n    \\\"\\\"\\\"Print a semaphore in better format.\\\"\\\"\\\"\\n    if semaphore is None:\\n        return \\\"None\\\"\\n    return f\\\"Semaphore(value={semaphore._value}, locked={semaphore.locked()})\\\"\\n\\n\\n\\\"\\\"\\\"A javascript function to get url parameters for the gradio web server.\\\"\\\"\\\"\\nget_window_url_params_js = \\\"\\\"\\\"\\nfunction() {\\n    const params = new URLSearchParams(window.location.search);\\n    url_params = Object.fromEntries(params);\\n    console.log(\\\"url_params\\\", url_params);\\n    return url_params;\\n    }\\n\\\"\\\"\\\"\\n\\n\\ndef iter_over_async(\\n    async_gen: AsyncGenerator, event_loop: AbstractEventLoop\\n) -> Generator:\\n    \\\"\\\"\\\"\\n    Convert async generator to sync generator\\n\\n    :param async_gen: the AsyncGenerator to convert\\n    :param event_loop: the event loop to run on\\n    :returns: Sync generator\\n    \\\"\\\"\\\"\\n    ait = async_gen.__aiter__()\\n\\n    async def get_next():\\n        try:\\n            obj = await ait.__anext__()\\n            return False, obj\\n        except StopAsyncIteration:\\n            return True, None\\n\\n    while True:\\n        done, obj = event_loop.run_until_complete(get_next())\\n        if done:\\n            break\\n        yield obj\\n\\n\\ndef detect_language(text: str) -> str:\\n    \\\"\\\"\\\"Detect the langauge of a string.\\\"\\\"\\\"\\n    import polyglot  # pip3 install polyglot pyicu pycld2\\n    from polyglot.detect import Detector\\n    from polyglot.detect.base import logger as polyglot_logger\\n    import pycld2\\n\\n    polyglot_logger.setLevel(\\\"ERROR\\\")\\n\\n    try:\\n        lang_code = Detector(text).language.name\\n    except (pycld2.error, polyglot.detect.base.UnknownLanguage):\\n        lang_code = \\\"unknown\\\"\\n    return lang_code\\n\\n\\ndef parse_gradio_auth_creds(filename: str):\\n    \\\"\\\"\\\"Parse a username:password file for gradio authorization.\\\"\\\"\\\"\\n    gradio_auth_creds = []\\n    with open(filename, \\\"r\\\", encoding=\\\"utf8\\\") as file:\\n        for line in file.readlines():\\n            gradio_auth_creds += [x.strip() for x in line.split(\\\",\\\") if x.strip()]\\n    if gradio_auth_creds:\\n        auth = [tuple(cred.split(\\\":\\\")) for cred in gradio_auth_creds]\\n    else:\\n        auth = None\\n    return auth\\n\\n\\ndef is_partial_stop(output: str, stop_str: str):\\n    \\\"\\\"\\\"Check whether the output contains a partial stop str.\\\"\\\"\\\"\\n    for i in range(0, min(len(output), len(stop_str))):\\n        if stop_str.startswith(output[-i:]):\\n            return True\\n    return False\\n\\n\\ndef run_cmd(cmd: str):\\n    \\\"\\\"\\\"Run a bash command.\\\"\\\"\\\"\\n    print(cmd)\\n    return os.system(cmd)\\n\\n\\ndef is_sentence_complete(output: str):\\n    \\\"\\\"\\\"Check whether the output is a complete sentence.\\\"\\\"\\\"\\n    end_symbols = (\\\".\\\", \\\"?\\\", \\\"!\\\", \\\"...\\\", \\\"\u3002\\\", \\\"\uff1f\\\", \\\"\uff01\\\", \\\"\u2026\\\", '\\\"', \\\"'\\\", \\\"\u201d\\\")\\n    return output.endswith(end_symbols)\\n\\n\\n# Models don't use the same configuration key for determining the maximum\\n# sequence length.  Store them here so we can sanely check them.\\n# NOTE: The ordering here is important.  Some models have two of these and we\\n# have a preference for which value gets used.\\nSEQUENCE_LENGTH_KEYS = [\\n    \\\"max_sequence_length\\\",\\n    \\\"seq_length\\\",\\n    \\\"max_position_embeddings\\\",\\n    \\\"max_seq_len\\\",\\n    \\\"model_max_length\\\",\\n]\\n\\n\\ndef get_context_length(config):\\n    \\\"\\\"\\\"Get the context length of a model from a huggingface model config.\\\"\\\"\\\"\\n    for key in SEQUENCE_LENGTH_KEYS:\\n        val = getattr(config, key, None)\\n        if val is not None:\\n            return val\\n    return 2048\\n\"},{\"source_archive\":\"Unified_Psychiatric_AI_Brain_Part1.zip\",\"source_path\":\"source_projects/ChatPsychiatrist-master/ChatPsychiatrist-master/fastchat/data/clean_sharegpt.py\",\"language\":\"py\",\"content\":\"\\\"\\\"\\\"\\n- Convert html to markdown with basic data cleaning.\\n- Deduplication.\\n\\nUsage:\\npython3 -m fastchat.data.clean_sharegpt --in sharegpt_html.json --out sharegpt_clean.json\\n\\\"\\\"\\\"\\nimport argparse\\nfrom concurrent.futures import ProcessPoolExecutor\\nimport json\\nimport logging\\nimport re\\nfrom typing import Dict, Union\\n\\nimport bs4\\nimport markdownify  # == 0.11.6\\nfrom tqdm import tqdm\\n\\n\\ndiv_pattern = re.compile(\\\"<div.*?>\\\")\\nspan_pattern = re.compile(\\\"<span.*?>\\\")\\ncode_lang_pattern = re.compile(\\n    \\\"```\\\\s*\\\" + \\\"(.*?)\\\" + \\\"(?:Copy code)+\\\" + \\\"(.+?)\\\" + \\\"\\\\s*?```\\\", re.DOTALL\\n)\\ncode_lang_format = \\\"```\\\\g<1>\\\\n\\\\g<2>\\\\n```\\\"\\nregenerate_pattern = re.compile(\\\"\\\\d+ / \\\\d+\\\")\\ncopy_chars_pattern = re.compile(\\\"Copy\\\\d+ chars / \\\\d+ words\\\")\\ncopy_code_pattern = re.compile(\\\"```(.*?)Copy code\\\\s*```\\\")\\n\\n\\ndef reformat_code(val: str) -> str:\\n    # Input code format is:\\n    # ```\\n    # $<language>Copy code$<exact_code_here>\\n    #\\n    # ```\\n    # This function convert it into the correct markdown format\\n    return re.sub(code_lang_pattern, code_lang_format, val)\\n\\n\\ndef html_to_markdown(val: str) -> str:\\n    # Remove all <div>. This is required to make intent work in code blocks.\\n    val = re.sub(div_pattern, \\\"\\\", val)\\n    # Remove all <span>. This is required to make underscores work in code blocks.\\n    val = re.sub(span_pattern, \\\"\\\", val)\\n    # Markdown to html\\n    val = markdownify.markdownify(val).strip()\\n    # Reformat code\\n    val = reformat_code(val)\\n\\n    # Remove noisy \\\"[number] / [number]\\\" at the beginning\\n    noise = re.search(regenerate_pattern, val)\\n    if noise and noise.start() == 0:\\n        val = val[noise.end() :]\\n    # Remove noisy \\\"Copy[number] chars / [number] words\\\"\\n    val = re.sub(copy_chars_pattern, \\\"\\\", val)\\n    # Remove empty code block ```\\\\nCopy code\\\\n```\\n    val = re.sub(copy_code_pattern, \\\"\\\", val)\\n\\n    # Strip\\n    val = val.replace(\\\"\\\\n\\\\n\\\\n\\\", \\\"\\\\n\\\").strip()\\n\\n    return val\\n\\n\\ndef contain_blocked_words(val: str) -> bool:\\n    blocked_words = [\\\"openai\\\", \\\"chatgpt\\\"]\\n    for w in blocked_words:\\n        if w in val.lower():\\n            return True\\n    return False\\n\\n\\ndef clean_html_one_sample(sample):\\n    roles = [\\\"human\\\", \\\"gpt\\\"]\\n\\n    if len(sample[\\\"conversations\\\"]) <= 1:\\n        return (sample, 1)\\n\\n    # Adjust the offset for cases like https://sharegpt.com/c/VyaZlh4\\n    if sample[\\\"conversations\\\"][0][\\\"from\\\"] != \\\"human\\\":\\n        sample[\\\"conversations\\\"] = sample[\\\"conversations\\\"][1:]\\n    if len(sample[\\\"conversations\\\"]) <= 1:\\n        return (sample, 1)\\n\\n    if sample[\\\"conversations\\\"][-1][\\\"from\\\"] == \\\"human\\\":\\n        sample[\\\"conversations\\\"] = sample[\\\"conversations\\\"][:-1]\\n    if len(sample[\\\"conversations\\\"]) <= 1:\\n        return (sample, 1)\\n\\n    char_count = 0\\n    new_conversations = []\\n    for i, c in enumerate(sample[\\\"conversations\\\"]):\\n        if c[\\\"from\\\"] != roles[i % 2]:\\n            return (sample, 2)\\n\\n        if contain_blocked_words(c[\\\"value\\\"]):\\n            return (sample, 3)\\n\\n        try:\\n            new_val = html_to_markdown(c[\\\"value\\\"])\\n        except (bs4.builder.ParserRejectedMarkup, AssertionError):\\n            return (sample, 4)\\n\\n        # Filter empty answers like https://sharegpt.com/c/mrllZ6u\\n        if not new_val or not new_val[0].isprintable():\\n            break\\n\\n        char_count += len(new_val)\\n        new_conversations.append(\\n            {\\n                \\\"from\\\": c[\\\"from\\\"],\\n                \\\"value\\\": new_val,\\n            }\\n        )\\n\\n    new_conversations = new_conversations[: len(new_conversations) // 2 * 2]\\n    sample[\\\"conversations\\\"] = new_conversations\\n\\n    if char_count < 16 or len(sample[\\\"conversations\\\"]) <= 0:\\n        return (sample, 1)\\n\\n    return (sample, 0)\\n\\n\\ndef clean_html_all(content, begin, end):\\n    \\\"\\\"\\\"\\n    Clean the source html files.\\n    \\\"\\\"\\\"\\n    cnt_skip = 0\\n    cnt_blocked_words = 0\\n    cnt_wrong_format = 0\\n    cnt_parser_error = 0\\n    cnt_";
